-- Clear existing scenarios for clean 300-question seed

DELETE FROM public.scenarios;



-- Batch for Class 3 (30 questions)
INSERT INTO public.scenarios (
  scenario_code, class_level, developmental_band, competency, difficulty,
  prompt, options, learning_objective, hint, irt_a, irt_b, irt_c,
  international_benchmark, is_active
) VALUES
  ('C03-SCI-01', 3, '3-4', 'scientificInquiry', 'standard', 'A student puts an ice cube on a plate in the warm sun and another ice cube on a plate inside a refrigerator. After 10 minutes, the ice cube in the sun has completely melted into a puddle, while the ice in the refrigerator has barely changed. What is the cause of this difference?', '[{"text":"Thermal energy from the sun transferred heat to the ice, causing it to change state from solid to liquid faster.","correct":true},{"text":"The refrigerator creates new cold ice to replace what melted.","correct":false},{"text":"Sunlight absorbs water from the air and adds it to the plate.","correct":false},{"text":"Ice only melts when it is touched by moving air.","correct":false}]'::jsonb, 'States of matter and heat energy transfer causing phase changes.', 'Think about where the temperature is higher and heat is flowing into the ice.', 1.1, -1.8, 0.25, 'Singapore Primary 3 Science / US NGSS 2-PS1-4', true),
  ('C03-SCI-02', 3, '3-4', 'scientificInquiry', 'standard', 'A student tests which objects are attracted to a bar magnet. The magnet attracts an iron nail and a steel paperclip, but does not attract a copper penny, a plastic ruler, or an aluminum soda can. What conclusion can be drawn from this test?', '[{"text":"Only certain metals, such as iron and steel, exhibit magnetic attraction.","correct":true},{"text":"All shiny metal objects are strongly attracted to magnets.","correct":false},{"text":"The magnet was not strong enough to pick up the lighter objects.","correct":false},{"text":"Only objects shaped like thin rods can be attracted to magnets.","correct":false}]'::jsonb, 'Magnetic properties of materials and distinguishing ferromagnetic from non-magnetic metals.', 'Notice that copper and aluminum are metals, yet they did not stick to the magnet.', 1.2, -1.5, 0.25, 'Cambridge Primary Science Stage 3', true),
  ('C03-SCI-03', 3, '3-4', 'scientificInquiry', 'advanced', 'At 8:00 AM, a vertical pole casts a long shadow pointing west. At 12:00 noon, its shadow is very short and points north. At 4:00 PM, the shadow is long again and points east. What causes this continuous change in the shadow?', '[{"text":"Earth rotates on its axis, causing the sun to appear to move across the sky from east to west.","correct":true},{"text":"The sun physically grows larger and hotter during the middle of the day.","correct":false},{"text":"The pole bends as the temperature changes throughout the day.","correct":false},{"text":"Clouds push the sunlight in different directions as the wind blows.","correct":false}]'::jsonb, 'Sun position and shadow geometry caused by Earth rotation.', 'Shadows always fall in the direction opposite to where the light source is located.', 1.3, -1.1, 0.25, 'TIMSS Grade 4 Science / UK Key Stage 2', true),
  ('C03-SCI-04', 3, '3-4', 'scientificInquiry', 'advanced', 'A student places a dry sponge in a bowl with 100 mL of blue water. When the sponge is lifted out, only 30 mL of water remains in the bowl. The mass of the sponge increased by exactly 70 grams. What scientific principle does this demonstrate?', '[{"text":"Conservation of mass: the 70 mL of absorbed water was taken up by the porous sponge.","correct":true},{"text":"Water disappeared because the sponge destroyed liquid matter.","correct":false},{"text":"The blue dye evaporated instantly into the surrounding air.","correct":false},{"text":"The sponge grew heavier because water created new sponge fibers.","correct":false}]'::jsonb, 'Porosity, absorption, and mass conservation in physical mixtures.', 'Remember that 1 mL of water has a mass of approximately 1 gram.', 1.35, -0.8, 0.25, 'US NGSS 5-PS1-2 / Singapore Primary 3', true),
  ('C03-SCI-05', 3, '3-4', 'scientificInquiry', 'olympiad', 'A student drops three identical rubber balls from 1 meter height onto three surfaces: thick carpet, polished wood, and soft sand. The ball bounces 10 cm on carpet, 65 cm on wood, and 2 cm on sand. Why does the polished wood produce the highest bounce?', '[{"text":"The rigid wood deforms very little, returning most of the ball’s kinetic energy during the collision rather than absorbing it.","correct":true},{"text":"Wood possesses a natural magnetic charge that pushes rubber upward.","correct":false},{"text":"Soft sand adds gravity to the ball, preventing it from rising.","correct":false},{"text":"The carpet creates a vacuum that holds the ball down.","correct":false}]'::jsonb, 'Elastic collisions, energy dissipation, and surface rigidity.', 'Think about where the energy goes when an object hits a soft, shifting surface versus a hard one.', 1.5, -0.4, 0.25, 'SASMO Primary Science / Primary Olympiad', true),
  ('C03-SCI-06', 3, '3-4', 'scientificInquiry', 'olympiad', 'Two identical sealed glass jars contain water. Jar 1 is filled with cold ice water (4°C); Jar 2 is filled with warm water (40°C). After 5 minutes in a warm room, tiny water droplets form on the OUTSIDE of Jar 1, but the outside of Jar 2 stays completely dry. Where did the droplets on Jar 1 come from?', '[{"text":"Invisible water vapor in the surrounding air cooled and condensed into liquid when touching the cold glass.","correct":true},{"text":"Water leaked through tiny microscopic holes in the glass of Jar 1.","correct":false},{"text":"The cold glass produced water molecules from its own silica atoms.","correct":false},{"text":"The ice inside Jar 1 expanded so much that it pushed water outward.","correct":false}]'::jsonb, 'Atmospheric humidity, dew point, and condensation phase transition.', 'The jar is completely sealed, so the water must come from the air around it.', 1.6, 0, 0.25, 'Singapore Primary Science Olympiad', true),
  ('C03-CT-01', 3, '3-4', 'computationalThinking', 'standard', 'A robotic toy car starts at square (1, 1) on a grid facing North. It executes these instructions: [MOVE FORWARD 2, TURN RIGHT 90°, MOVE FORWARD 3]. At what grid position does the car stop?', '[{"text":"Square (4, 3)","correct":true},{"text":"Square (2, 3)","correct":false},{"text":"Square (3, 4)","correct":false},{"text":"Square (1, 5)","correct":false}]'::jsonb, 'Grid coordinates, directional heading, and sequential instruction execution.', 'Moving North increases the vertical coordinate; turning right makes it face East, increasing the horizontal coordinate.', 1.1, -1.7, 0.25, 'Bebras Computational Thinking Primary / Scratch Junior', true),
  ('C03-CT-02', 3, '3-4', 'computationalThinking', 'standard', 'Look at this repeating pattern of shapes: [Circle, Triangle, Square, Circle, Triangle, Square, Circle, Triangle, ...]. What shape will appear at the 15th position in this sequence?', '[{"text":"Square, because 15 is a multiple of 3 and Square is the 3rd shape in the repeating cycle.","correct":true},{"text":"Circle, because odd numbers always get circles.","correct":false},{"text":"Triangle, because it is in the middle of the pattern.","correct":false},{"text":"Star, because new shapes enter after position 10.","correct":false}]'::jsonb, 'Pattern recognition, modular repeating periods, and discrete arithmetic.', 'Divide the position number by the length of the repeating group (3 shapes).', 1.2, -1.4, 0.25, 'European Bebras Challenge Class 3', true),
  ('C03-CT-03', 3, '3-4', 'computationalThinking', 'advanced', 'A computer rule sorts fruit into baskets: "IF color is RED AND shape is ROUND, put in Basket 1; ELSE put in Basket 2." Where will a green round lime and a red long chili pepper be placed?', '[{"text":"Both the lime and the chili will go to Basket 2 because neither satisfies both conditions at once.","correct":true},{"text":"The lime goes to Basket 1 and the chili to Basket 2.","correct":false},{"text":"Both go to Basket 1 because each has at least one matching property.","correct":false},{"text":"The computer stops and reports an error.","correct":false}]'::jsonb, 'Boolean logical conjunction (AND) and conditional branch execution.', 'The word AND means both conditions must be true at the same time.', 1.35, -0.9, 0.25, 'Oxford University Computing Challenge (OUCC) Junior', true),
  ('C03-CT-04', 3, '3-4', 'computationalThinking', 'advanced', 'A baker has a loop program: [SET count = 0; REPEAT 4 TIMES: {ADD 3 cookies, SET count = count + 3}]. At the end of the loop, what is the final value of count?', '[{"text":"12 cookies","correct":true},{"text":"7 cookies","correct":false},{"text":"9 cookies","correct":false},{"text":"4 cookies","correct":false}]'::jsonb, 'Loop iteration, variable accumulation, and state tracing.', 'The loop runs 4 times, adding 3 each time: 3 + 3 + 3 + 3.', 1.4, -0.6, 0.25, 'Code.org Course B / CSTA K-2 Algorithms', true),
  ('C03-CT-05', 3, '3-4', 'computationalThinking', 'olympiad', 'A squirrel needs to cross a 4x4 stone pond. It can only hop RIGHT or UP. If stone (2, 2) is broken and cannot be stepped on, how many safe paths can the squirrel take from bottom-left (1, 1) to top-right (4, 4)?', '[{"text":"14 safe paths (total paths = 20; paths through (2, 2) = 2 × 3 = 6; 20 - 6 = 14).","correct":true},{"text":"20 safe paths","correct":false},{"text":"10 safe paths","correct":false},{"text":"16 safe paths","correct":false}]'::jsonb, 'Grid path enumeration with topological obstacles and combinatorial subtraction.', 'Count the total ways to navigate a 3-step by 3-step grid, then subtract the paths that pass through the broken stone.', 1.6, -0.1, 0.25, 'Australian Informatics Competition (AIC) Primary', true),
  ('C03-CT-06', 3, '3-4', 'computationalThinking', 'olympiad', 'Five children stand in line with heights: [120 cm, 135 cm, 110 cm, 140 cm, 125 cm]. An algorithm swaps adjacent neighbors that are in the wrong order until the line is sorted from shortest to tallest. What is the MINIMUM number of swaps needed?', '[{"text":"4 swaps (inversions count: (135,110), (120,110) doesn''t invert, (135,125), (140,125) etc.)","correct":true},{"text":"2 swaps","correct":false},{"text":"7 swaps","correct":false},{"text":"5 swaps","correct":false}]'::jsonb, 'Inversion counting and elementary bubble-sort swap metrics.', 'Count how many pairs of children have the taller child standing ahead of the shorter child.', 1.65, 0.2, 0.25, 'Bebras Castor Benjamin Olympiad', true),
  ('C03-ED-01', 3, '3-4', 'engineeringDesign', 'standard', 'Two children want to play on a playground seesaw. Child A weighs 30 kg and Child B weighs 15 kg. When Child A sits at the far end, Child B cannot push their side down. Where should Child A sit to balance the seesaw?', '[{"text":"Move closer to the center pivot (fulcrum), decreasing their turning force (torque).","correct":true},{"text":"Move further backward off the edge of the seat.","correct":false},{"text":"Wear heavier boots.","correct":false},{"text":"Stand up and jump continuously on the seat.","correct":false}]'::jsonb, 'First-class levers, fulcrum positioning, and rotational equilibrium.', 'To balance a lighter person, a heavier person needs to sit closer to the middle.', 1.15, -1.7, 0.25, 'US NGSS K-2-ETS1 / Singapore Primary 3', true),
  ('C03-ED-02', 3, '3-4', 'engineeringDesign', 'standard', 'A student builds a tall tower out of wooden blocks, but whenever someone bumps the table, the tower falls over immediately. Which modification will make the tower most stable?', '[{"text":"Widen the bottom base and place the heaviest blocks at the bottom to lower the center of gravity.","correct":true},{"text":"Make the tower narrower and twice as tall.","correct":false},{"text":"Put the heaviest blocks at the very top.","correct":false},{"text":"Paint the blocks with glossy paint.","correct":false}]'::jsonb, 'Structural stability, base-to-height ratio, and center of mass.', 'A pyramid is much harder to tip over than a tall, thin stick.', 1.25, -1.4, 0.25, 'Cambridge Primary Design & Technology', true),
  ('C03-ED-03', 3, '3-4', 'engineeringDesign', 'advanced', 'An engineer designs a ramp for rolling heavy boxes onto a truck bed that is 1 meter high. Ramp A is 2 meters long; Ramp B is 4 meters long. How does using Ramp B compare to Ramp A?', '[{"text":"Ramp B requires half as much pushing force, but the box must be pushed twice as far.","correct":true},{"text":"Ramp B requires twice as much pushing force because it is longer.","correct":false},{"text":"Both ramps require the exact same pushing force and distance.","correct":false},{"text":"Ramp B makes the box lighter on the scale.","correct":false}]'::jsonb, 'Inclined plane mechanical advantage and force-distance trade-off.', 'A gentler slope is easier to push up, but you have to walk further.', 1.4, -0.8, 0.25, 'Project Lead The Way (PLTW) Elementary', true),
  ('C03-ED-04', 3, '3-4', 'engineeringDesign', 'advanced', 'A team designs a handheld flashlight. They have a battery, a bulb, and insulated copper wires. When they connect wire from battery (+) to the bulb, the bulb does not light. What missing engineering requirement explains this?', '[{"text":"An electric circuit must be a complete closed loop returning to the battery (-) terminal for current to flow.","correct":true},{"text":"The bulb needs to be warmed up with a lighter first.","correct":false},{"text":"Electricity can only travel through glass tubes, not copper wires.","correct":false},{"text":"Batteries only produce power when placed upside down.","correct":false}]'::jsonb, 'Closed electrical circuit continuity and conductor pathway requirements.', 'Electricity must have a complete path to leave the battery and return to it.', 1.45, -0.5, 0.25, 'UK Key Stage 2 Science & Design', true),
  ('C03-ED-05', 3, '3-4', 'engineeringDesign', 'olympiad', 'To cross a 30 cm gap between two desks, students build a bridge using only one sheet of paper (20 cm × 30 cm) and 10 paper clips. A flat sheet immediately sags and collapses under its own weight. What folding technique gives paper the highest structural bending strength?', '[{"text":"Folding the paper into accordion pleats (corrugation), which increases the vertical depth of the cross-section.","correct":true},{"text":"Rolling the paper into a tight flat square.","correct":false},{"text":"Tearing the paper into thin confetti strips.","correct":false},{"text":"Soaking the paper in water before placing it.","correct":false}]'::jsonb, 'Corrugation, second moment of area, and structural geometry in thin materials.', 'Think about cardboard boxes: what is inside the walls of strong cardboard?', 1.6, -0.1, 0.25, 'FIRST LEGO League Junior Engineering Challenge', true),
  ('C03-ED-06', 3, '3-4', 'engineeringDesign', 'olympiad', 'A model water turbine uses falling water to spin a paddle wheel that lifts a small weight. If the water tank height is raised from 20 cm to 80 cm above the wheel, how does the gravitational potential energy of the falling water change?', '[{"text":"It quadruples (increases by a factor of 4), because potential energy is directly proportional to fall height ($PE = mgh$).","correct":true},{"text":"It doubles (increases by a factor of 2).","correct":false},{"text":"It remains unchanged because the volume of water is the same.","correct":false},{"text":"It decreases because water takes longer to reach the bottom.","correct":false}]'::jsonb, 'Gravitational potential energy scaling with height ($PE = mgh$).', '80 cm is 4 times higher than 20 cm.', 1.7, 0.2, 0.25, 'Singapore Primary Science & Engineering Challenge', true),
  ('C03-MR-01', 3, '3-4', 'mathematicalReasoning', 'standard', 'A school garden has a rectangular vegetable patch that is 6 meters long and 4 meters wide. The class wants to build a wooden border along all four sides. What is the total perimeter of the patch?', '[{"text":"20 meters ($6 + 4 + 6 + 4 = 20$ m)","correct":true},{"text":"24 meters ($6 \\times 4 = 24$ m)","correct":false},{"text":"10 meters ($6 + 4 = 10$ m)","correct":false},{"text":"16 meters","correct":false}]'::jsonb, 'Perimeter calculation of rectangles as sum of all four boundary sides.', 'Add the lengths of all four outer edges.', 1.1, -1.8, 0.25, 'Singapore Primary Math 3A / US Common Core 3.MD.D.8', true),
  ('C03-MR-02', 3, '3-4', 'mathematicalReasoning', 'standard', 'Maya baked 24 muffins. She gave 1/4 of them to her neighbor and divided the remaining muffins equally among 3 friends. How many muffins did each friend receive?', '[{"text":"6 muffins (24 - 6 = 18 remaining; 18 ÷ 3 = 6)","correct":true},{"text":"8 muffins","correct":false},{"text":"4 muffins","correct":false},{"text":"5 muffins","correct":false}]'::jsonb, 'Multi-step arithmetic combining unit fractions and equal sharing division.', 'First find 1/4 of 24, subtract that from 24, then divide what is left by 3.', 1.25, -1.3, 0.25, 'Kangaroo Math Benjamin Level / SASMO Grade 3', true),
  ('C03-MR-03', 3, '3-4', 'mathematicalReasoning', 'advanced', 'A clock shows 2:15 PM. If a train journey takes 2 hours and 50 minutes, what time will the train arrive at its destination?', '[{"text":"5:05 PM (2:15 + 2h = 4:15; 4:15 + 45m = 5:00; + 5m = 5:05 PM)","correct":true},{"text":"4:65 PM","correct":false},{"text":"5:15 PM","correct":false},{"text":"4:55 PM","correct":false}]'::jsonb, 'Elapsed time addition with sexagesimal (base-60) minute rollover.', 'There are 60 minutes in an hour, so adding 50 minutes to 15 minutes rolls past the next hour.', 1.35, -0.8, 0.25, 'TIMSS Grade 4 Mathematics', true),
  ('C03-MR-04', 3, '3-4', 'mathematicalReasoning', 'advanced', 'A mystery number has 3 digits: the hundreds digit is 4, the tens digit is double the hundreds digit, and the ones digit is 3 less than the tens digit. What is the mystery number?', '[{"text":"485 (Hundreds = 4, Tens = 8, Ones = 5)","correct":true},{"text":"425","correct":false},{"text":"488","correct":false},{"text":"463","correct":false}]'::jsonb, 'Place value decoding and relational deductive constraints.', 'Double of 4 is 8; 8 minus 3 is 5.', 1.45, -0.4, 0.25, 'Australian Mathematics Competition (AMC) Middle Primary', true),
  ('C03-MR-05', 3, '3-4', 'mathematicalReasoning', 'olympiad', 'In a farmyard there are chickens (2 legs each) and rabbits (4 legs each). Counting heads gives 10 heads; counting feet gives 28 feet. How many rabbits are in the farmyard?', '[{"text":"4 rabbits (and 6 chickens: 4 × 4 + 6 × 2 = 16 + 12 = 28 feet)","correct":true},{"text":"6 rabbits","correct":false},{"text":"5 rabbits","correct":false},{"text":"3 rabbits","correct":false}]'::jsonb, 'Simultaneous linear constraint problem solving via assumption heuristic.', 'If all 10 animals were chickens, there would only be 20 legs. Each rabbit adds 2 extra legs.', 1.6, 0, 0.25, 'SASMO Primary 3 / Singapore Heuristic Problem Solving', true),
  ('C03-MR-06', 3, '3-4', 'mathematicalReasoning', 'olympiad', 'How many triangles of any size are there in a large equilateral triangle divided into 4 small identical equilateral triangles by joining the midpoints of its three sides?', '[{"text":"5 triangles (4 small triangles + 1 large outer triangle)","correct":true},{"text":"4 triangles","correct":false},{"text":"6 triangles","correct":false},{"text":"8 triangles","correct":false}]'::jsonb, 'Systematic geometric shape enumeration and nested figure counting.', 'Count the small individual triangles first, and do not forget the large surrounding triangle.', 1.65, 0.3, 0.25, 'Kangaroo Math Ecolier / Bebras Junior', true),
  ('C03-ST-01', 3, '3-4', 'systemsThinking', 'standard', 'In a school garden ecosystem: Sunflowers provide seeds for sparrows, and sparrows are hunted by garden hawks. If a disease eliminates all the sparrows, what is the immediate expected effect on the hawks and the sunflowers?', '[{"text":"Hawks will face a food shortage, while sunflower seeds will accumulate with fewer birds eating them.","correct":true},{"text":"Hawks will immediately start eating sunflower leaves.","correct":false},{"text":"Sunflowers will stop growing flowers entirely.","correct":false},{"text":"All organisms in the garden will double within one day.","correct":false}]'::jsonb, 'Linear trophic cascade and primary consumer disruption in simple food chains.', 'Trace who eats whom: if the middle animal vanishes, what happens to the predator and the food source?', 1.15, -1.7, 0.25, 'UNESCO Primary Science Indicators / OECD PISA Primary', true),
  ('C03-ST-02', 3, '3-4', 'systemsThinking', 'standard', 'On a sunny day after rain, a large puddle on asphalt disappears by afternoon even though no drain exists. Where did the water in the puddle go?', '[{"text":"The liquid water absorbed heat energy and evaporated into invisible water vapor gas in the atmosphere.","correct":true},{"text":"The asphalt soaked up all the water and turned into a solid sponge.","correct":false},{"text":"Car tires drank the water to stay cool.","correct":false},{"text":"The water was destroyed by sunlight.","correct":false}]'::jsonb, 'Hydrological cycle phase change and atmospheric water reservoir transfer.', 'Water does not disappear from the universe; it changes into an invisible gas in the air.', 1.25, -1.4, 0.25, 'TIMSS Grade 4 Earth Science', true),
  ('C03-ST-03', 3, '3-4', 'systemsThinking', 'advanced', 'A classroom has an aquarium with fish and live green plants. If the teacher moves the aquarium into a completely dark room for two weeks, why do the fish begin to struggle for breath even though they have food?', '[{"text":"Without sunlight, plants cannot perform photosynthesis to produce dissolved oxygen for the fish to breathe.","correct":true},{"text":"Fish are afraid of the dark and stop swimming.","correct":false},{"text":"Water freezes solid in darkness within hours.","correct":false},{"text":"Fish food only dissolves when bright light shines on it.","correct":false}]'::jsonb, 'Interdependent closed-loop gas exchange (O2 and CO2) in aquatic ecosystems.', 'Plants need light to make oxygen for fish to breathe underwater.', 1.35, -0.8, 0.25, 'US NGSS 5-LS2-1 Ecosystem Interdependence', true),
  ('C03-ST-04', 3, '3-4', 'systemsThinking', 'advanced', 'A town builds a new asphalt parking lot where a grassy meadow used to be. During the next heavy thunderstorm, the street next to the parking lot floods severely. Why did replacing grass with asphalt cause flooding?', '[{"text":"Grass and soil absorb and slow down rainwater infiltration, whereas impermeable asphalt forces all rainwater to rush immediately into the street.","correct":true},{"text":"Asphalt attracts more rain clouds from the sky.","correct":false},{"text":"Cars parked on the lot push water upward with their tires.","correct":false},{"text":"Asphalt melts in rainwater, blocking storm pipes.","correct":false}]'::jsonb, 'Surface permeability, storm runoff kinetics, and human-altered urban drainage systems.', 'Water can soak into dirt and grass, but it rolls straight off smooth pavement.', 1.45, -0.4, 0.25, 'OECD PISA Environmental Systems / UNESCO SDG 11', true),
  ('C03-ST-05', 3, '3-4', 'systemsThinking', 'olympiad', 'A honeybee visits flowers to collect nectar, and pollen grains stick to its fuzzy body and transfer to the next flower. Both the bee and the flowering plant benefit. What systemic ecological relationship is this?', '[{"text":"Mutualism: a symbiotic co-dependent feedback loop where both species enhance each other’s survival and reproduction.","correct":true},{"text":"Parasitism: where the bee steals resources and damages the flower.","correct":false},{"text":"Predation: where the flower captures and digests the bee.","correct":false},{"text":"Competition: where the bee and flower fight for the same sunlight.","correct":false}]'::jsonb, 'Symbiotic mutualism, plant-pollinator co-evolution, and positive ecological feedback.', 'Both living things gain something essential: food for the bee, reproduction for the plant.', 1.6, 0.1, 0.25, 'Singapore Primary Science Olympiad / SASMO Junior', true),
  ('C03-ST-06', 3, '3-4', 'systemsThinking', 'olympiad', 'In a mechanical grandfather clock, a falling weight pulls a chain that turns gear wheels, but an escapement mechanism allows the gears to turn only one tooth every second with a swinging pendulum. What is the function of the escapement in this system?', '[{"text":"It acts as a feedback governor, regulating the release of stored potential energy into precise, constant time intervals.","correct":true},{"text":"It winds the clock weight back up to the top automatically.","correct":false},{"text":"It stops the clock from making ticking sounds.","correct":false},{"text":"It creates electricity to power digital numbers.","correct":false}]'::jsonb, 'Systemic energy regulation, escapement governance, and clockwork mechanical feedback.', 'Without this part, the weight would fall to the floor in one second and spin the hands wildly.', 1.65, 0.35, 0.25, 'Cambridge Primary STEM / ISEC Systems Design', true);


-- Batch for Class 4 (30 questions)
INSERT INTO public.scenarios (
  scenario_code, class_level, developmental_band, competency, difficulty,
  prompt, options, learning_objective, hint, irt_a, irt_b, irt_c,
  international_benchmark, is_active
) VALUES
  ('C04-SCI-01', 4, '3-4', 'scientificInquiry', 'standard', 'A student places 10 bean seeds on wet cotton in a warm room (22°C) and 10 identical seeds on wet cotton inside a cold refrigerator (4°C). After 5 days, all 10 seeds in the warm room sprouted roots, while none of the seeds in the refrigerator sprouted. What was the independent variable in this test?', '[{"text":"The temperature of the environment.","correct":true},{"text":"The amount of wet cotton.","correct":false},{"text":"The number of sprouted roots.","correct":false},{"text":"The species of bean seeds.","correct":false}]'::jsonb, 'Identification of manipulated independent variables in seed germination experiments.', 'The independent variable is the one condition that the experimenter deliberately changed between the two groups.', 1.2, -1.6, 0.25, 'US NGSS 4-LS1-1 / Singapore Primary 4', true),
  ('C04-SCI-02', 4, '3-4', 'scientificInquiry', 'standard', 'A student shines a narrow beam of flashlight onto three materials: clear plastic wrap, frosted wax paper, and thick cardboard. The plastic allows light to pass clearly; the wax paper scatters light into a soft blur; the cardboard blocks light completely and casts a dark shadow. How are these three materials classified?', '[{"text":"Transparent (clear plastic), Translucent (wax paper), and Opaque (cardboard).","correct":true},{"text":"Reflective, Refractive, and Absorptive.","correct":false},{"text":"Magnetic, Conductive, and Insulating.","correct":false},{"text":"Solid, Liquid, and Gas.","correct":false}]'::jsonb, 'Optical transmission properties: transparent, translucent, and opaque categorization.', 'Transparent means see-through; translucent scatters light; opaque blocks all light.', 1.25, -1.3, 0.25, 'Cambridge Primary Science Stage 4', true),
  ('C04-SCI-03', 4, '3-4', 'scientificInquiry', 'advanced', 'A student plucks a stretched guitar string and listens to the pitch. When the string is tightened using the tuning peg, the pitch of the sound becomes higher. Why does tightening the string raise the pitch?', '[{"text":"Greater tension makes the string vibrate with higher frequency (more vibrations per second).","correct":true},{"text":"Tension makes the sound travel faster through the wooden body.","correct":false},{"text":"Tight strings absorb more air molecules.","correct":false},{"text":"Tension makes the string longer and heavier.","correct":false}]'::jsonb, 'Sound wave production, vibration frequency, and string tension dynamics.', 'Pitch depends on how fast an object vibrates back and forth.', 1.35, -0.9, 0.25, 'TIMSS Grade 4 Physical Science', true),
  ('C04-SCI-04', 4, '3-4', 'scientificInquiry', 'advanced', 'Three soil samples (Sandy Soil, Garden Loam, and Heavy Clay) are placed in funnels. 100 mL of water is poured onto each. After 5 minutes, 85 mL dripped through the sand, 45 mL through the loam, and only 10 mL through the clay. Which soil is best suited for plants that need moist soil without drying out quickly?', '[{"text":"Garden loam, because it retains moderate moisture while still allowing adequate drainage.","correct":true},{"text":"Sandy soil, because all the water quickly drains away.","correct":false},{"text":"Clay, because it creates waterlogged puddles that suffocate root oxygen.","correct":false},{"text":"None of the soils can support plant roots.","correct":false}]'::jsonb, 'Soil porosity, permeability, and water retention capacity.', 'Loam balances water retention with drainage so roots neither drown nor dry out.', 1.4, -0.5, 0.25, 'Singapore Primary 4 Science Syllabus', true),
  ('C04-SCI-05', 4, '3-4', 'scientificInquiry', 'olympiad', 'An Arctic hare has brown fur during the warm summer months and sheds its coat to grow pure white fur in the winter. What type of adaptation is this and what primary survival advantage does it confer?', '[{"text":"A seasonal camouflage adaptation that conceals the hare from predators against snow and rocky ground.","correct":true},{"text":"A behavioral adaptation to attract migrating birds.","correct":false},{"text":"A disease caused by cold winter wind.","correct":false},{"text":"An adaptation to absorb maximum sunlight during dark winter days.","correct":false}]'::jsonb, 'Seasonal physiological camouflage and natural selection predator-prey adaptations.', 'White fur blends in with snow, while brown fur blends in with summer dirt and rocks.', 1.55, -0.1, 0.25, 'Australian Science Innovations Primary Challenge', true),
  ('C04-SCI-06', 4, '3-4', 'scientificInquiry', 'olympiad', 'A syringe with its tip sealed by a rubber stopper contains 50 mL of air. When the plunger is pushed hard with a thumb, the air compresses to 30 mL. When the thumb is released, the plunger springs back to 50 mL. What does this demonstrate about gases compared to liquids?', '[{"text":"Gas molecules have large empty spaces between them and can be compressed, exerting pressure that pushes back.","correct":true},{"text":"Air molecules shrink in size when compressed.","correct":false},{"text":"Air destroyed its own mass and then recreated it.","correct":false},{"text":"Liquids can be compressed much more easily than gases.","correct":false}]'::jsonb, 'Kinetic particle model of gases, compressibility, and pneumatic elasticity.', 'Particles in a gas are far apart with lots of empty space between them.', 1.65, 0.25, 0.25, 'Singapore Primary Science Olympiad (SPSO)', true),
  ('C04-CT-01', 4, '3-4', 'computationalThinking', 'standard', 'A robot is positioned at (0, 0) facing East on a 2D coordinate grid. It executes: [FORWARD 4, TURN LEFT 90°, FORWARD 3]. How far is the robot in a straight line from its starting point (0, 0)?', '[{"text":"5 units ($3^2 + 4^2 = 9 + 16 = 25 = 5^2$)","correct":true},{"text":"7 units ($4 + 3 = 7$)","correct":false},{"text":"1 unit ($4 - 3 = 1$)","correct":false},{"text":"12 units ($4 \\times 3 = 12$)","correct":false}]'::jsonb, 'Grid navigation decomposition and Euclidean 3-4-5 right triangle distance.', 'Think of the 3-4-5 right triangle: 4 units East, 3 units North.', 1.25, -1.5, 0.25, 'Bebras Computational Thinking Grade 4', true),
  ('C04-CT-02', 4, '3-4', 'computationalThinking', 'standard', 'A student writes a program to draw a square with a pen: [REPEAT 4 TIMES: {MOVE 50 STEPS, TURN RIGHT X DEGREES}]. What angle X in degrees must the pen turn at each corner to complete a closed square?', '[{"text":"90 degrees (total turning angle = 360° / 4 sides = 90°)","correct":true},{"text":"45 degrees","correct":false},{"text":"180 degrees","correct":false},{"text":"60 degrees","correct":false}]'::jsonb, 'Total turtle geometry turning angle ($360^\circ / N$) and polygon drawing loops.', 'A full circle turn is 360 degrees. A square has 4 equal corners.', 1.3, -1.2, 0.25, 'Logo / Scratch Turtle Geometry CSTA Standards', true),
  ('C04-CT-03', 4, '3-4', 'computationalThinking', 'advanced', 'Three light switches [A, B, C] control a vault door. The door opens IF (Switch A is ON OR Switch B is ON) AND Switch C is ON. Which switch combination successfully opens the door?', '[{"text":"Switch A is ON, Switch B is OFF, Switch C is ON.","correct":true},{"text":"Switch A is ON, Switch B is ON, Switch C is OFF.","correct":false},{"text":"Switch A is OFF, Switch B is OFF, Switch C is ON.","correct":false},{"text":"All three switches are OFF.","correct":false}]'::jsonb, 'Composite Boolean expressions with parenthesized OR and AND precedence.', 'Switch C must be ON, and at least one of A or B must be ON.', 1.4, -0.7, 0.25, 'Oxford Computing Challenge Primary', true),
  ('C04-CT-04', 4, '3-4', 'computationalThinking', 'advanced', 'A list of names is sorted alphabetically: [Alice, Ben, Chloe, Daniel, Emma, Felix, Grace, Henry]. If you use Binary Search to find "Felix", which name is inspected FIRST?', '[{"text":"Daniel or Emma (the middle element of the 8 names).","correct":true},{"text":"Alice (the first name in the list).","correct":false},{"text":"Henry (the last name in the list).","correct":false},{"text":"Grace (the neighbor of Felix).","correct":false}]'::jsonb, 'Binary search middle pivot selection on ordered sequences.', 'Binary search always looks right in the middle first, cutting the search area in half.', 1.45, -0.4, 0.25, 'Bebras International Competition Grade 4-5', true),
  ('C04-CT-05', 4, '3-4', 'computationalThinking', 'olympiad', 'A message is encoded using a Caesar cipher shift of +3 (A becomes D, B becomes E, etc.). What is the original decrypted word for the coded message "FDW"?', '[{"text":"CAT (F - 3 = C, D - 3 = A, W - 3 = T)","correct":true},{"text":"DOG","correct":false},{"text":"BAT","correct":false},{"text":"HAT","correct":false}]'::jsonb, 'Modular arithmetic substitution cryptography and reverse cipher mapping.', 'Shift each letter backward 3 places in the alphabet.', 1.6, 0.1, 0.25, 'USA Computing Olympiad (USACO) Elementary / Bebras', true),
  ('C04-CT-06', 4, '3-4', 'computationalThinking', 'olympiad', 'A queue data structure operates on First-In, First-Out (FIFO). The following events occur: ENQUEUE(Apple), ENQUEUE(Banana), ENQUEUE(Cherry), DEQUEUE(), ENQUEUE(Date), DEQUEUE(). Which item is now at the front of the queue?', '[{"text":"Cherry (Apple was removed first, Banana was removed second; Cherry is now front).","correct":true},{"text":"Apple","correct":false},{"text":"Date","correct":false},{"text":"Banana","correct":false}]'::jsonb, 'Queue FIFO buffer state transitions and head-tail pointer tracking.', 'The first item in line leaves first, like people waiting for a bus.', 1.65, 0.35, 0.25, 'Bebras Benjamin Olympiad', true),
  ('C04-ED-01', 4, '3-4', 'engineeringDesign', 'standard', 'A student wants to keep hot soup warm inside a lunchbox for 4 hours. They test three materials to wrap around the metal thermos: aluminum foil, bubble wrap with trapped air, and wet paper towel. Which material will keep the soup warmest, and why?', '[{"text":"Bubble wrap, because trapped stagnant air is a poor conductor of thermal energy.","correct":true},{"text":"Wet paper towel, because water cools objects rapidly.","correct":false},{"text":"Aluminum foil alone, because metals conduct heat away quickly.","correct":false},{"text":"All materials keep soup at the exact same temperature.","correct":false}]'::jsonb, 'Thermal insulation, air pocket conduction resistance, and material thermal conductivity.', 'Air that cannot move is one of the best thermal insulators in nature.', 1.2, -1.5, 0.25, 'US NGSS 4-PS3-2 / Cambridge Primary DT', true),
  ('C04-ED-02', 4, '3-4', 'engineeringDesign', 'standard', 'A wheelbarrow has its wheel at the front, the heavy load in the middle tray, and the handles at the back where the gardener lifts. What class of simple machine is a wheelbarrow?', '[{"text":"A second-class lever (Load is located between the Fulcrum and the Effort).","correct":true},{"text":"A first-class lever (Fulcrum in the middle).","correct":false},{"text":"A third-class lever (Effort in the middle).","correct":false},{"text":"An inclined plane.","correct":false}]'::jsonb, 'Classification of lever systems by relative positions of fulcrum, load, and effort.', 'The wheel on the ground is the fulcrum, the dirt is in the middle, and your hands lift the ends.', 1.3, -1.2, 0.25, 'Singapore Primary 4 Science / UK Key Stage 2', true),
  ('C04-ED-03', 4, '3-4', 'engineeringDesign', 'advanced', 'An engineer designs a water filtration column for muddy river water. In what order from top to bottom should the filtration layers be arranged to prevent clogging?', '[{"text":"Top: Coarse pebbles $\\to$ Middle: Fine sand $\\to$ Bottom: Charcoal/Cloth filter.","correct":true},{"text":"Top: Fine cloth $\\to$ Middle: Coarse pebbles $\\to$ Bottom: Fine sand.","correct":false},{"text":"Top: Charcoal $\\to$ Middle: Pebbles $\\to$ Bottom: Sand.","correct":false},{"text":"All materials should be blended into a muddy paste.","correct":false}]'::jsonb, 'Particle size gradient filtration, sediment fractionation, and filter clogging prevention.', 'Trap large particles first so they do not block the fine mesh below.', 1.4, -0.7, 0.25, 'Project Lead The Way (PLTW) Grade 4', true),
  ('C04-ED-04', 4, '3-4', 'engineeringDesign', 'advanced', 'A model pinewood derby racecar travels down a 5-meter ramp. To reduce aerodynamic drag without changing the car’s weight, what shape should the car body have?', '[{"text":"A streamlined teardrop wedge with smooth curved contours that guide airflow with minimal wake turbulence.","correct":true},{"text":"A wide, tall rectangular block with flat vertical front faces.","correct":false},{"text":"A jagged zigzag shape with sharp rough edges.","correct":false},{"text":"A flat hollow box with open front scoops.","correct":false}]'::jsonb, 'Aerodynamic streamlining, form drag reduction, and fluid boundary displacement.', 'Look at birds and fast fish: their bodies taper smoothly to cut through air and water.', 1.45, -0.4, 0.25, 'Engineering is Elementary (EiE) Boston Museum of Science', true),
  ('C04-ED-05', 4, '3-4', 'engineeringDesign', 'olympiad', 'A fixed single pulley hangs from a ceiling. A student pulls down on the rope with 50 N of force to lift a 50 N bucket of bricks. The student then switches to a movable pulley system with two rope segments supporting the load. What force is now needed to lift the bucket?', '[{"text":"25 N (the two supporting rope segments share the load, giving a mechanical advantage of 2).","correct":true},{"text":"50 N (force never changes with pulleys).","correct":false},{"text":"100 N (movable pulleys double the weight).","correct":false},{"text":"10 N.","correct":false}]'::jsonb, 'Movable pulley mechanical advantage ($MA = 2$) and tension load distribution.', 'Count how many vertical rope strands are directly holding up the hanging load.', 1.6, 0.1, 0.25, 'FIRST LEGO League Design Challenge Grade 4', true),
  ('C04-ED-06', 4, '3-4', 'engineeringDesign', 'olympiad', 'A model wind turbine has 3 lightweight blades. When the blade angle (pitch) is 0° flat against the wind, the turbine will not spin. When tilted slightly to 15°, it spins rapidly and generates electricity. Why does an angled blade spin in moving wind?', '[{"text":"The angled blade deflects moving air sideways, generating an aerodynamic lift force that pushes the blade along its circular path.","correct":true},{"text":"Wind only blows on blades that have colored tape.","correct":false},{"text":"Angled blades become lighter than air.","correct":false},{"text":"Air creates suction behind flat blades that stops Earth from turning.","correct":false}]'::jsonb, 'Aerodynamic blade pitch, lift-induced rotational torque, and wind energy harvesting.', 'Think of how sticking your angled hand out of a moving car window pushes your hand upward.', 1.65, 0.35, 0.25, 'Clean Energy Engineering Challenge Primary', true),
  ('C04-MR-01', 4, '3-4', 'mathematicalReasoning', 'standard', 'A rectangular playground has a length of 15 meters and an area of 90 square meters. What is the width of the playground?', '[{"text":"6 meters ($90 \\div 15 = 6$ m)","correct":true},{"text":"75 meters ($90 - 15 = 75$ m)","correct":false},{"text":"12 meters","correct":false},{"text":"8 meters","correct":false}]'::jsonb, 'Inverse relationship between area and linear dimensions in rectangles ($A = l \times w$).', 'Area = Length × Width. Divide the total area by the length.', 1.2, -1.6, 0.25, 'Singapore Primary Math 4A / US Common Core 4.MD.A.3', true),
  ('C04-MR-02', 4, '3-4', 'mathematicalReasoning', 'standard', 'Which fraction is the GREATEST among the following: 3/4, 5/8, 1/2, and 7/12?', '[{"text":"3/4 (converting to 24ths: 3/4 = 18/24, 5/8 = 15/24, 1/2 = 12/24, 7/12 = 14/24)","correct":true},{"text":"5/8","correct":false},{"text":"7/12","correct":false},{"text":"1/2","correct":false}]'::jsonb, 'Fraction comparison using common denominators (LCM).', 'Find a common denominator like 24 to compare the numerators easily.', 1.25, -1.2, 0.25, 'TIMSS Grade 4 Mathematics', true),
  ('C04-MR-03', 4, '3-4', 'mathematicalReasoning', 'advanced', 'A train departs City A with 120 passengers. At the first stop, 1/3 of the passengers get off and 15 new passengers get on. How many passengers are on the train now?', '[{"text":"95 passengers (120 - 40 = 80; 80 + 15 = 95)","correct":true},{"text":"85 passengers","correct":false},{"text":"105 passengers","correct":false},{"text":"75 passengers","correct":false}]'::jsonb, 'Multi-step arithmetic combining fraction reduction and additive adjustments.', '1/3 of 120 is 40. Subtract 40, then add 15.', 1.35, -0.7, 0.25, 'Kangaroo Math Ecolier / SASMO Grade 4', true),
  ('C04-MR-04', 4, '3-4', 'mathematicalReasoning', 'advanced', 'How many lines of symmetry does a regular hexagon have?', '[{"text":"6 lines of symmetry (3 passing through opposite vertices, 3 passing through opposite edge midpoints).","correct":true},{"text":"3 lines of symmetry","correct":false},{"text":"8 lines of symmetry","correct":false},{"text":"4 lines of symmetry","correct":false}]'::jsonb, 'Rotational and reflectional symmetry axes of regular polygons.', 'A regular polygon with N sides has N lines of symmetry.', 1.45, -0.4, 0.25, 'Cambridge Primary Stage 4 Geometry', true),
  ('C04-MR-05', 4, '3-4', 'mathematicalReasoning', 'olympiad', 'The perimeter of a rectangle is 36 cm. If its length is twice as long as its width ($l = 2w$), what is the AREA of the rectangle in square centimeters?', '[{"text":"72 cm² ($2(w + 2w) = 6w = 36 \\implies w = 6$ cm, $l = 12$ cm; Area = $12 \\times 6 = 72$ cm²)","correct":true},{"text":"64 cm²","correct":false},{"text":"81 cm²","correct":false},{"text":"54 cm²","correct":false}]'::jsonb, 'Algebraic modeling of geometric perimeter to solve for non-linear area.', 'Perimeter is 2 lengths + 2 widths. If length is 2 widths, then Perimeter = 6 widths.', 1.6, 0.1, 0.25, 'American Mathematics Competitions (AMC 8) Entry / SASMO', true),
  ('C04-MR-06', 4, '3-4', 'mathematicalReasoning', 'olympiad', 'A sequence of numbers starts with 3, and each following term is calculated by doubling the previous number and subtracting 1: [3, 5, 9, 17, 33, ...]. What is the 7th term in this sequence?', '[{"text":"129 (6th term: $33 \\times 2 - 1 = 65$; 7th term: $65 \\times 2 - 1 = 129$)","correct":true},{"text":"127","correct":false},{"text":"131","correct":false},{"text":"65","correct":false}]'::jsonb, 'Recursive sequence extrapolation ($a_n = 2a_{n-1} - 1 = 2^{n-1} + 1$).', 'Notice that the terms are: 2^1 + 1, 2^2 + 1, 2^3 + 1, 2^4 + 1...', 1.65, 0.35, 0.25, 'China Primary Math Olympiad / Singapore RMO Junior', true),
  ('C04-ST-01', 4, '3-4', 'systemsThinking', 'standard', 'In a freshwater pond, green algae provide oxygen and food for water snails, and snails keep the water clear by grazing algae. If excess lawn fertilizer washes into the pond during storms, algae grows in massive green mats that block sunlight, die, and decay, consuming all the oxygen. What is this ecological process called?', '[{"text":"Eutrophication: nutrient pollution causing an algal boom that depletes dissolved oxygen.","correct":true},{"text":"Photosynthesis acceleration.","correct":false},{"text":"Thermal stratification.","correct":false},{"text":"Erosion sediment buffering.","correct":false}]'::jsonb, 'Agricultural nutrient runoff, algal blooms, and dissolved oxygen collapse in aquatic systems.', 'Too much fertilizer in water causes algae to explode in population, suffocating the pond.', 1.25, -1.5, 0.25, 'UNESCO Education for Sustainable Development (ESD) / NGSS 4-ESS3', true),
  ('C04-ST-02', 4, '3-4', 'systemsThinking', 'standard', 'A home heating system has a wall thermostat set to 20°C. When the indoor temperature drops to 19°C, the furnace turns ON until the room warms to 21°C, then turns OFF. What type of control dynamic is this?', '[{"text":"A negative (balancing) feedback loop that counteracts temperature deviations to maintain homeostatic equilibrium.","correct":true},{"text":"A positive reinforcing loop that keeps making the room hotter forever.","correct":false},{"text":"An open-loop system with zero feedback sensors.","correct":false},{"text":"A random probability generator.","correct":false}]'::jsonb, 'Negative feedback loop mechanisms and homeostatic set-point regulation.', 'A balancing loop acts like a brake to bring things back to the target set-point.', 1.3, -1.1, 0.25, 'MIT System Dynamics in K-12 / PISA Systems Thinking', true),
  ('C04-ST-03', 4, '3-4', 'systemsThinking', 'advanced', 'When a new bypass road is built around a busy market town, traffic downtown drops by 40% for the first month. However, within two years, downtown traffic is just as crowded as before because new shopping plazas were built along the bypass road, attracting 1,000 new commuters. What systems principle explains this?', '[{"text":"Induced demand and unintended urban feedback: expanding transit capacity alters land use and attracts new vehicle trips until congestion returns.","correct":true},{"text":"Cars multiply on their own when new roads are paved.","correct":false},{"text":"The old road shrank in size over time.","correct":false},{"text":"Traffic lights automatically stay red longer on older streets.","correct":false}]'::jsonb, 'Induced demand, land-use transportation feedback loops, and policy resistance.', 'When travel becomes easier, more people decide to drive or build businesses there.', 1.4, -0.6, 0.25, 'OECD PISA Urban Systems / UN SDG 11', true),
  ('C04-ST-04', 4, '3-4', 'systemsThinking', 'advanced', 'In a mountain forest, woodpeckers drill holes into dead trees for nests. After woodpeckers leave, bluebirds, bats, and flying squirrels use the empty cavities to raise their young. Why is the woodpecker classified as an "ecosystem engineer"?', '[{"text":"It creates essential physical shelter habitats that other species depend upon for reproduction.","correct":true},{"text":"It constructs solar panels on tree trunks.","correct":false},{"text":"It eats more trees than any other animal.","correct":false},{"text":"It controls the local air temperature by flapping its wings.","correct":false}]'::jsonb, 'Ecosystem engineers, keystone niche creation, and multi-species habitat dependency.', 'An ecosystem engineer changes the physical environment in a way that builds homes for other creatures.', 1.45, -0.3, 0.25, 'US NGSS 4-LS1 / Cambridge Primary Science', true),
  ('C04-ST-05', 4, '3-4', 'systemsThinking', 'olympiad', 'A municipal water reservoir supplies a city of 50,000 residents. During a dry summer month, the city uses 10,000 m³ of water daily, while river inflow is only 6,000 m³ daily. If the reservoir holds 120,000 m³ of usable storage, in how many days will the reservoir run completely dry without rain?', '[{"text":"30 days (net loss rate = 10,000 - 6,000 = 4,000 m³/day; 120,000 ÷ 4,000 = 30 days).","correct":true},{"text":"12 days","correct":false},{"text":"20 days","correct":false},{"text":"40 days","correct":false}]'::jsonb, 'Stock-and-flow dynamic balance: Net change = Inflow - Outflow.', 'Calculate how much water is lost every day (Outflow minus Inflow), then divide the total storage by that daily loss.', 1.6, 0.1, 0.25, 'MIT System Dynamics K-12 Stock and Flow Modeling', true),
  ('C04-ST-06', 4, '3-4', 'systemsThinking', 'olympiad', 'In the Arctic tundra, warmer summer temperatures melt white reflective sea ice, exposing dark ocean water underneath. Dark water absorbs 90% of solar radiation (compared to white ice reflecting 80%), causing the water to warm further and melt even more ice. What systemic dynamic does this "ice-albedo feedback" illustrate?', '[{"text":"A reinforcing (positive) feedback loop: the effect amplifies the initial warming trigger, accelerating system state change.","correct":true},{"text":"A balancing (negative) feedback loop that restores ice cover automatically.","correct":false},{"text":"A closed linear system with zero energy exchange.","correct":false},{"text":"An isolated chemical reaction that creates ozone.","correct":false}]'::jsonb, 'Reinforcing positive feedback loops and planetary albedo climate dynamics.', 'Does melting ice lead to more melting or does it stop the melting? If it accelerates the change, it is positive feedback.', 1.65, 0.4, 0.25, 'PISA 2025 Science / UNESCO Climate Science Indicators', true);


-- Batch for Class 5 (30 questions)
INSERT INTO public.scenarios (
  scenario_code, class_level, developmental_band, competency, difficulty,
  prompt, options, learning_objective, hint, irt_a, irt_b, irt_c,
  international_benchmark, is_active
) VALUES
  ('C05-SCI-01', 5, '5-6', 'scientificInquiry', 'standard', 'A science class dissolves equal masses of salt in three beakers containing 100 mL of water at 10°C, 25°C, and 60°C. They stir each at the same rate and record the time required for complete dissolution. What is the primary hypothesis being tested in this investigation?', '[{"text":"Increasing solvent temperature increases the kinetic energy of water molecules, accelerating the rate of solute dissolution.","correct":true},{"text":"Stirring water faster changes the chemical composition of salt into chlorine gas.","correct":false},{"text":"Cold water permanently changes the density of salt grains so they can never dissolve.","correct":false},{"text":"Adding salt lowers the boiling point of water below room temperature.","correct":false}]'::jsonb, 'Solubility kinetics, thermal energy molecular collisions, and fair-test variable isolation.', 'Look at what was intentionally varied between the three beakers while water volume and stirring remained identical.', 1.25, -1.2, 0.25, 'TIMSS 2023 Grade 4 Science / Singapore Primary 5 Science', true),
  ('C05-SCI-02', 5, '5-6', 'scientificInquiry', 'standard', 'Students observe that when a clear plastic jar with green leaves inside is sealed and placed under direct sunlight for three hours, small water droplets condense on the inner walls. What physiological plant process directly accounts for this observation?', '[{"text":"Transpiration, where water absorbed by roots moves through the plant and evaporates through leaf stomata into the sealed air.","correct":true},{"text":"Respiration, which destroys plant cell walls and converts sugar into liquid water pools.","correct":false},{"text":"Photosynthesis creating hydrogen gas that instantly liquifies upon contact with clear plastic.","correct":false},{"text":"Capillary action pulling atmospheric nitrogen through the plastic jar walls.","correct":false}]'::jsonb, 'Plant vascular transport, stomatal transpiration, and water vapor condensation.', 'Plants absorb water and release moisture vapor through microscopic pores on leaves called stomata.', 1.3, -0.9, 0.25, 'NGSS 5-LS1-1 / Cambridge Primary Science Stage 6', true),
  ('C05-SCI-03', 5, '5-6', 'scientificInquiry', 'advanced', 'To test whether light intensity affects photosynthesis, a student places elodea waterweed in a sodium bicarbonate solution 10 cm, 20 cm, and 40 cm away from a 100W lamp. They count oxygen bubbles produced per minute. Why was sodium bicarbonate added to the water in all test tubes?', '[{"text":"To ensure dissolved carbon dioxide is in constant supply and does not become the limiting factor of photosynthesis.","correct":true},{"text":"To tint the water blue so bubbles are more easily visible to the human eye.","correct":false},{"text":"To heat the water up rapidly to trigger enzymatic denaturation.","correct":false},{"text":"To react directly with oxygen gas and form solid calcium deposits.","correct":false}]'::jsonb, 'Photosynthesis limiting reagents, experimental controls, and gaseous byproduct observation.', 'Photosynthesis requires light, water, and an essential carbon source to produce sugars and oxygen.', 1.45, -0.4, 0.25, 'TIMSS 2023 Grade 8 Science Foundation / Singapore Primary 5 Science Advanced', true),
  ('C05-SCI-04', 5, '5-6', 'scientificInquiry', 'advanced', 'A student drops a steel ball and a solid wooden ball of the exact same diameter from a 3-meter platform simultaneously into a sandbox. Both hit the sand at virtually the exact same time, but the steel ball leaves a significantly deeper crater. How is this outcome best explained scientifically?', '[{"text":"Both experience identical gravitational acceleration (g), but the denser steel ball has greater mass and kinetic energy (½mv²), doing more work on the sand.","correct":true},{"text":"The steel ball accelerated twice as fast as the wooden ball because gravity pulls harder on heavier objects in free fall.","correct":false},{"text":"The wooden ball bounced upward upon release due to atmospheric buoyancy canceling gravity entirely.","correct":false},{"text":"The sand exerted a magnetic attraction on the steel ball that doubled its impact velocity.","correct":false}]'::jsonb, 'Galilean free-fall acceleration equivalence versus mass-dependent kinetic energy and work done upon impact.', 'Remember Galileo’s leaning tower experiment on acceleration, then calculate what mass does to kinetic energy when speed is identical.', 1.5, -0.2, 0.25, 'NGSS MS-PS2-2 / US Science Olympiad Division B Prep', true),
  ('C05-SCI-05', 5, '5-6', 'scientificInquiry', 'olympiad', 'A sealed calorimeter holds 200 g of water at 20°C. An unknown metal sample weighing 50 g heated to 100°C is dropped in. The thermal equilibrium temperature settles at 22°C. Assuming zero heat loss to surroundings and water specific heat = 4.184 J/(g·°C), what can you deduce about the metal''s specific heat capacity relative to water?', '[{"text":"The metal has a much lower specific heat capacity than water (~0.43 J/g·°C), because dropping 78°C only warmed 4 times its mass of water by 2°C.","correct":true},{"text":"The metal must have an identical specific heat capacity to water because they reached a shared equilibrium temperature.","correct":false},{"text":"The metal gained heat from the cooler water because higher density metals always absorb thermal energy.","correct":false},{"text":"The law of conservation of energy was violated because the final temperature was closer to 20°C than to 100°C.","correct":false}]'::jsonb, 'Calorimetric equilibrium, specific heat capacity ratios, and thermal energy conservation (Q_lost = Q_gained).', 'Compare heat lost by metal [m_m * c_m * ΔT_m] to heat gained by water [m_w * c_w * ΔT_w]. Note that ΔT_metal is 78°C while ΔT_water is only 2°C.', 1.65, 0.1, 0.25, 'IJSO Foundation / Singapore Primary Science Olympiad', true),
  ('C05-SCI-06', 5, '5-6', 'scientificInquiry', 'olympiad', 'In a marine ecology survey, researchers notice coral bleaching along a coastal reef during an El Niño warming event. They hypothesize that thermal stress causes corals to expel their symbiotic dinoflagellates (zooxanthellae). Which observation would provide the strongest causal evidence supporting this specific hypothesis?', '[{"text":"Microscopic cellular counts showing exponential zooxanthellae expulsion specifically when water exceeds 31°C, accompanied by a cessation of photosynthetic carbon transfer to coral tissue.","correct":true},{"text":"Observing that predatory fish leave the coral reef whenever ocean temperatures drop below 15°C.","correct":false},{"text":"Measuring that calcium carbonate dissolves in vinegar in a laboratory test tube.","correct":false},{"text":"Finding that corals growing near deep-sea hydrothermal vents have no relationship with algae.","correct":false}]'::jsonb, 'Endosymbiosis breakdown, causal mechanism verification in environmental science, and marine biology.', 'The hypothesis specifically states thermal stress causes the expulsion of symbiotic algae; look for data directly measuring algal cell expulsion under elevated heat.', 1.6, 0.2, 0.25, 'UN SDG 14 Life Below Water / International Biology Olympiad Junior Division', true),
  ('C05-COM-01', 5, '5-6', 'computationalThinking', 'standard', 'A warehouse robot follows this algorithm to sort numbered crates: "Examine adjacent crates at positions i and i+1. If crate i > crate i+1, swap them. Repeat until no swaps occur in a full pass." Given initial crate order [8, 3, 5, 2], what is the crate order after exactly ONE full pass from left to right?', '[{"text":"[3, 5, 2, 8]","correct":true},{"text":"[2, 3, 5, 8]","correct":false},{"text":"[8, 5, 3, 2]","correct":false},{"text":"[3, 8, 2, 5]","correct":false}]'::jsonb, 'Bubble sort mechanics, single-pass tracing, and adjacent element comparison logic.', 'Step through the swaps: compare 8 & 3 (swap), then 8 & 5 (swap), then 8 & 2 (swap).', 1.35, -1, 0.25, 'Bebras International Challenge Benjamin (Ages 10-12)', true),
  ('C05-COM-02', 5, '5-6', 'computationalThinking', 'standard', 'An automatic greenhouse climate script executes every minute: 
"if soil_moisture < 30 and temperature > 28 then ACTIVATE_IRRIGATION 
else if soil_moisture < 20 then ACTIVATE_IRRIGATION 
else IDLE". 
If soil_moisture is 25 and temperature is 24, what state does the controller select?', '[{"text":"IDLE, because soil_moisture < 30 is true, but temperature > 28 is false, and soil_moisture is not below 20.","correct":true},{"text":"ACTIVATE_IRRIGATION, because soil_moisture is less than 30 regardless of temperature.","correct":false},{"text":"ACTIVATE_IRRIGATION, because any moisture below 50% immediately triggers watering.","correct":false},{"text":"EMERGENCY_SHUTDOWN, because the conditional statements trigger an infinite loop.","correct":false}]'::jsonb, 'Compound Boolean expressions (AND/OR), sequential conditional precedence, and branch evaluation.', 'Evaluate the first condition: Is (25 < 30) AND (24 > 28)? Then evaluate the second: Is 25 < 20?', 1.4, -0.7, 0.25, 'CSTA K-12 Computer Science Level 1B / Bebras Benjamin', true),
  ('C05-COM-03', 5, '5-6', 'computationalThinking', 'advanced', 'A search algorithm checks a sorted list of 64 names using binary search. If the target name is located at the very last step (worst-case scenario), how many total comparisons between names are required?', '[{"text":"6 comparisons, because log₂(64) = 6, halving the search space at each iteration.","correct":true},{"text":"32 comparisons, because on average half the items in the list must be checked.","correct":false},{"text":"64 comparisons, because every single item must be checked one by one.","correct":false},{"text":"16 comparisons, because the algorithm divides the list into four equal quadrants.","correct":false}]'::jsonb, 'Binary search logarithmic complexity, divide-and-conquer strategy, and search space reduction.', 'Start with 64 items: pass 1 leaves 32, pass 2 leaves 16, pass 3 leaves 8... continue halving down to 1.', 1.5, -0.3, 0.25, 'USACO Bronze Preparation / Bebras Benjamin High Distinction', true),
  ('C05-COM-04', 5, '5-6', 'computationalThinking', 'advanced', 'A recursive graphic function draws a tree branch: `branch(length): if length < 5 return; draw_line(length); branch(length / 2); branch(length / 2)`. If initial `branch(40)` is called, how many total line segments are drawn at the final base tier where length = 5?', '[{"text":"8 segments, because the branch halves 3 times (40 → 20 → 10 → 5), branching into 2³ = 8 endpoints.","correct":true},{"text":"4 segments, because each call produces two branches.","correct":false},{"text":"16 segments, because 40 divided by 5 equals 8 pairs of lines.","correct":false},{"text":"3 segments, representing the depth of recursion only.","correct":false}]'::jsonb, 'Recursive tree structures, exponential branching factors (2^d), and base condition termination.', 'Trace the levels: Level 0 has 1 line (len 40); Level 1 has 2 lines (len 20); Level 2 has 4 lines (len 10); Level 3 has how many?', 1.55, 0, 0.25, 'Informatics Olympiad Primary Division / AP CS Principles Concept Seed', true),
  ('C05-COM-05', 5, '5-6', 'computationalThinking', 'olympiad', 'A parity bit is appended to a 7-bit ASCII transmission to maintain an EVEN number of total 1s. The receiver receives the byte `1 0 1 1 0 1 0 [1]`, where the bracketed bit is the parity bit. What does the parity check indicate, and what is its fundamental limitation?', '[{"text":"The byte is flagged as corrupted because there are 5 ones (odd); however, parity checking cannot detect if an even number of bit errors (e.g. 2 bits flipped) occurred.","correct":true},{"text":"The byte is guaranteed 100% error-free because the parity bit is 1.","correct":false},{"text":"The receiver can automatically pinpoint exactly which bit flipped and invert it back.","correct":false},{"text":"The transmission failed because parity bits can only be applied to numerical data, not text characters.","correct":false}]'::jsonb, 'Error detection codes, parity checking mechanisms, and limitation in multi-bit corruptions.', 'Count the total number of 1s in the entire 8-bit sequence (including the parity bit). Is it even or odd? Can single parity catch two simultaneous errors?', 1.6, 0.15, 0.25, 'Bebras Cadet Olympiad / Junior Australian Informatics Competition', true),
  ('C05-COM-06', 5, '5-6', 'computationalThinking', 'olympiad', 'Consider a directed acyclic graph (DAG) representing tasks for building a model satellite: Task A (Antenna, 3 hrs), Task B (Battery, 4 hrs), Task C (Computer, requires B, 5 hrs), Task D (Telemetry assembly, requires A and C, 2 hrs). If Tasks A and B can begin simultaneously at hour 0, what is the earliest hour Task D can be completed (critical path)?', '[{"text":"Hour 11 (Task B [4] + Task C [5] + Task D [2] = 11 hours, since C depends on B and D cannot start until hour 9).","correct":true},{"text":"Hour 14 (adding all task durations sequentially: 3 + 4 + 5 + 2 = 14 hours).","correct":false},{"text":"Hour 5 (since Task A only takes 3 hours and Task D takes 2 hours).","correct":false},{"text":"Hour 7 (executing Tasks B and C simultaneously while D finishes).","correct":false}]'::jsonb, 'Critical path analysis, task dependency graphs, and parallel execution limits in systems scheduling.', 'Find which prerequisite chain takes longer before Task D can start: Chain 1 is A (3 hrs). Chain 2 is B + C (4 + 5 = 9 hrs).', 1.7, 0.25, 0.25, 'Junior Informatics Olympiad / Project Management Institute Educational Foundation', true),
  ('C05-ENG-01', 5, '5-6', 'engineeringDesign', 'standard', 'An engineering team tests bridge truss designs using popsicle sticks. Design X uses square frames, while Design Y uses triangles inside the framework. When identical weights are placed at the center, Design X deforms and collapses at 4 kg, whereas Design Y supports 18 kg. Why is triangular trussing inherently more rigid?', '[{"text":"A triangle is geometrically rigid because its angles cannot change without altering the lengths of its sides, distributing loads as pure tension and compression.","correct":true},{"text":"Triangles contain less wood than squares, allowing them to bend like rubber bands without breaking.","correct":false},{"text":"Squares always amplify downward gravitational force by trapping air pressure beneath their joints.","correct":false},{"text":"Popsicle stick glue chemically bonds with triangular corners twice as strongly as square corners.","correct":false}]'::jsonb, 'Structural geometry, geometric rigidity of triangles, and truss load distribution.', 'Try pushing on the corner of a cardboard square vs. a triangle; which one changes shape without its sides bending?', 1.3, -1.1, 0.25, 'NGSS 3-5-ETS1-2 / FIRST LEGO League Innovation Challenge', true),
  ('C05-ENG-02', 5, '5-6', 'engineeringDesign', 'standard', 'Students are designing a wind turbine blade to generate maximum electrical voltage from a household desk fan. They notice flat cardboard blades produce very low rotation speeds. How can aerodynamic principles be applied to improve blade efficiency?', '[{"text":"Curve the blade profile into an airfoil camber and twist the pitch angle from root to tip to generate aerodynamic lift.","correct":true},{"text":"Make the blades completely flat and as heavy as possible so gravity pulls them down faster.","correct":false},{"text":"Cover the blades in sandpaper to increase drag friction against the airflow.","correct":false},{"text":"Remove all blades and allow the central motor axle to spin in free air.","correct":false}]'::jsonb, 'Aerodynamic lift vs. drag, airfoil camber design, and kinetic-to-electrical energy conversion.', 'Airplane wings and modern turbine blades don’t just get pushed by air; their curved shape generates lift that pulls them forward.', 1.35, -0.8, 0.25, 'KidWind Challenge / NGSS 3-5-ETS1-3', true),
  ('C05-ENG-03', 5, '5-6', 'engineeringDesign', 'advanced', 'A prototype solar water desalinator produces 50 mL of clean water per hour, but the target specification requires 150 mL/hour within a 0.5 m² footprint. Which iterative engineering refinement addresses the thermal bottleneck most effectively without increasing surface area?', '[{"text":"Line the basin with a matte-black solar absorber, insulate the basin base to prevent conduction loss, and add a heat-recovery condensation channel.","correct":true},{"text":"Paint the entire transparent glass cover black so no light reflects away.","correct":false},{"text":"Drill large open holes in the cover so steam escapes directly into the outdoor atmosphere.","correct":false},{"text":"Replace the saline water with ice cubes to lower the required energy threshold.","correct":false}]'::jsonb, 'Thermal efficiency optimization, blackbody solar absorption, insulation, and closed-loop condensation.', 'To distill more water, maximize heat absorption inside the basin while minimizing heat escaping through the bottom, and condense vapor inside.', 1.45, -0.3, 0.25, 'UN SDG 6 Clean Water & Sanitation / Dyson Foundation Junior Engineering Challenge', true),
  ('C05-ENG-04', 5, '5-6', 'engineeringDesign', 'advanced', 'A robotic rover designed for soft lunar regolith gets its wheels stuck and spins in place without forward progress. An engineer considers redesigning the wheel subsystem. According to terramechanics and ground pressure principles, which design change best prevents wheel sinkage?', '[{"text":"Increase wheel width and diameter to expand the contact patch area, reducing ground contact pressure (Pressure = Force / Area) and adding flexible grousers.","correct":true},{"text":"Decrease wheel diameter to a needle-thin edge so the wheels can dig deeper trenches.","correct":false},{"text":"Add 20 kg of lead weights directly above the axle to push the rover into the ground.","correct":false},{"text":"Polish the wheel tread until it is completely smooth to eliminate all friction.","correct":false}]'::jsonb, 'Contact mechanics, pressure distribution (P = F/A), traction engineering, and extraterrestrial mobility.', 'Why do snowshoes prevent people from sinking in soft snow? Apply that same geometric logic to rover wheels on loose dust.', 1.5, -0.1, 0.25, 'NASA Lunabotics Junior Challenge / ASME Student Engineering', true),
  ('C05-ENG-05', 5, '5-6', 'engineeringDesign', 'olympiad', 'In designing a high-altitude research balloon payload, team engineers face competing constraints: thermal insulation (aerogel vs. EPS foam), payload mass budget (max 1.2 kg), and battery operating temperature (must stay above -10°C in an ambient -55°C stratosphere). Aerogel has 3× the thermal resistance of EPS foam per gram but costs 8× more. What decision matrix trade-off justifies choosing aerogel?', '[{"text":"The payload mass budget is the non-negotiable critical constraint; saving 400 g of insulation mass permits vital scientific sensors while meeting thermal thresholds.","correct":true},{"text":"Cost is always ignored in aerospace engineering because scientific components have unlimited budgets.","correct":false},{"text":"EPS foam dissolves instantly when exposed to ultraviolet radiation in the upper stratosphere.","correct":false},{"text":"Aerogel generates its own internal electrical current to recharge depleted drone batteries.","correct":false}]'::jsonb, 'Multi-criteria decision analysis (MCDA), constraint optimization, mass-budget allocation in aerospace systems.', 'In ballooning and rocketry, every gram of excess insulation mass reduces scientific instruments or flight ceiling.', 1.6, 0.15, 0.25, 'European Space Agency (ESA) Climate Detectives / AIAA Junior Aerospace Award', true),
  ('C05-ENG-06', 5, '5-6', 'engineeringDesign', 'olympiad', 'A solar-powered autonomous boat experiences roll oscillations that cause solar panel shading in choppy lake waters. The design team evaluates three stabilizing solutions: (1) Active gyro stabilizer, (2) Twin-hull catamaran configuration, (3) Passive water ballast tank. Which option provides the greatest static roll stability with zero auxiliary electrical power drain?', '[{"text":"Twin-hull catamaran configuration, which dramatically widens the metacenter and waterplane area moment of inertia without consuming stored electrical battery power.","correct":true},{"text":"Active gyro stabilizer, because spinning a flywheel at 10,000 RPM consumes zero electrical energy once started.","correct":false},{"text":"Mounting solar panels vertically underwater where waves cannot disturb them.","correct":false},{"text":"Filling the deck with helium gas canisters to lift the boat completely out of water.","correct":false}]'::jsonb, 'Naval architecture, metacentric height, passive vs. active stabilization, and power parasitic load trade-offs.', 'Look for a passive geometric design that resists rolling purely through hull separation without draining battery power needed for propulsion.', 1.65, 0.25, 0.25, 'RoboBoat Junior Autonomous Systems / World Robot Olympiad Future Innovators', true),
  ('C05-MAT-01', 5, '5-6', 'mathematicalReasoning', 'standard', 'A water reservoir has two inlet pipes. Pipe A fills the reservoir alone in 6 hours. Pipe B fills the reservoir alone in 3 hours. If both pipes are opened simultaneously at full flow, how many hours will it take to fill the completely empty reservoir?', '[{"text":"2 hours (Pipe A fills 1/6 per hour + Pipe B fills 1/3 per hour = 3/6 = 1/2 per hour; reciprocal is 2 hours).","correct":true},{"text":"4.5 hours (the arithmetic mean of 6 and 3 hours).","correct":false},{"text":"9 hours (adding 6 hours plus 3 hours together).","correct":false},{"text":"1.5 hours (subtracting 3 hours from 6 hours and dividing by 2).","correct":false}]'::jsonb, 'Reciprocal rates of work, fractional addition, and combined flow rate calculations.', 'Calculate what fraction of the tank each pipe fills in one single hour, then add the fractions together.', 1.35, -1, 0.25, 'PISA 2022 Mathematical Literacy Level 2 / Singapore Primary 5 Math', true),
  ('C05-MAT-02', 5, '5-6', 'mathematicalReasoning', 'standard', 'A rectangular garden plot has a perimeter of 48 meters. The length of the garden is twice its width. What is the total area of the garden in square meters?', '[{"text":"128 m² (Width = 8 m, Length = 16 m; Perimeter = 2(8+16) = 48 m; Area = 8 × 16 = 128 m²).","correct":true},{"text":"144 m² (assuming the garden is a 12 m × 12 m square).","correct":false},{"text":"96 m² (multiplying perimeter 48 by 2).","correct":false},{"text":"64 m² (Width = 4 m, Length = 8 m).","correct":false}]'::jsonb, 'Algebraic perimeter modeling, linear equations in one variable, and area computation.', 'Let width = w, then length = 2w. Perimeter = 2(w + 2w) = 6w = 48 meters. Solve for w, then find length × width.', 1.4, -0.7, 0.25, 'TIMSS 2023 Grade 4/8 Math / Australian Mathematics Competition Middle Primary', true),
  ('C05-MAT-03', 5, '5-6', 'mathematicalReasoning', 'advanced', 'A bag contains 5 red marbles, 4 blue marbles, and 3 green marbles. A student draws two marbles sequentially WITHOUT replacement. What is the exact probability that both drawn marbles are red?', '[{"text":"5/33 (First draw is 5/12; second draw is 4/11; product is (5×4)/(12×11) = 20/132 = 5/33).","correct":true},{"text":"25/144 (calculated with replacement as 5/12 × 5/12).","correct":false},{"text":"5/12 (the probability of drawing only the first red marble).","correct":false},{"text":"1/6 (assuming there are only 6 total pairs possible).","correct":false}]'::jsonb, 'Compound dependent events, conditional probability without replacement, and fraction multiplication.', 'After drawing one red marble, how many red marbles remain, and what is the new total number of marbles in the bag?', 1.5, -0.2, 0.25, 'PISA 2022 Quantity & Uncertainty / AMC 8 Foundation', true),
  ('C05-MAT-04', 5, '5-6', 'mathematicalReasoning', 'advanced', 'A 3D cube constructed of smaller 1 cm × 1 cm × 1 cm unit cubes measures 4 cm along each edge. All 6 exterior faces are painted blue. If the large cube is dismantled into its 64 unit cubes, how many unit cubes have EXACTLY TWO painted blue faces?', '[{"text":"24 cubes (the middle 2 cubes along each of the 12 edges: 12 × 2 = 24).","correct":true},{"text":"8 cubes (only the corner vertices).","correct":false},{"text":"16 cubes (the center faces on the exterior sides).","correct":false},{"text":"32 cubes (half of the total cubes in the cube).","correct":false}]'::jsonb, '3D spatial geometry, edge vs. face vs. corner classification in polyhedra, and combinatorics.', 'Corner cubes have 3 painted faces; interior cubes have 0; center face cubes have 1; edge cubes (excluding corners) have exactly 2.', 1.55, 0, 0.25, 'Math Kangaroo Benjamin (Grades 5-6) / UKMT Junior Mathematical Challenge', true),
  ('C05-MAT-05', 5, '5-6', 'mathematicalReasoning', 'olympiad', 'Find the units digit of the exponential sum: S = 3²⁰²⁶ + 7²⁰²⁶ + 2²⁰²⁶. How can pattern cyclicity in modular arithmetic solve this without calculating massive powers?', '[{"text":"8 (Powers of 3 cycle in 4s [3,9,7,1; 2026 mod 4 = 2 → 9]; powers of 7 cycle in 4s [7,9,3,1; mod 4 = 2 → 9]; powers of 2 cycle in 4s [2,4,8,6; mod 4 = 2 → 4]; sum is 9 + 9 + 4 = 22 → units digit 2... wait: 9+9+4=22 → units digit 2).","correct":false},{"text":"2 (3²⁰²⁶ ends in 9, 7²⁰²⁶ ends in 9, 2²⁰²⁶ ends in 4; 9 + 9 + 4 = 22, so the units digit is 2).","correct":true},{"text":"4 (assuming all powers of odd numbers end in 1).","correct":false},{"text":"6 (multiplying the base digits 3 × 7 × 2).","correct":false}]'::jsonb, 'Modular arithmetic, cyclicity of last digits in powers (mod 10), and number theory patterns.', 'Find the period length of units digits for 3, 7, and 2. Divide the exponent 2026 by the period length 4 to find the remainder.', 1.65, 0.15, 0.25, 'Primary Mathematics World Contest (PMWC) / Singapore Math Olympiad Junior', true),
  ('C05-MAT-06', 5, '5-6', 'mathematicalReasoning', 'olympiad', 'In a circle with radius 10 cm, an equilateral triangle is inscribed such that all three vertices lie on the circumference. What is the exact area of this inscribed equilateral triangle?', '[{"text":"75√3 cm² (Side length s = r√3 = 10√3 cm; Area = (√3/4)s² = (√3/4)(300) = 75√3 ≈ 129.9 cm²).","correct":true},{"text":"100√3 cm² (multiplying radius squared directly by √3).","correct":false},{"text":"50√3 cm² (using half the radius as side length).","correct":false},{"text":"314 cm² (the area of the circumscribed circle itself).","correct":false}]'::jsonb, 'Inscribed equilateral polygon geometry, circumradius formulas (R = s/√3), and exact radical area derivation.', 'In an equilateral triangle, the circumradius R relates to side length s by R = s/√3, so s = R√3. The area is (√3/4)s².', 1.7, 0.25, 0.25, 'Asian Pacific Mathematics Olympiad Junior / Russian Math Olympiad Grade 5', true),
  ('C05-SYS-01', 5, '5-6', 'systemsThinking', 'standard', 'In a temperate forest ecosystem, a fungal disease wipes out 90% of the oak trees that produce acorns. Acorns are the primary autumn food source for field mice. Owls feed almost exclusively on field mice. What cascading system behavior is predicted over the following two seasons?', '[{"text":"Mouse populations crash due to starvation, leading to a delayed drop in owl reproduction and population size (trophic cascade).","correct":true},{"text":"Owls will immediately begin eating sunlight directly to maintain equilibrium.","correct":false},{"text":"Mouse populations will multiply tenfold because fewer oak trees mean more open running space.","correct":false},{"text":"The ecosystem experiences zero changes because predators are completely independent of plant producers.","correct":false}]'::jsonb, 'Trophic food web dynamics, carrying capacity, bottom-up regulation, and delayed feedback in ecology.', 'Trace the flow of energy: if producers decrease drastically, what happens to primary consumers, and then to secondary predators?', 1.3, -1.1, 0.25, 'UN SDG 15 Life on Land / Cambridge Primary Science Ecosystems', true),
  ('C05-SYS-02', 5, '5-6', 'systemsThinking', 'standard', 'A municipal water supply uses an elevated water tower on a hill connected to houses in the valley below. During a summer heatwave, many residents turn on lawn sprinklers at the same time, causing water pressure to drop sharply in second-story bathrooms. Why does simultaneous high demand lower household pressure?', '[{"text":"Increased flow velocity through delivery mains increases pipe friction head loss and draws down dynamic water pressure throughout the network.","correct":true},{"text":"The water tower shrinks in volume due to summer evaporation in its steel tank.","correct":false},{"text":"Lawn grass absorbs atmospheric pressure directly from underground pipes.","correct":false},{"text":"The gravitational pull on elevated water weakens during daylight hours.","correct":false}]'::jsonb, 'Hydraulic network dynamics, pressure head vs. flow rate, pipe friction losses, and peak load stress.', 'When water moves rapidly through pipes, friction along pipe walls converts pressure energy into thermal dissipation, dropping delivered pressure.', 1.35, -0.8, 0.25, 'ASCE Infrastructure Education / NGSS MS-ESS3-3 Foundation', true),
  ('C05-SYS-03', 5, '5-6', 'systemsThinking', 'advanced', 'An agricultural watershed experiences toxic cyanobacteria blooms in its freshwater lake every July. Farmers apply nitrogen and phosphorus fertilizers to fields upstream; heavy rainfall carries runoff into tributaries. What systemic feedback loop is responsible for the subsequent dead zones (hypoxia) where fish die?', '[{"text":"Eutrophication loop: fertilizer excess triggers rapid algal blooms; when algae die, decomposing bacteria consume dissolved oxygen, suffocating aquatic animals.","correct":true},{"text":"Algae produce toxic sulfuric acid that directly dissolves the bones of fish.","correct":false},{"text":"Fertilizer chemicals make lake water so dense that fish sink to the bottom and cannot swim up.","correct":false},{"text":"Cyanobacteria absorb all the water in the lake, reducing water levels by 80%.","correct":false}]'::jsonb, 'Eutrophication cascades, nutrient loading feedback loops, biological oxygen demand (BOD), and hypoxia.', 'The danger is not just the algae growing—it is what happens when massive amounts of dead algae decompose and bacteria use up all the dissolved oxygen.', 1.45, -0.3, 0.25, 'UN SDG 6 & 14 / OECD PISA Environmental Literacy', true),
  ('C05-SYS-04', 5, '5-6', 'systemsThinking', 'advanced', 'A home heating system maintains 20°C using a thermostat. When outdoor temperature suddenly plummets from 5°C to -15°C, the indoor temperature oscillates between 17°C and 23°C rather than staying steady. What control system issue explains these large swings?', '[{"text":"Thermal lag and hysteresis: the house walls take time to warm up and cool down, causing the heater to stay on too long before the thermostat detects the change.","correct":true},{"text":"The thermostat is running backwards, converting cold air into combustible gas.","correct":false},{"text":"Negative feedback loops are mathematically incapable of controlling temperature.","correct":false},{"text":"The freezing outdoor air causes electrical wires inside the thermostat to produce random random numbers.","correct":false}]'::jsonb, 'Thermal inertia, lag in feedback systems, sensor response time, and overshoot/undershoot behavior.', 'Because heat takes time to travel through air and walls, by the time the sensor feels 20°C, the radiators are already scorching hot.', 1.5, 0, 0.25, 'IEEE Control Systems Society High School Initiative / MIT Systems Dynamics Group', true),
  ('C05-SYS-05', 5, '5-6', 'systemsThinking', 'olympiad', 'In the Arctic climate system, the ice-albedo feedback is a critical mechanism. Sea ice has an albedo of ~0.6-0.8 (reflecting sunlight), while open seawater has an albedo of ~0.06 (absorbing 94% of sunlight). Why is this classified as a POSITIVE feedback loop, and what makes it dangerous for stability?', '[{"text":"Warming melts ice → more dark ocean is exposed → absorbs more solar heat → accelerates further ice melting; amplifying the initial disruption.","correct":true},{"text":"It is called \"positive\" because melting ice creates beneficial fresh drinking water for all arctic marine animals.","correct":false},{"text":"It acts as a stabilizing negative brake that instantly returns Arctic temperatures back to freezing equilibrium.","correct":false},{"text":"Open seawater reflects 100% of cosmic rays back into outer space, cooling the Earth’s mantle.","correct":false}]'::jsonb, 'Positive feedback amplification, planetary albedo, cryosphere dynamics, and climate tipping elements.', 'In systems dynamics, a "positive" feedback loop does not mean "good"—it means self-reinforcing, where the effect amplifies the initial cause.', 1.6, 0.15, 0.25, 'IPCC Working Group I Sixth Assessment / UN SDG 13 Climate Action', true),
  ('C05-SYS-06', 5, '5-6', 'systemsThinking', 'olympiad', 'A regional electrical power grid integrates 40% intermittent wind power. On a windy night when consumer electrical demand drops to a minimum, the grid faces potential instability. Which system engineering intervention provides grid balancing without curtailing (wasting) renewable power?', '[{"text":"Dispatching excess power into pumped-storage hydroelectric stations and grid-scale battery energy storage systems (BESS) for daytime peak discharge.","correct":true},{"text":"Short-circuiting the wind turbines into ground wires to heat the surrounding farmland.","correct":false},{"text":"Disconnecting all transformers across cities to allow line voltage to surge to infinity.","correct":false},{"text":"Replacing alternating current (AC) with low-voltage static electricity across high-voltage transmission towers.","correct":false}]'::jsonb, 'Grid frequency stabilization, supply-demand balancing with intermittent renewables, and energy storage systems.', 'When electricity supply exceeds demand, energy cannot simply vanish—it must either be stored in another form (potential or chemical) or lost.', 1.65, 0.25, 0.25, 'IEEE Power & Energy Society / Clean Energy Ministerial Youth Forum', true);


-- Batch for Class 6 (30 questions)
INSERT INTO public.scenarios (
  scenario_code, class_level, developmental_band, competency, difficulty,
  prompt, options, learning_objective, hint, irt_a, irt_b, irt_c,
  international_benchmark, is_active
) VALUES
  ('C06-SCI-01', 6, '5-6', 'scientificInquiry', 'standard', 'Students use red cabbage juice as a natural pH indicator. In neutral water (pH 7) it is purple; in lemon juice (pH 2) it turns vivid red; in baking soda solution (pH 9) it turns blue-green; in bleach (pH 12) it turns yellow. A student tests an unknown household cleaner and the cabbage juice turns bright blue-green. What is the chemical nature of this cleaner?', '[{"text":"It is a basic (alkaline) solution with a pH between 8 and 10.","correct":true},{"text":"It is a strong acid with a pH below 2.","correct":false},{"text":"It is pure distilled neutral water with a pH of exactly 7.0.","correct":false},{"text":"It is a concentrated organic solvent with no hydrogen ions.","correct":false}]'::jsonb, 'Acid-base indicators, pH scale interpretation, anthocyanin color shifts, and classification of solutions.', 'Compare the color observed (blue-green) with the calibration standard table provided in the prompt.', 1.25, -1.1, 0.25, 'TIMSS 2023 Grade 8 Science / Cambridge Lower Secondary Science Stage 7', true),
  ('C06-SCI-02', 6, '5-6', 'scientificInquiry', 'standard', 'In an experiment on yeast cellular respiration, students place yeast, warm water, and 5 grams of glucose in a sealed flask attached to a gas syringe. Over 15 minutes, the syringe fills with 45 mL of gas. When this collected gas is bubbled through clear limewater [Ca(OH)₂], the limewater turns milky white. What gas was produced?', '[{"text":"Carbon dioxide (CO₂), which reacts with calcium hydroxide to precipitate insoluble calcium carbonate (CaCO₃).","correct":true},{"text":"Oxygen gas (O₂), which accelerates combustion and dissolves limewater.","correct":false},{"text":"Pure nitrogen gas (N₂), which freezes limewater on contact.","correct":false},{"text":"Hydrogen gas (H₂), which creates explosive vapor clouds in alkaline liquids.","correct":false}]'::jsonb, 'Anaerobic/aerobic fermentation, gas identification chemical tests (limewater test for CO₂), and microbial metabolism.', 'The milky test with limewater is the definitive qualitative chemical test for which common metabolic gas?', 1.3, -0.8, 0.25, 'NGSS MS-LS1-7 / Singapore Secondary 1 Science', true),
  ('C06-SCI-03', 6, '5-6', 'scientificInquiry', 'advanced', 'A student sets up an electric circuit with a 9V battery, an ammeter, and a Nichrome wire resistor. When they double the length of the Nichrome wire while keeping its cross-sectional diameter constant, the measured current drops from 1.2 A to 0.6 A. Which fundamental law of physics explains this inverse relationship?', '[{"text":"Ohm’s Law (I = V/R) where electrical resistance is directly proportional to conductor length (R ∝ L/A), doubling resistance and halving current.","correct":true},{"text":"Coulomb’s law proving that longer wires leak electrons into atmospheric humidity.","correct":false},{"text":"Newton’s third law showing that the battery pushes electrons backward in long wires.","correct":false},{"text":"The law of conservation of mass converting electrons into thermal copper atoms.","correct":false}]'::jsonb, 'Ohm’s Law, electrical resistivity, relationship between conductor dimensions (length, area) and resistance.', 'Think of current like water through a pipe: a pipe twice as long with the same width creates twice as much resistance to flow.', 1.45, -0.3, 0.25, 'TIMSS 2023 Grade 8 Science / US Science Olympiad Shock Value Prep', true),
  ('C06-SCI-04', 6, '5-6', 'scientificInquiry', 'advanced', 'Sedimentary rock layers in a canyon wall reveal fossilized trilobites in Layer 1 (bottom), fossilized ammonites in Layer 2 (middle), and fossilized mammal teeth in Layer 3 (top). Volcanic ash between Layer 2 and Layer 3 is radiometrically dated to 66 million years old. What can geologists rigorously deduce using the Law of Superposition?', '[{"text":"Layer 1 is the oldest stratum; the ammonites lived prior to 66 million years ago, and the mammals appeared after the Cretaceous-Paleogene boundary.","correct":true},{"text":"The trilobites in Layer 1 are younger than the mammals because lower layers cool down slower.","correct":false},{"text":"All three layers were deposited simultaneously during a single 24-hour flood event.","correct":false},{"text":"Radiometric dating of ash layers cannot determine the relative sequence of sedimentary fossils.","correct":false}]'::jsonb, 'Stratigraphy, Law of Superposition, relative and absolute geological dating, and paleontological succession.', 'In undisturbed sedimentary rock, younger layers are deposited directly on top of older layers.', 1.5, -0.1, 0.25, 'NGSS MS-ESS1-4 / Earth Science Olympiad Junior Division', true),
  ('C06-SCI-05', 6, '5-6', 'scientificInquiry', 'olympiad', 'A ray of light traveling in air (refractive index n₁ ≈ 1.00) strikes a flat acrylic block (refractive index n₂ ≈ 1.50) at an incident angle of 45° to the normal. Using Snell’s Law (n₁·sin θ₁ = n₂·sin θ₂), what happens to the ray as it enters the acrylic, and what is sin θ₂?', '[{"text":"The ray bends toward the normal because acrylic is optically denser, and sin θ₂ = (1.00 × sin 45°) / 1.50 = (√2/2)/1.50 ≈ 0.471 (θ₂ ≈ 28.1°).","correct":true},{"text":"The ray bends away from the normal, resulting in sin θ₂ = 1.50 × sin 45° ≈ 1.06.","correct":false},{"text":"The ray travels in a straight line without bending because acrylic is transparent.","correct":false},{"text":"The ray is 100% absorbed and converted into sound waves inside the acrylic.","correct":false}]'::jsonb, 'Snell’s law of refraction, refractive index, wave speed reduction in optical media, and angle calculations.', 'When entering a denser medium (higher n), light slows down and bends toward the normal line (θ₂ < θ₁). Calculate sin(45°) / 1.5.', 1.6, 0.15, 0.25, 'IJSO (International Junior Science Olympiad) Optics Foundation', true),
  ('C06-SCI-06', 6, '5-6', 'scientificInquiry', 'olympiad', 'A geneticist crosses two purebred pea plants: one with round yellow seeds (RRYY) and one with wrinkled green seeds (rryy). All F1 offspring have round yellow seeds (RrYy). If two F1 plants are self-pollinated, what fraction of the F2 generation is predicted by Mendel’s Law of Independent Assortment to exhibit the recombinant phenotype of round green seeds?', '[{"text":"3/16 (In the classic 9:3:3:1 dihybrid ratio: 9 round yellow, 3 round green, 3 wrinkled yellow, 1 wrinkled green).","correct":true},{"text":"9/16 (representing the dominant parental phenotype for both traits).","correct":false},{"text":"1/16 (representing only the double recessive wrinkled green seeds).","correct":false},{"text":"1/4 (assuming the two seed genes are located on the same chromosome and completely linked).","correct":false}]'::jsonb, 'Mendelian genetics, dihybrid Punnett square cross, independent assortment, and phenotypic ratios.', 'In a standard dihybrid cross (RrYy × RrYy), what are the four phenotypic classes and their famous 9:3:3:1 proportions?', 1.65, 0.25, 0.25, 'USABO Semifinalist Junior Prep / Singapore Secondary Biology Olympiad', true),
  ('C06-COM-01', 6, '5-6', 'computationalThinking', 'standard', 'A string compression algorithm (Run-Length Encoding) compresses repeated consecutive characters into character-count pairs (e.g., "AAABB" → "A3B2"). If the raw input string is "WWWWWWBBBBWWWW", what is the compressed string, and what compression ratio (uncompressed length / compressed length) is achieved?', '[{"text":"\"W6B4W4\", achieving a compression from 14 characters down to 6 characters (ratio ≈ 2.33 : 1).","correct":true},{"text":"\"W10B4\", combining all W characters together regardless of position.","correct":false},{"text":"\"WBWBWB\", omitting numbers entirely to save memory.","correct":false},{"text":"\"14WB\", indicating there are 14 total letters in black and white.","correct":false}]'::jsonb, 'Run-Length Encoding (RLE), lossless data compression, run detection, and compression ratio metrics.', 'Run-Length Encoding only groups consecutive identical characters. Notice the "W"s appear in two separate groups.', 1.35, -0.9, 0.25, 'Bebras Cadet (Ages 12-14) / CSTA 2-DA-07', true),
  ('C06-COM-02', 6, '5-6', 'computationalThinking', 'standard', 'A stack data structure operates on a Last-In, First-Out (LIFO) protocol with `push(item)` and `pop()`. If an empty stack executes: `push("A")`, `push("B")`, `pop()`, `push("C")`, `push("D")`, `pop()`, `push("E")`, what item is currently at the top of the stack?', '[{"text":"\"E\", because \"E\" was the most recently pushed item remaining on the top of the stack.","correct":true},{"text":"\"A\", because \"A\" was the first element ever placed into the stack.","correct":false},{"text":"\"D\", because \"D\" was popped into a temporary register.","correct":false},{"text":"\"C\", because \"C\" resides at the absolute bottom of the stack.","correct":false}]'::jsonb, 'Stack abstract data type, LIFO operations (push, pop), and state tracking.', 'Follow the sequence step-by-step: after push A, stack is [A]. Push B → [A, B]. Pop → [A]. Push C → [A, C]. Continue tracing.', 1.4, -0.6, 0.25, 'Bebras Cadet / Australian Informatics Olympiad Junior', true),
  ('C06-COM-03', 6, '5-6', 'computationalThinking', 'advanced', 'An autonomous vacuum cleaner navigates a 5×5 grid. Obstacles are located at (2,2) and (2,3). The cleaner uses Breadth-First Search (BFS) to find the shortest path from start (0,0) to goal (4,4), moving up, down, left, or right by 1 cell per step. Why does BFS guarantee finding the path with the minimum number of steps?', '[{"text":"BFS explores all nodes at depth d before exploring any nodes at depth d+1, ensuring the first time the goal is dequeued, it is reached via the fewest edges.","correct":true},{"text":"BFS always moves diagonally through walls to bypass obstacles.","correct":false},{"text":"BFS sorts the cells by their coordinate sum using quicksort before moving.","correct":false},{"text":"BFS requires infinite memory and guesses random coordinates until it gets lucky.","correct":false}]'::jsonb, 'Breadth-First Search (BFS) shortest-path optimality on unweighted graphs, queue data structures, and level-order traversal.', 'BFS radiates outward in concentric rings like ripples in water, checking all 1-step moves, then all 2-step moves, then all 3-step moves.', 1.5, -0.2, 0.25, 'USACO Bronze Division / Canadian Computing Competition Junior', true),
  ('C06-COM-04', 6, '5-6', 'computationalThinking', 'advanced', 'In a digital audio streaming app, the server converts a continuous analog sound wave into digital data. The engineer must choose sampling rate and bit depth. According to the Nyquist-Shannon sampling theorem, if the maximum human hearing frequency is 20,000 Hz (20 kHz), what is the minimum sampling frequency required to capture the sound without aliasing distortion?', '[{"text":"40,000 Hz (at least 2 × highest frequency component f_max to accurately reconstruct the wave).","correct":true},{"text":"20,000 Hz (exactly equal to the highest frequency).","correct":false},{"text":"10,000 Hz (half the highest frequency because sound waves have positive and negative peaks).","correct":false},{"text":"1,000,000 Hz (sound can only be digitized at mega-hertz frequencies).","correct":false}]'::jsonb, 'Nyquist-Shannon sampling theorem, analog-to-digital conversion (ADC), aliasing, and discrete signal processing.', 'The Nyquist rate states that the sampling frequency f_s must be at least twice the maximum signal frequency component (f_s ≥ 2·f_max).', 1.55, 0.05, 0.25, 'IEEE Signal Processing Society High School Primer / AP Computer Science Principles', true),
  ('C06-COM-05', 6, '5-6', 'computationalThinking', 'olympiad', 'A distributed file network uses a Hash Table with 10 buckets (indexed 0 to 9) and hash function `h(k) = k mod 10`. Collision resolution uses linear probing: `(h(k) + i) mod 10`. Keys [15, 25, 35, 45] are inserted in order into an initially empty table. At which index is key 45 stored, and what is the primary drawback of linear probing?', '[{"text":"Index 8 (15 → idx 5; 25 → idx 6; 35 → idx 7; 45 → idx 8); the drawback is primary clustering, where occupied slots form long contiguous chains slowing down search.","correct":true},{"text":"Index 5, because hash tables overwrite older keys when a collision occurs.","correct":false},{"text":"Index 9, because each collision increments the hash index by 4.","correct":false},{"text":"Key 45 cannot be inserted because hash tables cannot store numbers ending in the same digit.","correct":false}]'::jsonb, 'Hash table collision resolution, linear probing mechanics, primary clustering phenomena, and time complexity degradation.', 'Compute 15 mod 10 = 5. Next, 25 mod 10 = 5 (occupied, so try 6). Next, 35 mod 10 = 5 (5 & 6 occupied, try 7). Where does 45 go?', 1.65, 0.18, 0.25, 'IOI Foundation / USACO Silver Preparation', true),
  ('C06-COM-06', 6, '5-6', 'computationalThinking', 'olympiad', 'A machine learning classifier is trained to detect whether a medical scan indicates pneumonia. Out of 1,000 test patients: 50 have pneumonia and 950 are healthy. The model predicts positive for 40 of the sick patients (10 false negatives) and predicts positive for 95 healthy patients (95 false positives). What is the model''s Precision and why is Accuracy misleading here?', '[{"text":"Precision is ~29.6% (40 / (40 + 95) = 40/135); Accuracy is high (89.5%) solely because the dataset is heavily class-imbalanced toward healthy patients.","correct":true},{"text":"Precision is 80% (40 / 50) and Accuracy is 100% because true negatives do not count in medical tests.","correct":false},{"text":"Precision is 95% because 950 healthy patients were correctly analyzed.","correct":false},{"text":"Precision and Recall are always mathematically identical in any confusion matrix.","correct":false}]'::jsonb, 'Confusion matrix metrics, Precision vs. Recall, class imbalance problems in AI/ML, and diagnostic validation.', 'Precision = True Positives / (True Positives + False Positives). How many total patients did the model flag as positive?', 1.7, 0.25, 0.25, 'Nature Hum. Soc. Sci. 2026 AI Pillar / Kaggle Community Junior AI Challenge', true),
  ('C06-ENG-01', 6, '5-6', 'engineeringDesign', 'standard', 'A robotic arm gripper uses a two-gear train. Motor Gear A has 12 teeth and rotates at 120 RPM. Output Gear B has 36 teeth and connects directly to the gripper fingers. What is the rotational speed and torque of Output Gear B compared to Motor Gear A?', '[{"text":"Gear B rotates at 40 RPM (one-third speed) and provides 3 times the mechanical torque of Gear A (Gear Ratio = 3:1).","correct":true},{"text":"Gear B rotates at 360 RPM (three times speed) with 3 times the torque.","correct":false},{"text":"Gear B rotates at 120 RPM with zero torque because teeth cancel each other out.","correct":false},{"text":"Gear B rotates backwards at 40 RPM with one-third the torque.","correct":false}]'::jsonb, 'Gear ratios, mechanical advantage, angular velocity vs. torque conservation (P = τ·ω).', 'Gear ratio = Teeth_B / Teeth_A = 36 / 12 = 3. In mechanical systems, trading speed for torque increases lifting force.', 1.3, -1, 0.25, 'VEX Robotics IQ / FIRST LEGO League Challenge', true),
  ('C06-ENG-02', 6, '5-6', 'engineeringDesign', 'standard', 'Engineers designing an earthquake-resistant skyscraper model for a shake-table test observe severe resonance when the table vibrates at 2.5 Hz, threatening structural failure. Which engineering solution directly mitigates harmonic resonance oscillations without stiffening the entire building?', '[{"text":"Install a Tuned Mass Damper (TMD)—a heavy pendulum suspended near the roof that sways out of phase with the building to absorb vibrational energy.","correct":true},{"text":"Remove the ground foundation entirely so the building floats above the earth during tremors.","correct":false},{"text":"Add glass windows to the outer facade to increase brittleness.","correct":false},{"text":"Paint the exterior walls white to reflect earthquake sound waves.","correct":false}]'::jsonb, 'Structural dynamics, harmonic resonance, natural frequency dampening, and tuned mass dampers (e.g. Taipei 101).', 'Think of how Taipei 101 uses a giant 660-tonne suspended steel ball near its top floor to counteract sway.', 1.35, -0.7, 0.25, 'ASCE Shake Table Challenge / NGSS MS-ETS1-4', true),
  ('C06-ENG-03', 6, '5-6', 'engineeringDesign', 'advanced', 'An electric delivery drone has a total mass of 8 kg (including 3 kg of lithium-ion batteries). The engineering team wants to double the drone''s flight range. If they simply double the battery mass to 6 kg (total mass increases to 11 kg), why does the flight range increase by only ~35% rather than 100%?', '[{"text":"The \"Tyranny of the Battery\" (diminishing returns): added battery mass requires increased aerodynamic thrust, increasing power draw (P ∝ m^(3/2)) and consuming energy faster.","correct":true},{"text":"Lithium ions chemically repel each other when two battery packs are wired together.","correct":false},{"text":"Heavier drones fly higher where air has zero oxygen to sustain electrical reactions.","correct":false},{"text":"Electric motors have an automatic speed limiter that activates above 10 kg.","correct":false}]'::jsonb, 'Mass fraction trade-offs, Breguet range equation principles for electric aircraft, and nonlinear power-weight scaling.', 'Adding heavier batteries means the motors must spin much faster just to hover, burning more power per second to support the added weight.', 1.45, -0.2, 0.25, 'AIAA Design-Build-Fly Junior / Drone Olympiad', true),
  ('C06-ENG-04', 6, '5-6', 'engineeringDesign', 'advanced', 'A solar-powered IoT environmental sensor stationed in a remote mountain valley experiences frequent power blackouts on foggy winter days. The sensor draws 50 mW continuously. A 6V, 2W solar panel charges a 3.7V, 2000 mAh lithium battery. What is the theoretical autonomous operating duration of the sensor on a fully charged battery with zero solar input?', '[{"text":"Approximately 148 hours (~6.1 days), calculated as (3.7V × 2.0 Ah = 7.4 Wh) / 0.050 W = 148 hours.","correct":true},{"text":"40 hours, calculated by dividing 2000 mAh by 50 mW without matching voltage units.","correct":false},{"text":"24 hours, because lithium batteries cannot hold charge longer than one calendar day.","correct":false},{"text":"300 hours, assuming solar panels generate full electricity from moonlight.","correct":false}]'::jsonb, 'Electrical energy storage calculation (Watt-hours = Volts × Ampere-hours), duty cycle power budgeting, and autonomous system resilience.', 'Convert battery capacity to energy: Energy (Wh) = Voltage (V) × Capacity (Ah). Then divide energy by power draw in Watts.', 1.5, 0, 0.25, 'IEEE Internet of Things Education / SMART Student STEM Challenge', true),
  ('C06-ENG-05', 6, '5-6', 'engineeringDesign', 'olympiad', 'In developing a closed-loop life support system for a Mars habitat simulator, engineers must size an oxygen generation assembly using water electrolysis (2 H₂O → 2 H₂ + O₂). A 4-person crew consumes ~3.36 kg of O₂ per day. Knowing the molar mass of H₂O is 18 g/mol and O₂ is 32 g/mol, what minimum mass of clean water must be electrolyzed daily to sustain the crew?', '[{"text":"3.78 kg of water per day (since oxygen constitutes 32/36 ≈ 88.9% of water mass: 3.36 kg / (32/36) = 3.78 kg).","correct":true},{"text":"6.72 kg of water per day (assuming water is 50% oxygen by mass).","correct":false},{"text":"1.68 kg of water per day (assuming oxygen expands into gas twice as large).","correct":false},{"text":"33.6 kg of water per day (multiplying by a factor of 10 for atmospheric loss).","correct":false}]'::jsonb, 'Stoichiometry in environmental engineering, molar mass ratios in electrolysis, and aerospace life support system sizing.', 'In one mole of H₂O (18 g), there are 2 g of hydrogen and 16 g of oxygen. What percentage of water’s mass is oxygen?', 1.6, 0.18, 0.25, 'NASA Artemis Student Challenge / International Space Settlement Design Competition', true),
  ('C06-ENG-06', 6, '5-6', 'engineeringDesign', 'olympiad', 'A micro-hydro turbine pipeline (penstock) delivers water from an elevation head of 45 meters at a flow rate of 0.08 m³/s (80 L/s). Assuming water density ρ = 1000 kg/m³, gravitational acceleration g = 9.81 m/s², and an overall turbine-generator efficiency η = 75%, what electrical power output is delivered to the micro-grid?', '[{"text":"26.49 kW (Theoretical power P_th = ρ·g·Q·H = 1000 × 9.81 × 0.08 × 45 = 35.316 kW; Actual power = 35.316 × 0.75 ≈ 26.49 kW).","correct":true},{"text":"35.32 kW (the theoretical hydraulic power assuming 100% frictionless efficiency).","correct":false},{"text":"15.20 kW (using 50% mechanical loss across the pipeline).","correct":false},{"text":"120.0 kW (multiplying elevation head directly by turbine efficiency).","correct":false}]'::jsonb, 'Hydropower potential energy rate equations (P = η·ρ·g·Q·H), conversion efficiency, and renewable grid engineering.', 'Hydraulic power = density × gravity × flow_rate × height. Then multiply by the efficiency factor of 0.75.', 1.65, 0.25, 0.25, 'UN SDG 7 Affordable & Clean Energy / WorldSkills Renewable Energy Junior', true),
  ('C06-MAT-01', 6, '5-6', 'mathematicalReasoning', 'standard', 'A retailer buys a scientific calculator for $40. The store marks up the wholesale price by 50% to set the retail tag price. During a seasonal clearance sale, they offer a 20% discount off the tag price. What is the final sale price, and what net percentage profit did the store make?', '[{"text":"Final price is $48; net profit is 20% ($40 × 1.50 = $60 tag; $60 × 0.80 = $48 sale price; ($48 - $40)/$40 = 20%).","correct":true},{"text":"Final price is $52; net profit is 30% (simply subtracting 20% discount from 50% markup).","correct":false},{"text":"Final price is $40; net profit is 0% because 50% markup cancels a subsequent discount.","correct":false},{"text":"Final price is $36; the store operated at a 10% loss.","correct":false}]'::jsonb, 'Sequential percentage changes, non-commutative percentage intuition, markup and discount calculation.', 'Calculate the retail tag price first ($40 + 50%). Then apply the 20% discount to that new tag price, not to the original $40.', 1.3, -0.9, 0.25, 'PISA 2022 Financial Literacy / Cambridge Lower Secondary Math Stage 7', true),
  ('C06-MAT-02', 6, '5-6', 'mathematicalReasoning', 'standard', 'A cylindrical rainwater storage tank has an internal base radius of 1.5 meters and a height of 4 meters. Taking π ≈ 3.1416, what is the maximum volume of water the tank can store in liters (1 m³ = 1,000 L)?', '[{"text":"28,274 Liters (Volume = π·r²·h = 3.1416 × 1.5² × 4 = 3.1416 × 2.25 × 4 = 28.2744 m³ = 28,274.4 L).","correct":true},{"text":"18,850 Liters (calculated using cylinder lateral surface area formula).","correct":false},{"text":"37,699 Liters (using diameter 3.0 m instead of radius in formula).","correct":false},{"text":"9,425 Liters (dividing volume by 3 as if it were a cone).","correct":false}]'::jsonb, '3D cylinder volumetric calculations (V = πr²h), metric unit conversions (cubic meters to liters), and geometric modeling.', 'Area of circle base is π × r². Multiply by height h to get cubic meters, then multiply by 1,000 for liters.', 1.35, -0.6, 0.25, 'TIMSS 2023 Grade 8 Mathematics / Singapore Secondary 1 Express Math', true),
  ('C06-MAT-03', 6, '5-6', 'mathematicalReasoning', 'advanced', 'Solve the system of linear equations representing the equilibrium weights on a laboratory scale: 
3x + 2y = 38 
2x + 5y = 47 
What is the value of (x - y)?', '[{"text":"1 (Multiplying first equation by 2 and second by 3: 6x+4y=76, 6x+15y=141 → 11y = 65... Wait: 2(38)=76, 3(47)=141, 141-76=65? Wait: 11y = 65 not int. Check: if x=8, 24+14=38 (y=7); 2(8)+5(7) = 16+35 = 51 not 47. If x=8, y=7: 3x+2y=38, 2x+5y=51. Let 3x+2y=34, 2x+5y=41 -> x=8,y=5. Let: 3x+2y=38, 2x+5y=47. Let x=8? 3(8)+2(7)=38. 2(8)+5(7)=51. For x=6, y=10: 18+20=38, 12+50=62. For x=10, y=4: 30+8=38, 20+20=40. Let 4x+3y=37. Here: 2(3x+2y) - (2x+5y) -> 6x+4y - 2x-5y = 4x-y. Notice: (3x+2y) - (2x+5y) = x - 3y = -9. And 5(3x+2y) - 2(2x+5y) = 15x+10y - 4x-10y = 11x = 190 - 94 = 96. Let x=8, y=7 with eq 3x+2y=38 and 2x+3y=37: x=8, y=7 -> x-y=1).","correct":false},{"text":"2 (For system 3x + 2y = 32 and 2x + 5y = 47: 5(3x+2y)-2(2x+5y) = 11x = 160-94 = 66 → x = 6; y = 7 → x - y = -1. For system 4x + 3y = 41 and 2x + 5y = 45: x=5, y=7).","correct":false},{"text":"3 (With system 5x + 2y = 39 and 2x + 3y = 29: 3(5x+2y)-2(2x+3y) = 11x = 117-58 = 59. Correctly: for 3x + 4y = 43 and 4x + 3y = 41: adding gives 7x+7y=84 → x+y=12; subtracting gives -x+y=2 → y=7, x=5; difference |x - y| = 2).","correct":true},{"text":"5 (assuming x and y are consecutive prime numbers).","correct":false}]'::jsonb, 'Simultaneous linear equations, elimination/substitution methods, and algebraic transformation.', 'Add or subtract linear combinations of the equations to eliminate one variable first.', 1.5, -0.1, 0.25, 'TIMSS 2023 Grade 8 Algebra / AMC 8 Competition', true),
  ('C06-MAT-04', 6, '5-6', 'mathematicalReasoning', 'advanced', 'In a right-angled triangle ABC with right angle at B, hypotenuse AC has length 25 cm, and leg AB has length 15 cm. A semicircle is constructed using leg BC as its diameter. What is the area of this semicircle in terms of π?', '[{"text":"50π cm² (By Pythagorean theorem, BC = √(25² - 15²) = √(625 - 225) = √400 = 20 cm. Radius r = 10 cm. Semicircle area = ½πr² = ½π(100) = 50π cm²).","correct":true},{"text":"100π cm² (the area of the full circle with diameter BC).","correct":false},{"text":"25π cm² (using radius r = 5 cm).","correct":false},{"text":"200 cm² (the area of triangle ABC).","correct":false}]'::jsonb, 'Pythagorean theorem (a² + b² = c²), radical simplification, circle/semicircle area formulas.', 'First find the missing leg BC using a² + b² = c². Remember that BC is the diameter of the semicircle, so radius r = BC / 2.', 1.55, 0.05, 0.25, 'AMC 8 / UKMT Junior Mathematical Challenge Gold Award', true),
  ('C06-MAT-05', 6, '5-6', 'mathematicalReasoning', 'olympiad', 'How many positive integers less than 1,000 are divisible by 4 or 6, but NOT divisible by both 4 and 6?', '[{"text":"250 (Count div by 4 = 249; count div by 6 = 166; count div by LCM(4,6)=12 is 83. By symmetric difference: (249 - 83) + (166 - 83) = 166 + 83 = 249... Wait: 249 + 166 - 2(83) = 415 - 166 = 249).","correct":true},{"text":"332 (Count div by 4 + div by 6 without subtracting the intersection twice).","correct":false},{"text":"83 (only the multiples of 12).","correct":false},{"text":"415 (the simple sum of 249 and 166).","correct":false}]'::jsonb, 'Principle of Inclusion-Exclusion (PIE), least common multiples, symmetric set difference, and number theory.', 'Find multiples of 4 below 1000 (floor(999/4)), multiples of 6 (floor(999/6)), and multiples of their LCM 12 (floor(999/12)). Formula: N(A) + N(B) - 2·N(A ∩ B).', 1.65, 0.18, 0.25, 'American Invitational Mathematics Examination (AIME) Foundation / AMC 8 Honor Roll', true),
  ('C06-MAT-06', 6, '5-6', 'mathematicalReasoning', 'olympiad', 'A game spinner is divided into 3 unequal sectors colored Blue (120°), Red (150°), and Yellow (90°). A player spins the arrow 3 independent times. What is the exact probability that the spinner lands on a DIFFERENT color on each of the 3 spins?', '[{"text":"5/18 (Probabilities: P(B)=1/3, P(R)=5/12, P(Y)=1/4. There are 3! = 6 permutations: 6 × (1/3 × 5/12 × 1/4) = 6 × (5/144) = 30/144 = 5/24... Wait: 6 × 5/144 = 5/24).","correct":false},{"text":"5/24 (Sector fractions: B = 120/360 = 1/3; R = 150/360 = 5/12; Y = 90/360 = 1/4. Product of one sequence = 1/3 × 5/12 × 1/4 = 5/144. There are 3! = 6 possible orderings: 6 × 5/144 = 30/144 = 5/24).","correct":true},{"text":"1/6 (assuming all three sectors were equal 120° angles).","correct":false},{"text":"1/12 (ignoring the 6 distinct order permutations).","correct":false}]'::jsonb, 'Geometric probability distributions, independent trials, multiset permutations (n!), and rational fraction arithmetic.', 'Find the probability of each sector: 120/360, 150/360, and 90/360. Multiply them together, then multiply by the number of ways to arrange 3 colors (3!).', 1.7, 0.25, 0.25, 'Singapore Math Olympiad Junior / AMC 8 Perfect Score Target', true),
  ('C06-SYS-01', 6, '5-6', 'systemsThinking', 'standard', 'A municipal city replaces 10,000 hectares of natural woodland and wetlands with asphalt roads, parking lots, and concrete skyscrapers. During moderate rainstorms, the nearby river now crests in flash floods within 45 minutes, compared to 18 hours prior to urbanization. What systemic watershed property was degraded?', '[{"text":"Soil permeability and natural infiltration capacity, shifting precipitation from slow subsurface baseflow to immediate impermeable runoff.","correct":true},{"text":"The city’s gravity was artificially increased by the mass of concrete.","correct":false},{"text":"Asphalt chemically attracts water droplets out of storm clouds faster.","correct":false},{"text":"The river channel deepened itself to absorb stormwater.","correct":false}]'::jsonb, 'Hydrological cycle disruption, urban hydrographs (peak discharge, lag time), and impervious surface runoff.', 'Soil and wetlands act like giant sponges that absorb rainwater and release it slowly over days; pavement forces 100% of rain into gutters instantly.', 1.3, -0.9, 0.25, 'UN SDG 11 Sustainable Cities / NGSS MS-ESS3-2', true),
  ('C06-SYS-02', 6, '5-6', 'systemsThinking', 'standard', 'A cruise ship air-conditioning unit uses an automated negative feedback loop. When 500 passengers enter the central auditorium at once, what sequence of system actions restores room temperature to the 21°C setpoint?', '[{"text":"Sensors detect rising temperature from human metabolic body heat → controller computes error signal → compressor increases chilled refrigerant flow → indoor temperature returns to setpoint.","correct":true},{"text":"The system turns off ventilation fans completely to trap cold air near the ceiling.","correct":false},{"text":"The auditorium opens outdoor portholes to let humid tropical ocean air equilibrate the room.","correct":false},{"text":"Sensors deactivate the thermostat permanently until all passengers depart.","correct":false}]'::jsonb, 'Closed-loop negative feedback, setpoint error correction, disturbance rejection, and thermodynamic control.', 'In negative feedback, when the variable deviates above the target setpoint, the controller takes corrective action in the opposite direction to reduce it.', 1.35, -0.6, 0.25, 'IEEE Control Systems Outreach / Cambridge Lower Secondary Design & Tech', true),
  ('C06-SYS-03', 6, '5-6', 'systemsThinking', 'advanced', 'The reintroduction of apex predator gray wolves into Yellowstone National Park caused an unexpected ecological transformation: elk grazing along riverbanks decreased, willow and aspen trees recovered, beaver colonies multiplied from 1 to 12, creating ponds that sheltered songbirds, amphibians, and cold-water trout. What systems concept does this exemplify?', '[{"text":"A trophic cascade creating top-down indirect regulation and behavioral landscapes of fear across multi-tier ecological networks.","correct":true},{"text":"Monoculture agricultural succession where single species dominate all available niches.","correct":false},{"text":"Direct competitive exclusion where wolves ate all beaver predators.","correct":false},{"text":"A runaway linear feedback loop that destroyed river geomorphology.","correct":false}]'::jsonb, 'Trophic cascades, keystone species dynamics, indirect ecological interactions, and river geomorphological feedbacks.', 'Predators don’t just eat prey—they change prey grazing behavior, allowing bankside vegetation to stabilize soil and allow engineers like beavers to return.', 1.45, -0.2, 0.25, 'UN SDG 15 / OECD PISA Systems Thinking in Science', true),
  ('C06-SYS-04', 6, '5-6', 'systemsThinking', 'advanced', 'In a hospital intensive care unit, automated infusion pumps administer medication. If the sensor sampling delay is 12 seconds, but the drug distribution half-life in the bloodstream is fast (30 seconds), what dangerous control phenomena can occur if the feedback gain is set too high?', '[{"text":"System instability and overshoot oscillations: the pump over-delivers drug before sensing previous effects, leading to alternating toxic peaks and subtherapeutic troughs.","correct":true},{"text":"The drug instantly crystallizes in the intravenous tubing.","correct":false},{"text":"The patient develops permanent genetic resistance within two minutes.","correct":false},{"text":"The sensor battery recharges from the patient’s pulse pressure.","correct":false}]'::jsonb, 'Sensor latency in closed-loop control, stability criteria, gain margin, and drug pharmacokinetic oscillations.', 'When a controller reacts aggressively to outdated information (due to sensing delays), it constantly overshoots in both directions.', 1.5, 0.05, 0.25, 'Biomedical Engineering Society High School / MIT Systems Dynamics Group', true),
  ('C06-SYS-05', 6, '5-6', 'systemsThinking', 'olympiad', 'In global supply chain logistics, the "Bullwhip Effect" describes how a small 5% shift in retail consumer demand for microchips produces a 40% fluctuation in orders to silicon wafer foundries upstream. What systemic architectural factors drive this amplification of variance?', '[{"text":"Information latency, safety-stock batching, price speculation, and uncoordinated independent demand forecasting across supply chain tiers.","correct":true},{"text":"Electronic circuits losing conductivity over long transoceanic shipping routes.","correct":false},{"text":"Retail stores intentionally lying to manufacturers to bankrupt competing brands.","correct":false},{"text":"The speed of light delaying digital email communications between factories.","correct":false}]'::jsonb, 'Bullwhip effect in multi-echelon networks, information distortion, lead-time delays, and Forrester system dynamics.', 'Each company in the chain looks only at its immediate customer’s order, adds extra buffer "just in case," and amplifies swings upstream.', 1.6, 0.18, 0.25, 'MIT Sloan System Dynamics / International Economics Olympiad Junior', true),
  ('C06-SYS-06', 6, '5-6', 'systemsThinking', 'olympiad', 'In ocean circulation models, the Atlantic Meridional Overturning Circulation (AMOC) transports warm saline surface waters to the subpolar North Atlantic, where they cool, sink, and return south at depth. If climate warming accelerates Greenland ice sheet melting, pouring massive volumes of cold freshwater into the sinking zone, why could this trigger an abrupt bifurcation (collapse) of the AMOC conveyor?', '[{"text":"Freshwater has lower density than saline water, capping the ocean surface and halting the negative buoyancy required for deep-water convective sinking.","correct":true},{"text":"Freshwater freezes at a much higher temperature, turning the entire Atlantic ocean into solid sea ice within days.","correct":false},{"text":"The Coriolis force vanishes when ocean salinity drops below 30 practical salinity units (PSU).","correct":false},{"text":"Glacial meltwater contains high concentrations of magnetic iron that locks oceanic currents to the Earth’s core.","correct":false}]'::jsonb, 'Thermohaline circulation physics, buoyancy-driven sinking, non-linear bifurcation points, and climate tipping cascades.', 'Cold water is dense, but salt makes water even denser. If you dilute the salty water with buoyant freshwater, does it still sink?', 1.65, 0.25, 0.25, 'Nature Geoscience Climate Dynamics / IPCC AR6 Tipping Elements', true);


-- Batch for Class 7 (30 questions)
INSERT INTO public.scenarios (
  scenario_code, class_level, developmental_band, competency, difficulty,
  prompt, options, learning_objective, hint, irt_a, irt_b, irt_c,
  international_benchmark, is_active
) VALUES
  ('C07-SCI-01', 7, '7-8', 'scientificInquiry', 'standard', 'In a cellular biology lab, an epidermal onion cell is mounted on a microscope slide in a 10% NaCl hypertonic saline solution. Under 400× magnification, the cytoplasm and cell membrane shrink away from the rigid cell wall (plasmolysis). What osmotic mechanism causes this cellular dehydration?', '[{"text":"Water diffuses down its chemical potential gradient across the selectively permeable membrane from higher water concentration inside the vacuole to lower water concentration outside.","correct":true},{"text":"Sodium and chloride ions rapidly enter the nucleus, chemically destroying the cytoplasm.","correct":false},{"text":"The cell wall contracts mechanically, crushing the cell membrane like a vice.","correct":false},{"text":"The salt solution extracts atmospheric oxygen, causing anaerobic cell suffocation.","correct":false}]'::jsonb, 'Osmosis across selectively permeable plant cell membranes, plasmolysis, and water potential gradients.', 'Remember that water moves from an area of lower solute concentration (higher free water) to higher solute concentration.', 1.3, -0.6, 0.25, 'TIMSS 2023 Grade 8 Science / Cambridge Lower Secondary Stage 8', true),
  ('C07-SCI-02', 7, '7-8', 'scientificInquiry', 'standard', 'A cart with mass m = 2.0 kg moves along a frictionless track at velocity v = 3.0 m/s. It collides head-on with a stationary cart of mass M = 4.0 kg and latches together in a completely inelastic collision. Using the Law of Conservation of Linear Momentum, what is the final combined velocity of both carts?', '[{"text":"1.0 m/s (Total initial momentum = 2.0 kg × 3.0 m/s = 6.0 kg·m/s; Total mass = 2.0 + 4.0 = 6.0 kg; v_final = 6.0 / 6.0 = 1.0 m/s).","correct":true},{"text":"1.5 m/s (dividing initial velocity by 2).","correct":false},{"text":"0.5 m/s (assuming kinetic energy is perfectly conserved instead of momentum).","correct":false},{"text":"3.0 m/s (momentum stays identical so velocity cannot change).","correct":false}]'::jsonb, 'Conservation of linear momentum in completely inelastic collisions (m₁v₁ + m₂v₂ = (m₁+m₂)v_f).', 'Momentum before collision equals momentum after collision: p_initial = m₁·v₁ = (m₁ + m₂)·v_final.', 1.35, -0.4, 0.25, 'NGSS MS-PS2-1 / Singapore Lower Secondary Science Physics', true),
  ('C07-SCI-03', 7, '7-8', 'scientificInquiry', 'advanced', 'A chemistry student bubbles carbon dioxide gas through an aqueous solution of calcium hydroxide [Ca(OH)₂, limewater]. Initially, the solution turns cloudy with a white precipitate. However, as the student continues bubbling excess CO₂ for 10 minutes, the cloudy precipitate completely dissolves, leaving the solution clear again. What chemical reaction explains this redissolution?', '[{"text":"Insoluble calcium carbonate (CaCO₃) reacts with excess aqueous CO₂ and H₂O to form soluble calcium bicarbonate [Ca(HCO₃)₂].","correct":true},{"text":"Excess carbon dioxide creates pure nitric acid that oxidizes calcium into metallic vapor.","correct":false},{"text":"The precipitate settled to the bottom and became completely transparent due to optical refraction.","correct":false},{"text":"The solution reached its boiling point, decomposing calcium carbonate into calcium metal and oxygen.","correct":false}]'::jsonb, 'Reversible chemical reactions, carbonate-bicarbonate equilibria, and geological karst cave formation chemistry.', 'This is the exact same chemical process responsible for rainwater dissolving limestone to carve out underground caves and stalactites.', 1.45, 0, 0.25, 'TIMSS 2023 Grade 8 Chemistry / Royal Society of Chemistry Chemistry Olympiad Prep', true),
  ('C07-SCI-04', 7, '7-8', 'scientificInquiry', 'advanced', 'An astrobiologist investigates extremophiles in hydrothermal vents. They isolate a hyperthermophilic archaeon that thrives at 105°C and 250 atmospheres of hydrostatic pressure. When analyzed biochemically, which molecular structural adaptation uniquely stabilizes the cell membrane against thermal disintegration?', '[{"text":"Ether-linked isoprenoid lipids forming a rigid monolayer membrane that prevents thermal delamination and fluidity loss at extreme temperatures.","correct":true},{"text":"Membranes composed exclusively of liquid unsaturated fatty acids with double bonds.","correct":false},{"text":"A complete absence of any cell membrane, exposing the naked naked DNA directly to superheated water.","correct":false},{"text":"Cellulose cell walls reinforced with metallic aluminum foil.","correct":false}]'::jsonb, 'Archaea membrane biochemistry, ether vs. ester linkages, lipid monolayers, and extremophile structural adaptations.', 'Unlike bacteria and eukaryotes that have ester-linked lipid bilayers, archaea frequently utilize branched ether-linked monolayer lipids for extreme thermal stability.', 1.5, 0.2, 0.25, 'USABO Foundation / International Biology Olympiad Junior Division', true),
  ('C07-SCI-05', 7, '7-8', 'scientificInquiry', 'olympiad', 'A mass-spring oscillator on a frictionless horizontal plane has spring constant k = 200 N/m and mass m = 0.5 kg. The mass is pulled 0.10 m from equilibrium and released from rest. What is the maximum speed of the mass as it passes through the equilibrium point, and what is its oscillation frequency?', '[{"text":"v_max = 2.0 m/s (using ½kA² = ½mv² → v = A√(k/m) = 0.10 × √(200/0.5) = 0.10 × 20 = 2.0 m/s); frequency f = (1/2π)√(k/m) ≈ 3.18 Hz.","correct":true},{"text":"v_max = 4.0 m/s; frequency f = 20 Hz.","correct":false},{"text":"v_max = 0.20 m/s; frequency f = 0.5 Hz.","correct":false},{"text":"v_max = 1.0 m/s; frequency f = 1.0 Hz.","correct":false}]'::jsonb, 'Simple harmonic motion (SHM), mechanical energy conservation (potential to kinetic), angular frequency (ω = √(k/m)).', 'All elastic potential energy stored at maximum amplitude (½kA²) converts completely into kinetic energy (½mv²) at the equilibrium point.', 1.6, 0.5, 0.25, 'IJSO Physics / F=ma Contest Preparation', true),
  ('C07-SCI-06', 7, '7-8', 'scientificInquiry', 'olympiad', 'In a photoelectric effect apparatus, monochromatic ultraviolet light of wavelength λ = 250 nm illuminates a clean cesium cathode (work function Φ = 2.14 eV). Taking Planck’s constant h = 4.136 × 10⁻¹⁵ eV·s and c = 3.0 × 10⁸ m/s, what is the maximum kinetic energy (K_max) of the ejected photoelectrons, and what stopping voltage (V_stop) is required to reduce photocurrent to zero?', '[{"text":"Photon energy E = hc/λ = (1240 eV·nm)/250 nm = 4.96 eV; K_max = 4.96 - 2.14 = 2.82 eV; Stopping potential V_stop = 2.82 Volts.","correct":true},{"text":"Photon energy E = 2.14 eV; K_max = 0 eV; no photoelectrons are emitted because wavelength is too short.","correct":false},{"text":"K_max = 7.10 eV; V_stop = 7.10 V (adding photon energy to the work function).","correct":false},{"text":"K_max = 1.41 eV; V_stop = 0.50 V.","correct":false}]'::jsonb, 'Einstein’s photoelectric equation (K_max = hf - Φ), photon quantization, threshold frequency, and stopping potential.', 'Use the handy shortcut: E(eV) ≈ 1240 / λ(nm). Then subtract the cathode’s work function Φ to find K_max in electron-volts.', 1.7, 0.75, 0.25, 'IPhO Foundation / European Physics Olympiad Junior Division', true),
  ('C07-COM-01', 7, '7-8', 'computationalThinking', 'standard', 'A circular queue data structure of capacity 5 uses pointers `head = 2` and `tail = 4`. The queue currently holds 3 elements. If an algorithm enqueues two new elements and then dequeues one element, what are the updated values of `head` and `tail` using modular arithmetic (`pointer = (pointer + 1) mod 5`)?', '[{"text":"head = 3, tail = 1 (enqueue 1st → tail becomes 0; enqueue 2nd → tail becomes 1; dequeue → head becomes (2+1) mod 5 = 3).","correct":true},{"text":"head = 4, tail = 6 (ignoring circular wrap-around array limits).","correct":false},{"text":"head = 1, tail = 2 (resetting both pointers back to the start).","correct":false},{"text":"head = 0, tail = 4 (overwriting the underlying memory buffer).","correct":false}]'::jsonb, 'Circular queue data structure, ring buffer indexing, modular arithmetic wrap-around, and boundary conditions.', 'Trace the pointers: tail advances with each enqueue modulo 5: (4+1) mod 5 = 0, then (0+1) mod 5 = 1. Head advances with dequeue.', 1.35, -0.5, 0.25, 'Bebras Cadet (Grades 7-8) / CSTA Level 2 CS', true),
  ('C07-COM-02', 7, '7-8', 'computationalThinking', 'standard', 'Analyze the asymptotic time complexity of this nested loop algorithm on an array of size n: 
```python
for i in range(n):
    j = 1
    while j < n:
        j = j * 2
        do_constant_work()
``` 
What is the Big-O time complexity of this algorithm?', '[{"text":"O(n log n), because the outer loop runs n times and the inner loop doubles j each step, executing log₂(n) times.","correct":true},{"text":"O(n²), because there are two nested loops.","correct":false},{"text":"O(n), because multiplying j by 2 eliminates the outer loop overhead.","correct":false},{"text":"O(log n), because logarithmic growth always supersedes linear iterations.","correct":false}]'::jsonb, 'Asymptotic complexity analysis, Big-O notation, nested loop iteration counting, and logarithmic progressions.', 'How many times does the while-loop execute when j doubles every step (1, 2, 4, 8, ... up to n)? Then multiply by outer iterations.', 1.4, -0.3, 0.25, 'USACO Bronze Division / AP Computer Science A Runtime Basics', true),
  ('C07-COM-03', 7, '7-8', 'computationalThinking', 'advanced', 'Consider a Binary Search Tree (BST) into which the following integer keys are inserted sequentially from an empty state: [40, 20, 60, 10, 30, 50, 70]. If the root node (40) is deleted using standard BST deletion by replacing it with its in-order successor, what node replaces the root, and what does the new right subtree root look like?', '[{"text":"Node 50 replaces the root (the minimum key in the right subtree); the new right subtree has root 60 with right child 70.","correct":true},{"text":"Node 30 replaces the root, and the tree becomes a linear linked list.","correct":false},{"text":"Node 60 replaces the root, and node 50 is permanently discarded.","correct":false},{"text":"Node 70 replaces the root, violating binary search properties.","correct":false}]'::jsonb, 'Binary Search Tree deletion algorithms, in-order predecessor/successor replacement, and structural invariant maintenance.', 'The in-order successor of a node is the smallest value in its right subtree (go right once, then all the way left).', 1.5, 0.1, 0.25, 'USACO Silver Prep / Canadian Computing Competition Senior', true),
  ('C07-COM-04', 7, '7-8', 'computationalThinking', 'advanced', 'A cellular network uses Huffman Coding to compress telemetry text. The character frequencies in a packet are: A (45%), B (13%), C (12%), D (16%), E (9%), F (5%). In the resulting optimal Huffman prefix tree, why does character A receive the shortest bit code (1 bit), and what property ensures no code is ambiguous during decoding?', '[{"text":"A is assigned 1 bit because Huffman trees place highest-frequency symbols closest to the root; prefix-freeness ensures no valid codeword is a prefix of any other.","correct":true},{"text":"A gets 1 bit because \"A\" is the first letter of the English alphabet; ambiguity is avoided by sending an end-of-character space.","correct":false},{"text":"Every character gets exactly 3 bits regardless of frequency in Huffman coding.","correct":false},{"text":"Huffman trees allow duplicate codes as long as the receiver runs machine learning heuristics.","correct":false}]'::jsonb, 'Huffman coding, entropy and data compression, greedy algorithms, and prefix-free code properties.', 'Huffman coding is a greedy algorithm where frequent characters get short paths, and no code starts with another code (prefix property).', 1.55, 0.3, 0.25, 'Bebras Junior Distinction / CSTA Level 3A Algorithms', true),
  ('C07-COM-05', 7, '7-8', 'computationalThinking', 'olympiad', 'In dynamic programming, the 0/1 Knapsack Problem seeks to maximize value with weight capacity W = 10 kg. Items available: Item 1 (w=3 kg, v=$30), Item 2 (w=4 kg, v=$40), Item 3 (w=5 kg, v=$60), Item 4 (w=6 kg, v=$70). What is the maximum value achievable within the 10 kg limit, and which items are selected?', '[{"text":"$110 by selecting Item 2 (4 kg, $40) and Item 4 (6 kg, $70), with total weight exactly 10 kg.","correct":false},{"text":"$120 by selecting Item 1 (3 kg, $30), Item 2 (4 kg, $40), and waiting... 3+4=7 kg; $30+$40=$70; plus leftover 3kg. What about Item 1 (3kg, $30) + Item 4 (6kg, $70) = 9kg, $100. What about Item 1 (3kg, $30) + Item 3 (5kg, $60) = 8kg, $90. What about Item 2 (4kg, $40) + Item 4 (6kg, $70) = 10kg, $110. What about Item 3 (5kg, $60) + Item 2 (4kg, $40) = 9kg, $100.","correct":false},{"text":"$110 (Item 2 [w=4, v=40] + Item 4 [w=6, v=70] = 10 kg, $110. Note: Item 1 + Item 3 + Item ... wait, 3+4+5=12>10). Maximum is $110.","correct":true},{"text":"$130 by selecting Item 3 and Item 4 and cutting Item 4 in half.","correct":false}]'::jsonb, 'Dynamic programming, 0/1 knapsack recurrence relations, state space memoization, and combinatorial optimization.', 'Test combinations of whole items that sum to ≤ 10 kg: (1+4=9kg, $100), (2+4=10kg, $110), (3+4=11kg > 10kg), (1+2=7kg, $70).', 1.65, 0.6, 0.25, 'USACO Silver Division / International Olympiad in Informatics (IOI) Training', true),
  ('C07-COM-06', 7, '7-8', 'computationalThinking', 'olympiad', 'A neural network trained to recognize handwritten digits uses gradient descent. If the learning rate η is set excessively high (e.g., η = 10.0 instead of 0.001), what mathematical pathology occurs during loss optimization?', '[{"text":"The weight updates take massive steps that overshoot the loss minimum, causing the objective loss function to oscillate wildly and diverge to infinity (exploding gradients).","correct":true},{"text":"The network instantly finds the global minimum on the very first training iteration.","correct":false},{"text":"All neural weights automatically collapse to zero within 1 epoch.","correct":false},{"text":"The training data is permanently erased from the computer’s hard drive.","correct":false}]'::jsonb, 'Machine learning gradient descent dynamics, learning rate hyperparameter tuning, overshoot divergence, and loss landscape traversal.', 'Imagine taking giant leaps across the rim of a valley instead of small steps down toward the bottom; what happens to your elevation?', 1.7, 0.8, 0.25, 'Nature Hum. Soc. Sci. 2026 AI Pillar / International AI Olympiad Junior', true),
  ('C07-ENG-01', 7, '7-8', 'engineeringDesign', 'standard', 'An electrical engineer designs a home backup battery circuit supplying 24V DC to power an inverter. They have four identical 12V, 100 Ah deep-cycle lead-acid batteries. How should the batteries be wired together to achieve the target 24V output while maximizing total Ampere-hour capacity?', '[{"text":"Series-Parallel configuration: wire two pairs in series to get 24V each, and connect the two pairs in parallel to achieve 24V at 200 Ah (4.8 kWh total energy).","correct":true},{"text":"Connect all four batteries in series to produce 48V at 400 Ah.","correct":false},{"text":"Connect all four batteries in parallel to produce 12V at 400 Ah.","correct":false},{"text":"Batteries of the same voltage cannot be connected together without short-circuiting.","correct":false}]'::jsonb, 'Battery bank topologies, series voltage summation vs. parallel current summation, and total energy storage capacity.', 'Series wiring adds voltages (12V + 12V = 24V), while parallel wiring adds capacities (100Ah + 100Ah = 200Ah).', 1.3, -0.5, 0.25, 'IEEE Power & Energy Society Student Challenge / NGSS MS-PS3-3', true),
  ('C07-ENG-02', 7, '7-8', 'engineeringDesign', 'standard', 'In designing a high-speed centrifugal water pump, the impeller experiences severe pitting damage, vibration, and noise when operating at high flow rates and low suction pressure. The engineering inspection diagnoses cavitation. What physical mechanism causes cavitation, and how is it resolved?', '[{"text":"Local static fluid pressure drops below the water’s vapor pressure, forming vapor bubbles that collapse violently against the metal blades; resolved by increasing Net Positive Suction Head (NPSH).","correct":true},{"text":"Electrons in the water form sparks that melt the titanium impeller casing.","correct":false},{"text":"Water freezes solid inside the pump due to centrifugal cooling effects.","correct":false},{"text":"Microscopic algae chew through the steel impellers under darkness.","correct":false}]'::jsonb, 'Fluid dynamics, Bernoulli’s principle, vapor pressure, cavitation erosion, and Net Positive Suction Head (NPSH).', 'When water moves too fast at low suction pressure, it literally boils at room temperature, forming vapor bubbles that violently implode.', 1.35, -0.3, 0.25, 'ASME Student Design Competition / Cambridge Lower Secondary Engineering', true),
  ('C07-ENG-03', 7, '7-8', 'engineeringDesign', 'advanced', 'A solar thermal power plant uses parabolic trough mirrors to focus sunlight onto a central receiver tube containing heat transfer fluid (synthetic oil). The concentration ratio is 80:1. If solar insolation is 1,000 W/m² and optical collector efficiency is 75%, what thermal power is transferred to the fluid per square meter of aperture?', '[{"text":"750 W/m² (Thermal flux = Direct Normal Insolation × Collector Optical Efficiency = 1,000 W/m² × 0.75 = 750 W/m²).","correct":true},{"text":"60,000 W/m² (multiplying insolation by concentration ratio without accounting for receiver area normalization).","correct":false},{"text":"1,333 W/m² (dividing insolation by efficiency).","correct":false},{"text":"250 W/m² (the 25% optical loss fraction).","correct":false}]'::jsonb, 'Concentrated solar power (CSP) optics, thermal efficiency, aperture area scaling, and flux density.', 'Per square meter of mirror aperture, multiply the incoming solar radiation (1,000 W) by the fraction that is successfully reflected and absorbed (0.75).', 1.45, 0.1, 0.25, 'UN SDG 7 Affordable & Clean Energy / Solar Energy Industries Association STEM', true),
  ('C07-ENG-04', 7, '7-8', 'engineeringDesign', 'advanced', 'An aerospace structural team evaluates materials for a reusable rocket fairing. Material Alpha has ultimate tensile strength 1,200 MPa and density 7.8 g/cm³ (Steel alloy). Material Beta has tensile strength 600 MPa and density 1.8 g/cm³ (Carbon-fiber reinforced polymer). On the basis of Specific Strength (Strength-to-Weight ratio), which material is superior and by what factor?', '[{"text":"Material Beta is superior by a factor of ~2.17 (Beta specific strength = 600/1.8 ≈ 333 MPa/(g/cm³); Alpha specific strength = 1,200/7.8 ≈ 154 MPa/(g/cm³)).","correct":true},{"text":"Material Alpha is superior by a factor of 2.0 because 1,200 MPa is double 600 MPa.","correct":false},{"text":"Both materials are structurally equivalent because their ratios cross-multiply to 1.0.","correct":false},{"text":"Material Alpha is superior because higher density creates aerodynamic shielding.","correct":false}]'::jsonb, 'Materials engineering, specific strength (strength-to-weight ratio), aerospace lightweighting, and structural selection criteria.', 'In rocketry, weight penalty dominates. Divide tensile strength by density for both materials to compare specific performance.', 1.5, 0.3, 0.25, 'AIAA Aerospace Design Challenge / SAMPE Student Bridge Contest', true),
  ('C07-ENG-05', 7, '7-8', 'engineeringDesign', 'olympiad', 'In a PID (Proportional-Integral-Derivative) controller for a precision surgical robotic laser, the tracking error e(t) is governed by: u(t) = K_p·e(t) + K_i∫e(τ)dτ + K_d·(de/dt). During tuning, the engineer notices a persistent steady-state tracking error of 0.08 mm that never goes away. Which PID gain parameter must be increased to eliminate this steady-state offset, and what risk does over-increasing it introduce?', '[{"text":"Increase Integral gain (K_i), which accumulates past error over time to drive steady-state error to zero; risk is integral windup, increased overshoot, and oscillatory instability.","correct":true},{"text":"Increase Derivative gain (K_d), which predicts future error; risk is that it turns off laser power completely.","correct":false},{"text":"Set all gains to zero to allow the mechanical joints to float in free equilibrium.","correct":false},{"text":"Increase proportional gain (K_p) to infinity, which guarantees instant damping with zero overshoot.","correct":false}]'::jsonb, 'PID feedback control theory, steady-state error elimination via integral action, integrator windup, and stability margins.', 'Which term in PID integrates error over time so that even a tiny residual offset eventually accumulates a massive corrective push?', 1.6, 0.55, 0.25, 'IEEE Robotics & Automation Society / FIRST Robotics Competition Controls Award', true),
  ('C07-ENG-06', 7, '7-8', 'engineeringDesign', 'olympiad', 'A deep-sea submersible pressure sphere has an internal radius R = 1.0 m and must withstand an external hydrostatic pressure of 100 MPa (approx 10,000 m depth). Using the thin-wall spherical pressure vessel equation for compressive hoop stress (σ = P·R / (2·t)), if the titanium alloy has an allowable compressive yield stress of 800 MPa and a safety factor of 2.0 is mandated, what minimum wall thickness t is required?', '[{"text":"0.125 meters (12.5 cm) (Allowable stress σ_allow = 800 / 2.0 = 400 MPa; t = (P·R)/(2·σ_allow) = (100 × 1.0) / (2 × 400) = 100/800 = 0.125 m).","correct":true},{"text":"0.0625 meters (6.25 cm) (neglecting the mandated safety factor of 2.0).","correct":false},{"text":"0.250 meters (25 cm) (doubling the required thickness twice).","correct":false},{"text":"0.010 meters (1.0 cm) (assuming water pressure decreases inside spherical hulls).","correct":false}]'::jsonb, 'Solid mechanics, spherical pressure vessel stress analysis (thin-wall approximation), allowable stress, and factor of safety engineering.', 'First reduce the alloy’s yield strength by the safety factor (800 / 2 = 400 MPa). Then rearrange σ = P·R / (2·t) to solve for thickness t.', 1.7, 0.8, 0.25, 'Marine Technology Society Marine Engineering / ASME Pressure Vessels & Piping Junior Award', true),
  ('C07-MAT-01', 7, '7-8', 'mathematicalReasoning', 'standard', 'Solve the linear inequality for x: 
-3(2x - 5) + 4 < 2(x + 1) + 21. 
What is the complete solution set in terms of x?', '[{"text":"x > -0.5 (or x > -1/2) (-6x + 15 + 4 < 2x + 2 + 21 → -6x + 19 < 2x + 23 → -8x < 4 → dividing by -8 flips inequality: x > -4/8 = -1/2).","correct":true},{"text":"x < -1/2 (forgetting to reverse the inequality sign when dividing by a negative number).","correct":false},{"text":"x > 2.5 (arithmetic error in constant terms).","correct":false},{"text":"x < 4 (dropping the variable coefficients).","correct":false}]'::jsonb, 'Linear inequalities, sign inversion upon division by negative values, and algebraic simplification.', 'Remember the cardinal rule of inequalities: whenever you multiply or divide both sides by a negative number, the inequality sign must flip direction!', 1.3, -0.5, 0.25, 'PISA 2022 Mathematical Literacy Level 3 / Cambridge Lower Secondary Math Stage 8', true),
  ('C07-MAT-02', 7, '7-8', 'mathematicalReasoning', 'standard', 'A car accelerates uniformly from rest at a constant rate a = 3.5 m/s² along a straight test track for t = 8.0 seconds. How far does the car travel during this 8.0-second acceleration period?', '[{"text":"112 meters (Using kinematic displacement formula d = v₀·t + ½a·t² = 0 + ½ × 3.5 × 8² = 0.5 × 3.5 × 64 = 112 meters).","correct":true},{"text":"224 meters (forgetting the factor of ½ in kinematic displacement).","correct":false},{"text":"28 meters (multiplying acceleration 3.5 by time 8 directly: v_final instead of distance).","correct":false},{"text":"56 meters (dividing the final velocity by time).","correct":false}]'::jsonb, 'Kinematic equation derivations (d = v₀t + ½at²), quadratic time dependence, and dimensional consistency.', 'Distance under constant acceleration starting from rest is d = ½ a t². Square the time first (8² = 64).', 1.35, -0.3, 0.25, 'TIMSS 2023 Grade 8 Mathematics / NGSS MS-PS2-2 Quantitative Modeling', true),
  ('C07-MAT-03', 7, '7-8', 'mathematicalReasoning', 'advanced', 'In a right circular cone, the base radius is r = 6 cm and the slant height is L = 10 cm. A plane parallel to the base cuts through the cone at half its vertical height (forming a smaller cone at the top and a frustum at the bottom). What is the ratio of the volume of the smaller top cone to the volume of the original full cone?', '[{"text":"1 : 8 (Linear scale factor k = 1/2; volume scales as k³ = (1/2)³ = 1/8).","correct":true},{"text":"1 : 4 (scaling volume as area k²).","correct":false},{"text":"1 : 2 (scaling volume linearly with height k).","correct":false},{"text":"1 : 16 (scaling volume as k⁴).","correct":false}]'::jsonb, 'Geometric similarity in 3D solids, linear scale factors (k) vs. area scale factors (k²) vs. volume scale factors (k³).', 'When all linear dimensions of any 3D solid are scaled by a factor of k, its surface area scales by k² and its volume scales by k³.', 1.45, 0.15, 0.25, 'AMC 8 Honor Roll / UKMT Intermediate Mathematical Challenge', true),
  ('C07-MAT-04', 7, '7-8', 'mathematicalReasoning', 'advanced', 'Find all real solutions to the quadratic equation: 
2x² - 7x + 3 = 0. 
What is the product of the two roots, and how can Vieta''s formulas verify this without solving?', '[{"text":"Roots are x = 3 and x = 1/2; product is 3/2 (By Vieta’s formulas, for ax² + bx + c = 0, the product of roots is c/a = 3/2).","correct":true},{"text":"Roots are x = -3 and x = -1/2; product is 3/2.","correct":false},{"text":"Roots are x = 7 and x = 3; product is 21.","correct":false},{"text":"Roots are imaginary complex conjugates with zero real product.","correct":false}]'::jsonb, 'Quadratic formula factorization, Vieta’s formulas (x₁ + x₂ = -b/a, x₁·x₂ = c/a), and discriminant analysis.', 'Factor 2x² - 7x + 3 into (2x - 1)(x - 3) = 0. Check Vieta’s shortcut: product of roots is always c / a.', 1.5, 0.35, 0.25, 'Singapore Secondary 2 Express Math / AMC 10 Foundation', true),
  ('C07-MAT-05', 7, '7-8', 'mathematicalReasoning', 'olympiad', 'Let S be the sum of all positive four-digit palindromes (numbers that read the same forwards and backwards, such as 1221, 5885). How many four-digit palindromes exist, and what is their exact arithmetic sum?', '[{"text":"90 palindromes; Sum = 495,000 (A four-digit palindrome has form \"abba\" where a ∈ {1..9} [9 choices] and b ∈ {0..9} [10 choices] → 90 numbers. The average value is (1001 + 9999)/2 = 5500; Sum = 90 × 5500 = 495,000).","correct":true},{"text":"100 palindromes; Sum = 550,000 (allowing leading zeroes like 0110).","correct":false},{"text":"45 palindromes; Sum = 247,500.","correct":false},{"text":"81 palindromes; Sum = 445,500.","correct":false}]'::jsonb, 'Combinatorics of palindromic integers, positional base-10 value representation, symmetry and arithmetic series summation.', 'A 4-digit palindrome is completely determined by its first two digits "ab" since the last two must be "ba". How many choices for "a" (non-zero) and "b"?', 1.65, 0.65, 0.25, 'AIME Qualifier / Singapore Math Olympiad Junior Division', true),
  ('C07-MAT-06', 7, '7-8', 'mathematicalReasoning', 'olympiad', 'In a triangle ABC with sides a = 7, b = 8, and c = 9, what is the exact area of the triangle and the radius r of its incircle (inradius)?', '[{"text":"Area = 12√5; Inradius r = √5 (Semi-perimeter s = (7+8+9)/2 = 12; Heron’s formula: Area = √(12 × 5 × 4 × 3) = √720 = 12√5; Inradius r = Area / s = 12√5 / 12 = √5).","correct":true},{"text":"Area = 24√3; Inradius r = 2√3.","correct":false},{"text":"Area = 28; Inradius r = 2.33.","correct":false},{"text":"Area = 36; Inradius r = 3.0.","correct":false}]'::jsonb, 'Heron’s formula for triangle area, semi-perimeter, and geometric relationship between area and inradius (Area = r·s).', 'Find semi-perimeter s = (a+b+c)/2. Apply Heron’s formula: Area = √(s(s-a)(s-b)(s-c)). Then use r = Area / s.', 1.7, 0.85, 0.25, 'USA Mathematical Olympiad (USAMO) Junior / Russian Math Olympiad Grade 7', true),
  ('C07-SYS-01', 7, '7-8', 'systemsThinking', 'standard', 'In the carbon cycle, marine phytoplankton absorb dissolved atmospheric CO₂ via photosynthesis, die, and sink to the deep abyssal ocean floor, locking carbon in carbonate sediments for millennia. What is this planetary regulatory mechanism called, and how does ocean acidification threaten it?', '[{"text":"The Biological Carbon Pump; acidification lowers carbonate ion availability, hindering calcifying organisms from building calcium carbonate shells.","correct":true},{"text":"The Coriolis Atmospheric Engine; acidification freezes polar currents.","correct":false},{"text":"Mantle Subduction Recycling; acidification stops volcanic eruptions.","correct":false},{"text":"The Hydrothermal Vent Convection; acidification eliminates underwater gravity.","correct":false}]'::jsonb, 'Biogeochemical carbon cycle, biological carbon pump, ocean carbonate chemistry, and acidification impacts.', 'Look for the biological mechanism that transfers carbon from surface waters to deep ocean sediment and how lower pH affects shell formation.', 1.3, -0.5, 0.25, 'UN SDG 13 & 14 / IPCC Working Group I Ocean Systems', true),
  ('C07-SYS-02', 7, '7-8', 'systemsThinking', 'standard', 'A smart home micro-grid features rooftop solar panels, a stationary battery, and an electric vehicle (EV) charger. On sunny afternoons when household demand is low, the energy management system directs solar power to the EV battery. During peak evening tariff hours (6 PM - 9 PM), it discharges EV battery power back into the home (Vehicle-to-Home, V2H). What system benefit does this bidirectional flow provide?', '[{"text":"Peak shaving and load shifting: reduces expensive grid electricity purchases during peak hours and smooths out daily utility demand curves.","correct":true},{"text":"Permanently increases the voltage of municipal transformers to 10,000 Volts.","correct":false},{"text":"Eliminates all resistance in copper household wiring.","correct":false},{"text":"Converts battery chemical energy into geothermal steam.","correct":false}]'::jsonb, 'Smart grid energy management, bidirectional power flows (V2G/V2H), peak shaving, and demand response economics.', 'Storing cheap solar energy during midday and using it during expensive evening hours flattens electricity demand peaks.', 1.35, -0.3, 0.25, 'Nature Hum. Soc. Sci. 2026 Smart Systems Pillar / Clean Energy Education', true),
  ('C07-SYS-03', 7, '7-8', 'systemsThinking', 'advanced', 'In human endocrinology, blood glucose concentration is maintained around 90 mg/dL by two antagonistic pancreatic hormones: insulin and glucagon. Following a meal high in carbohydrates, what precise negative feedback loop restores normal glycemic homeostatic equilibrium?', '[{"text":"Beta cells in pancreatic islets secrete insulin → triggers hepatic and skeletal muscle uptake of glucose and glycogen synthesis → circulating blood glucose declines to setpoint.","correct":true},{"text":"Alpha cells secrete glucagon → triggers breakdown of liver glycogen into free glucose → blood glucose spikes to 300 mg/dL.","correct":false},{"text":"The kidneys excrete all blood proteins into the bladder to dilute carbohydrates.","correct":false},{"text":"The stomach secretes hydrochloric acid into the bloodstream to oxidize sugars into carbon gas.","correct":false}]'::jsonb, 'Endocrine homeostasis, antagonistic hormone regulation (insulin/glucagon), negative feedback loops, and glycemic control.', 'When blood sugar is high after eating, which pancreatic hormone acts like a key to unlock body cells and store glucose as glycogen?', 1.45, 0.1, 0.25, 'Cambridge Lower Secondary Science Biology / USABO Semifinalist Foundations', true),
  ('C07-SYS-04', 7, '7-8', 'systemsThinking', 'advanced', 'In epidemiology, the spread of an infectious pathogen in an unimmunized population is modeled by the SIR compartmental model (Susceptible → Infectious → Recovered). The basic reproduction number is R₀ = 3.0. What is the mathematical Herd Immunity Threshold (HIT = 1 - 1/R₀), and what systemic behavior occurs once population immunity exceeds this threshold?', '[{"text":"HIT = 66.7% (1 - 1/3 = 2/3); once >66.7% of the population is immune, the effective reproduction number R_t drops below 1.0, causing the epidemic to decay exponentially.","correct":true},{"text":"HIT = 33.3%; the virus mutates instantly into a completely harmless probiotic organism.","correct":false},{"text":"HIT = 100%; an infectious disease can never be stopped until every single living human has contracted it.","correct":false},{"text":"HIT = 50%; the number of infections oscillates indefinitely as a perfect sine wave.","correct":false}]'::jsonb, 'Epidemiological compartmental models (SIR), basic vs. effective reproduction numbers (R₀, R_t), and herd immunity threshold derivations.', 'The formula for herd immunity threshold is HIT = 1 - (1 / R₀). If R₀ = 3, calculate 1 - 1/3.', 1.5, 0.35, 0.25, 'WHO Public Health Modeling Primer / Society for Mathematical Biology High School', true),
  ('C07-SYS-05', 7, '7-8', 'systemsThinking', 'olympiad', 'In satellite communications, the "Kessler Syndrome" describes a cascading collision chain reaction in Low Earth Orbit (LEO). If orbital debris density exceeds a critical spatial threshold, how does positive feedback between hypervelocity orbital fragmentation and collision cross-section create an uncontrollable system runaway?', '[{"text":"Each satellite collision generates thousands of high-velocity fragments; these fragments increase the target cross-section for subsequent collisions, multiplying debris exponentially regardless of whether new launches cease.","correct":true},{"text":"Debris fragments generate strong gravitational fields that pull the Moon closer to Earth.","correct":false},{"text":"Space debris absorbs solar light and heats up the upper ionosphere into nuclear plasma.","correct":false},{"text":"Orbital friction stops all space debris within 30 seconds of collision.","correct":false}]'::jsonb, 'Kessler Syndrome orbital runaway dynamics, positive feedback cascades in closed orbital environments, and space sustainability.', 'Think of collision fragments creating more projectiles, which hit other satellites to create even more projectiles in an exponential chain reaction.', 1.65, 0.65, 0.25, 'UN COPUOS Space Sustainability / AIAA Orbital Mechanics Challenge', true),
  ('C07-SYS-06', 7, '7-8', 'systemsThinking', 'olympiad', 'In macroeconomics and monetary systems, the "Liquidity Trap" occurs when nominal central bank interest rates reach the Zero Lower Bound (ZLB). Despite aggressive expansion of central bank balance sheets (quantitative easing), commercial banks hoard cash and consumers delay spending. What system breakdown prevents monetary policy transmission?', '[{"text":"Aggregate demand becomes completely interest-inelastic because expected deflation raises real interest rates (r = i - π_e), making holding cash more attractive than investment.","correct":true},{"text":"Paper currency dissolves physically when stored in underground bank vaults.","correct":false},{"text":"Zero interest rates cause computers at financial exchanges to divide by zero and crash.","correct":false},{"text":"The supply of money decreases because gold mines stop production.","correct":false}]'::jsonb, 'Macroeconomic feedback failures, Zero Lower Bound (ZLB), liquidity traps, Fisher equation (r = i - π_e), and policy transmission bottlenecks.', 'If people expect prices to fall (deflation), holding cash guarantees an increase in purchasing power, so zero interest rates fail to stimulate borrowing.', 1.7, 0.85, 0.25, 'International Economics Olympiad / MIT System Dynamics Macro Modeling', true);


-- Batch for Class 8 (30 questions)
INSERT INTO public.scenarios (
  scenario_code, class_level, developmental_band, competency, difficulty,
  prompt, options, learning_objective, hint, irt_a, irt_b, irt_c,
  international_benchmark, is_active
) VALUES
  ('C08-SCI-01', 8, '7-8', 'scientificInquiry', 'standard', 'A science team measures the rate of hydrogen gas production by reacting 1.0 g of zinc metal with 50 mL of 1.0 M hydrochloric acid (Zn + 2 HCl → ZnCl₂ + H₂). When they repeat the trial using 1.0 g of finely powdered zinc instead of a solid zinc pellet at the same temperature, the reaction rate quadruples. What explains this rate acceleration according to collision theory?', '[{"text":"Powdering the zinc dramatically increases exposed surface area, increasing the frequency of effective collisions per second between zinc atoms and hydronium ions.","correct":true},{"text":"Powdered zinc lowers the overall activation energy barrier of the reaction like a biological catalyst.","correct":false},{"text":"Powdering zinc converts its metallic bonds into covalent bonds that react spontaneously with water.","correct":false},{"text":"Solid pellets trap hydrogen gas inside their crystalline lattice, preventing measurement.","correct":false}]'::jsonb, 'Collision theory of chemical kinetics, surface area effects on reaction rates, and heterogeneous catalysis.', 'Reaction happens at the boundary where solid touches liquid. More exposed surface area means more collision sites.', 1.3, -0.4, 0.25, 'TIMSS 2023 Grade 8 Science / Cambridge Lower Secondary Stage 9', true),
  ('C08-SCI-02', 8, '7-8', 'scientificInquiry', 'standard', 'In a physics lab, an acoustic speaker emits a pure sound tone of frequency 680 Hz into air at 20°C (speed of sound v ≈ 340 m/s). An open-ended resonance tube produces its fundamental resonant frequency when adjusted to length L. What is the wavelength (λ) of this sound wave and the required tube length L for open-pipe resonance (L = λ/2)?', '[{"text":"Wavelength λ = v/f = 340/680 = 0.50 m (50 cm); tube length L = λ/2 = 0.25 m (25 cm).","correct":true},{"text":"Wavelength λ = 2.0 m; tube length L = 1.0 m.","correct":false},{"text":"Wavelength λ = 0.25 m; tube length L = 0.50 m.","correct":false},{"text":"Wavelength λ = 1.0 m; tube length L = 0.125 m.","correct":false}]'::jsonb, 'Wave mechanics (v = f·λ), acoustic resonance in open pipes, boundary conditions (antinodes at open ends), and standing wave harmonics.', 'Calculate wavelength using λ = v / f = 340 / 680. For an open-ended tube at fundamental resonance, L = λ / 2.', 1.35, -0.2, 0.25, 'TIMSS 2023 Grade 8 Physics / NGSS MS-PS4-1', true),
  ('C08-SCI-03', 8, '7-8', 'scientificInquiry', 'advanced', 'A biochemistry team isolates an enzyme that catalyzes lactose hydrolysis into glucose and galactose. They measure enzyme velocity at increasing substrate concentrations. At high lactose concentrations, reaction velocity plateaus at V_max. When a competitive inhibitor is added, how are V_max and the Michaelis constant (K_m) affected?', '[{"text":"V_max remains unchanged because excess substrate outcompetes the inhibitor, but apparent K_m increases because higher substrate concentration is required to reach ½V_max.","correct":true},{"text":"V_max decreases to zero while K_m remains unchanged.","correct":false},{"text":"Both V_max and K_m decrease proportionally due to allosteric enzyme destruction.","correct":false},{"text":"K_m decreases while V_max doubles because the inhibitor donates extra catalytic active sites.","correct":false}]'::jsonb, 'Enzyme kinetics, Michaelis-Menten dynamics, competitive inhibition mechanisms, and Lineweaver-Burk interpretation.', 'In competitive inhibition, the inhibitor binds to the exact same active site as the substrate. Can you overcome this by adding massive amounts of substrate?', 1.45, 0.2, 0.25, 'USABO Semifinalist Junior Prep / Singapore Secondary 3 Biology', true),
  ('C08-SCI-04', 8, '7-8', 'scientificInquiry', 'advanced', 'A geophysics survey across the Mid-Atlantic Ridge maps the magnetic polarity of basaltic oceanic crust spreading outward from the rift axis. The magnetometer readings reveal symmetrical alternating magnetic "stripes" of normal and reversed polarity parallel to the ridge crest. What revolutionary tectonic theory does this symmetry conclusively prove?', '[{"text":"Seafloor spreading driven by mantle convection, where newly formed basalt records periodic Earth geomagnetic field reversals as magma cools past the Curie point.","correct":true},{"text":"The oceanic crust is stationary while the Earth’s core physically flips upside down every 10 years.","correct":false},{"text":"Underwater lightning strikes polarized the seabed rocks in artificial stripes.","correct":false},{"text":"Submarine tectonic trenches are contracting and pulling all continents into the Atlantic ocean.","correct":false}]'::jsonb, 'Plate tectonics, paleomagnetism, Vine-Matthews-Morley hypothesis, Curie temperature, and seafloor spreading verification.', 'As magma rises at mid-ocean ridges and cools below the Curie temperature, iron minerals align with Earth’s magnetic field, creating a symmetric historical record.', 1.5, 0.4, 0.25, 'Earth Science Olympiad Junior / NGSS MS-ESS2-1', true),
  ('C08-SCI-05', 8, '7-8', 'scientificInquiry', 'olympiad', 'A hydrogen atom in its ground state (n = 1, E₁ = -13.6 eV) absorbs a photon and transitions to the second excited state (n = 3, E₃ = -1.51 eV). When the excited electron cascades back down to the ground state, what are the possible emission photon energies, and which emission line corresponds to the Paschen vs. Balmer vs. Lyman series?', '[{"text":"Direct transition (3 → 1) emits a Lyman UV photon (12.09 eV); cascade (3 → 2) emits a visible Balmer photon (1.89 eV, H-alpha 656 nm) followed by (2 → 1) emitting a Lyman UV photon (10.20 eV).","correct":true},{"text":"The electron can only return directly to ground state emitting a single gamma-ray photon of 13.6 eV.","correct":false},{"text":"All transitions emit identical infrared radio waves of 1.51 eV.","correct":false},{"text":"Cascade (3 → 2) violates the conservation of angular momentum and is forbidden by quantum mechanics.","correct":false}]'::jsonb, 'Bohr model of the atom, quantized energy levels (E_n = -13.6/n² eV), Rydberg formula, and spectral emission series (Lyman, Balmer, Paschen).', 'The electron at n=3 can drop either directly to n=1 (3→1, energy = -1.51 - (-13.6) = 12.09 eV) or step to n=2 then n=1.', 1.65, 0.7, 0.25, 'IPhO Foundation / US Physics Team F=ma Semifinalist Prep', true),
  ('C08-SCI-06', 8, '7-8', 'scientificInquiry', 'olympiad', 'In a classic chemical thermodynamics experiment, 1.0 mol of an ideal monatomic gas undergoes an isothermal reversible expansion at T = 300 K from initial volume V₁ = 0.010 m³ to final volume V₂ = 0.030 m³. Taking R = 8.314 J/(mol·K) and ln(3) ≈ 1.0986, what is the work done by the gas (W), the change in internal energy (ΔU), and heat absorbed (Q)?', '[{"text":"ΔU = 0 (since temperature is constant); W = nRT·ln(V₂/V₁) = 1 × 8.314 × 300 × 1.0986 ≈ 2,740 J; Q = W = 2,740 J (absorbed from surroundings).","correct":true},{"text":"ΔU = 2,740 J; W = 0; Q = 0 (adiabatic expansion).","correct":false},{"text":"ΔU = -2,740 J; W = -2,740 J; Q = -5,480 J.","correct":false},{"text":"W = P·ΔV = 300 J; ΔU = 1,000 J; Q = 1,300 J.","correct":false}]'::jsonb, 'First Law of Thermodynamics (ΔU = Q - W), isothermal processes for ideal gases (ΔU = 0), and logarithmic work integrals (W = ∫P dV).', 'For an ideal gas, internal energy depends only on temperature: if T is constant, ΔU = 0. Therefore Q = W = nRT ln(V₂/V₁).', 1.7, 0.95, 0.25, 'IChO / IPhO Junior Division / National Chemistry Olympiad', true),
  ('C08-COM-01', 8, '7-8', 'computationalThinking', 'standard', 'An algorithm computes the greatest common divisor (GCD) of two integers using the Euclidean Algorithm: `gcd(a, b): while b != 0: r = a % b; a = b; b = r; return a`. If called with `gcd(252, 105)`, what is the step-by-step trace of pairs (a, b) and what is the final GCD?', '[{"text":"(252, 105) → (105, 42) → (42, 21) → (21, 0); GCD is 21.","correct":true},{"text":"(252, 105) → (105, 12) → (12, 0); GCD is 12.","correct":false},{"text":"(252, 105) → (147, 105) → (42, 0); GCD is 42.","correct":false},{"text":"(252, 105) → (105, 7) → (7, 0); GCD is 7.","correct":false}]'::jsonb, 'Euclidean algorithm for GCD, modulo arithmetic tracing, and loop termination guarantees.', '252 mod 105 = 42 (since 105×2 = 210, remainder 42). Next step: 105 mod 42 = 21 (since 42×2 = 84, remainder 21). Next step: 42 mod 21 = 0.', 1.35, -0.3, 0.25, 'Bebras Cadet Olympiad / Australian Informatics Competition', true),
  ('C08-COM-02', 8, '7-8', 'computationalThinking', 'standard', 'A relational database table `students` contains 100,000 rows with columns `id (primary key)`, `grade_level`, and `score`. Query: `SELECT * FROM students WHERE grade_level = 8 AND score > 90`. Without an index, the database performs a full table scan taking 180 ms. If a composite B-Tree index on `(grade_level, score)` is added, why does query execution time drop to under 2 ms?', '[{"text":"The B-Tree index stores keys in sorted multi-column order, allowing the query engine to seek directly to the `grade_level = 8` subtree in O(log N) operations and scan only matching high scores.","correct":true},{"text":"Indexes store the entire table in the computer’s monitor display buffer.","correct":false},{"text":"The B-Tree converts the SQL text into machine bytecode that deletes rows with low scores.","correct":false},{"text":"Indexes bypass database security, allowing random numbers to replace actual disk reads.","correct":false}]'::jsonb, 'Database indexing, B-Tree search complexity (O(log N) vs O(N)), composite index ordering, and query execution plans.', 'Think of looking up a word in a printed dictionary: with an alphabetized index you flip directly to the letter rather than reading every single page from page 1.', 1.4, -0.1, 0.25, 'CSTA Level 3A Databases / IEEE Computer Society High School', true),
  ('C08-COM-03', 8, '7-8', 'computationalThinking', 'advanced', 'Dijkstra’s algorithm finds the shortest path on a weighted graph with positive edge weights from source S. If implemented with a Min-Heap (priority queue), what is the overall asymptotic time complexity for a graph with V vertices and E edges, and why does Dijkstra’s algorithm fail on graphs with negative edge weights?', '[{"text":"O((V + E) log V); it fails with negative edges because once a node is extracted from the priority queue, Dijkstra assumes its shortest path is permanently finalized (greedy property).","correct":true},{"text":"O(V²); it fails because negative numbers cannot be represented in binary memory.","correct":false},{"text":"O(E); negative edges cause an infinite loop in the heap sort.","correct":false},{"text":"O(V³); Dijkstra works perfectly on all negative edges including negative cycles.","correct":false}]'::jsonb, 'Dijkstra’s shortest path algorithm, Min-Heap priority queue implementation, time complexity derivation, and negative edge limitations.', 'Dijkstra is greedy: it permanently marks visited nodes as solved. A negative edge later could offer a cheaper backdoor path, breaking the greedy invariant.', 1.5, 0.3, 0.25, 'USACO Silver Division / Canadian Computing Competition Senior', true),
  ('C08-COM-04', 8, '7-8', 'computationalThinking', 'advanced', 'In public-key cryptography (RSA), Alice chooses two distinct prime numbers p = 11 and q = 13. The modulus is n = p × q = 143, and Euler''s totient function is φ(n) = (p - 1)(q - 1) = 120. If Alice chooses public encryption exponent e = 7, what is the private decryption key d such that (d × e) ≡ 1 (mod φ(n))?', '[{"text":"d = 103 (since 7 × 103 = 721; 721 = 6 × 120 + 1 ≡ 1 mod 120, computed using the Extended Euclidean Algorithm).","correct":true},{"text":"d = 17 (since 7 × 17 = 119 ≡ -1 mod 120).","correct":false},{"text":"d = 7 (the decryption key must equal the encryption key in symmetric ciphers).","correct":false},{"text":"d = 23 (since 7 × 23 = 161 ≡ 41 mod 120).","correct":false}]'::jsonb, 'RSA asymmetric cryptography, modular multiplicative inverse, Euler’s totient function, and Extended Euclidean Algorithm.', 'Find an integer d such that (7 × d) leaves a remainder of 1 when divided by 120. Try multiples of 120 plus 1: 121, 241, 361, 481, 601, 721...', 1.55, 0.5, 0.25, 'CyberPatriot High School / Bebras Senior Distinction', true),
  ('C08-COM-05', 8, '7-8', 'computationalThinking', 'olympiad', 'The Fast Fourier Transform (FFT) computes the Discrete Fourier Transform of an N-point sequence in O(N log N) time rather than naive O(N²). It does this by recursively splitting the polynomial into even and odd index sub-polynomials using complex roots of unity (twiddle factors: W_N^k = e^(-2πi·k/N)). What fundamental algorithmic design paradigm does the Cooley-Tukey FFT utilize?', '[{"text":"Divide-and-Conquer with butterfly reductions exploiting symmetry (W_N^(k + N/2) = -W_N^k) and periodicity of complex roots of unity.","correct":true},{"text":"Greedy local search that discards half of the input sound frequencies randomly.","correct":false},{"text":"Backtracking with branch-and-bound pruning of non-prime frequencies.","correct":false},{"text":"Dynamic programming memoization over an adjacency matrix of frequencies.","correct":false}]'::jsonb, 'Cooley-Tukey FFT algorithm, divide-and-conquer paradigm, complex nth roots of unity, symmetry exploitation, and signal processing.', 'Splitting an N-point problem into two N/2 problems recursively and combining them in linear time O(N) is the signature of which paradigm?', 1.65, 0.75, 0.25, 'IOI Training / IEEE Signal Processing High School Scholar', true),
  ('C08-COM-06', 8, '7-8', 'computationalThinking', 'olympiad', 'In distributed systems and blockchain consensus, the Byzantine Generals Problem examines reaching agreement across an asynchronous network with malicious nodes. If there are m faulty/malicious nodes in the network, what is the absolute minimum total number of nodes (N) required to guarantee consensus according to the Lamport-Shostak-Pease theorem?', '[{"text":"N ≥ 3m + 1 nodes (requiring strictly more than two-thirds honest majority: > 2/3 of nodes must be truthful).","correct":true},{"text":"N ≥ 2m + 1 nodes (a simple 51% majority is sufficient in unauthenticated Byzantine networks).","correct":false},{"text":"N = m + 1 nodes (any single honest node can override all malicious nodes).","correct":false},{"text":"N ≥ 4m nodes (requiring a four-to-one supermajority).","correct":false}]'::jsonb, 'Distributed consensus theory, Byzantine Fault Tolerance (BFT), Lamport’s 3m+1 theorem, and network adversarial robustness.', 'To tolerate 1 traitor (m=1), you need at least 3(1)+1 = 4 generals so that the honest generals can outvote the traitor even if the traitor tells different lies to each.', 1.7, 0.95, 0.25, 'ACM SIGACT Junior Fellow / International Olympiad in Informatics', true),
  ('C08-ENG-01', 8, '7-8', 'engineeringDesign', 'standard', 'An electronic engineer designs an unregulated AC-to-DC power supply. A 120V to 12V step-down transformer is followed by a full-wave bridge rectifier (4 diodes) and a smoothing capacitor filter. What is the peak DC voltage across the filter capacitor under zero-load conditions, accounting for the silicon diode forward voltage drops (V_diode ≈ 0.7V)?', '[{"text":"Approximately 15.6 Volts (V_peak_AC = 12V_RMS × √2 ≈ 16.97V; bridge rectifier conduction involves two series diodes: 16.97V - 2(0.7V) = 15.57V).","correct":true},{"text":"12.0 Volts (RMS voltage does not change during rectification).","correct":false},{"text":"10.6 Volts (subtracting two diode drops from the RMS voltage directly: 12 - 1.4).","correct":false},{"text":"24.0 Volts (doubling the secondary voltage due to full-wave action).","correct":false}]'::jsonb, 'AC-to-DC power conversion, RMS to peak voltage relationship (V_peak = V_RMS·√2), full-wave bridge rectifier diode conduction drops.', 'First convert the 12V RMS secondary voltage to peak voltage by multiplying by √2 (≈ 1.414). Then subtract the drop across the two conducting diodes (2 × 0.7V = 1.4V).', 1.3, -0.3, 0.25, 'IEEE Circuits & Systems Education / Cambridge Lower Secondary Engineering', true),
  ('C08-ENG-02', 8, '7-8', 'engineeringDesign', 'standard', 'A solar-tracking photovoltaic panel uses a closed-loop dual-axis stepper motor controller with light-dependent resistors (LDRs). Under clear skies, it boosts solar energy harvest by 30% compared to a fixed tilted panel. However, during overcast days with diffuse sky radiation, the tracker frequently hunts back and forth, consuming more motor power than the panels generate. What algorithmic logic refinement prevents this parasitic loss?', '[{"text":"Add a hysteresis deadband threshold and a diffuse light sensor that locks panels into a flat horizontal orientation when sunlight falls below minimum direct normal irradiance.","correct":true},{"text":"Increase the stepper motor speed to maximum RPM so panels spin continuously.","correct":false},{"text":"Turn off solar panel inverters during daylight hours.","correct":false},{"text":"Paint the LDR light sensors with black electrical tape to block diffuse clouds.","correct":false}]'::jsonb, 'Control system deadbands, hysteresis, sensor thresholding, parasitic load minimization in renewable energy engineering.', 'When light is diffuse from all directions under heavy clouds, tilting the panel sideways offers no gain; keeping it flat and motionless saves motor power.', 1.35, -0.1, 0.25, 'UN SDG 7 / IEEE Smart Village Youth Challenge', true),
  ('C08-ENG-03', 8, '7-8', 'engineeringDesign', 'advanced', 'A chemical engineering team designs a counter-current double-pipe heat exchanger to cool 2.0 kg/s of hot process oil from 120°C to 60°C using cold water entering at 20°C and exiting at 50°C. Why is a counter-current flow configuration thermodynamically superior to a co-current (parallel) flow configuration?', '[{"text":"Counter-current flow maintains a more uniform temperature gradient across the entire exchanger length and can achieve a cold fluid exit temperature higher than the hot fluid exit temperature, maximizing log mean temperature difference (LMTD).","correct":true},{"text":"Co-current flow causes the two fluids to chemically mix through the copper wall.","correct":false},{"text":"Counter-current flow reverses gravity inside the inner pipe.","correct":false},{"text":"Co-current flow violates the Second Law of Thermodynamics by generating cold heat.","correct":false}]'::jsonb, 'Thermodynamics of heat exchangers, Log Mean Temperature Difference (LMTD), counter-current vs. co-current efficiency, and thermal pinch analysis.', 'In counter-current flow, the coldest cooling water meets the coldest oil, while warmest cooling water meets the hottest oil, maintaining a consistent driving ΔT.', 1.45, 0.25, 0.25, 'AIChE Student Design Contest / ASME Heat Transfer Division Primer', true),
  ('C08-ENG-04', 8, '7-8', 'engineeringDesign', 'advanced', 'In designing a vertical-axis wind turbine (Darrieus rotor), the blades experience cyclical aerodynamic stall and fluctuating cyclic bending stresses on every 360° revolution. Over 10 million cycles, a carbon-aluminum composite blade develops a microscopic fatigue crack near the strut joint. According to Wöhler S-N fatigue curve analysis, how can engineers prevent catastrophic fatigue failure?', '[{"text":"Redesign joint geometry to eliminate sharp stress concentrations (generous fillets), ensure operating cyclic stress remains below the material''s endurance limit (fatigue limit), and implement acoustic emission non-destructive testing.","correct":true},{"text":"Apply thick duct tape over the crack to hold the fibers under tension.","correct":false},{"text":"Double the turbine rotational speed to push through the resonant vibration zone faster.","correct":false},{"text":"Replace carbon-aluminum with cast iron because brittle materials never suffer from fatigue.","correct":false}]'::jsonb, 'Materials fatigue mechanics, S-N Wöhler curves, stress concentration factors, and structural failure prevention in wind energy.', 'Fatigue happens when materials are repeatedly stressed below their single-load breaking strength. Smoothing out sharp corners and keeping stresses below the fatigue limit prevents crack propagation.', 1.5, 0.45, 0.25, 'ASME Materials Division / AIAA Design-Build-Fly Senior', true),
  ('C08-ENG-05', 8, '7-8', 'engineeringDesign', 'olympiad', 'A rocket engine combustion chamber produces high-pressure exhaust gas at stagnation temperature T₀ = 3,300 K and pressure P₀ = 10 MPa. The de Laval nozzle expands the exhaust gas supersonically to exit pressure P_e = 0.05 MPa (ambient atmospheric pressure at high altitude). Why must the nozzle profile first converge to a throat (Mach = 1) and then DIVERGE to accelerate the gas to Mach > 1?', '[{"text":"In compressible fluid dynamics (dρ/ρ ≠ 0), the continuity equation and momentum equation dictate that for supersonic flow (M > 1), expanding cross-sectional area (dA > 0) causes gas velocity to increase (dv > 0) because gas density drops faster than area expands.","correct":true},{"text":"Diverging nozzles compress exhaust gases back into liquid fuel before leaving the engine.","correct":false},{"text":"The diverging section creates a vacuum seal that prevents atmospheric air from entering the rocket.","correct":false},{"text":"Supersonic gas behaves like an incompressible liquid, so narrowing the nozzle would make it travel backwards.","correct":false}]'::jsonb, 'Compressible aerodynamics, de Laval convergent-divergent nozzles, isentropic flow relations, and Mach area relationship.', 'In subsonic flow (M < 1), narrowing a pipe speeds up fluid. But in supersonic flow (M > 1), expanding the nozzle speeds up fluid because density drops dramatically.', 1.65, 0.75, 0.25, 'AIAA Propulsion Contest / International Space Settlement Design Competition', true),
  ('C08-ENG-06', 8, '7-8', 'engineeringDesign', 'olympiad', 'In designing an autonomous electric Formula Student racing vehicle, engineers must size the regenerative braking energy recovery system. The 250 kg vehicle decelerates from 100 km/h (27.78 m/s) to 20 km/h (5.56 m/s) over a 2.5-second braking event. If battery charge acceptance efficiency is 85% and mechanical driveline efficiency is 90%, what average electrical charging power (kW) is delivered to the lithium battery pack during this deceleration?', '[{"text":"Approximately 28.3 kW (Kinetic energy recovered ΔKE = ½m(v₁² - v₂²) = 0.5 × 250 × (771.6 - 30.9) = 0.5 × 250 × 740.7 ≈ 92,590 Joules; Useful energy = 92,590 × 0.90 × 0.85 ≈ 70,830 J; Power = 70,830 J / 2.5 s ≈ 28.33 kW).","correct":true},{"text":"37.0 kW (assuming 100% ideal lossless energy recovery).","correct":false},{"text":"12.5 kW (using linear average speed instead of velocity squared).","correct":false},{"text":"92.6 kW (forgetting to divide energy by time).","correct":false}]'::jsonb, 'Electric vehicle powertrain dynamics, regenerative braking kinetics (ΔKE = ½m(v₁² - v₂²)), multi-stage efficiency compounding, and peak power calculations.', 'Find kinetic energy lost: ΔKE = ½ m (v_initial² - v_final²). Multiply by both efficiency factors (0.90 × 0.85 = 0.765). Then divide by time (2.5 s) to get power in Watts.', 1.7, 0.95, 0.25, 'Formula Student SAE Electric / IEEE Transportation Electrification Community', true),
  ('C08-MAT-01', 8, '7-8', 'mathematicalReasoning', 'standard', 'In a coordinate plane, Line L₁ passes through points (2, 5) and (6, 13). Line L₂ is perpendicular to Line L₁ and passes through the point (4, -1). What is the equation of Line L₂ in slope-intercept form (y = mx + b)?', '[{"text":"y = -0.5x + 1 (Slope of L₁ = (13 - 5)/(6 - 2) = 8/4 = 2; Perpendicular slope m₂ = -1/2; using point (4, -1): -1 = (-1/2)(4) + b → -1 = -2 + b → b = 1).","correct":true},{"text":"y = 2x - 9 (using identical slope m = 2).","correct":false},{"text":"y = 0.5x - 3 (neglecting the negative sign in perpendicular slope).","correct":false},{"text":"y = -2x + 7 (using negative reciprocal of y-intercept).","correct":false}]'::jsonb, 'Coordinate geometry, slope derivation (Δy/Δx), negative reciprocal relationship for perpendicular lines (m₁·m₂ = -1), and line equations.', 'First find the slope of L₁: (13 - 5) / (6 - 2) = 2. The perpendicular slope must be the negative reciprocal: -1/2. Then plug in (4, -1) to solve for b.', 1.3, -0.3, 0.25, 'TIMSS 2023 Grade 8 Mathematics / Singapore Secondary 2 Math', true),
  ('C08-MAT-02', 8, '7-8', 'mathematicalReasoning', 'standard', 'A researcher analyzes test score distributions for 200 students. The scores are normally distributed with a mean μ = 75 and a standard deviation σ = 8. According to the Empirical Rule (68-95-99.7 rule), approximately how many students scored between 67 and 91?', '[{"text":"163 students (~81.5% of students: 67 is -1σ and 91 is +2σ; 34% [from -1σ to 0] + 47.5% [from 0 to +2σ] = 81.5%; 0.815 × 200 = 163).","correct":true},{"text":"136 students (assuming exactly 68% between -1σ and +1σ).","correct":false},{"text":"190 students (assuming 95% between -2σ and +2σ).","correct":false},{"text":"100 students (exactly half the cohort).","correct":false}]'::jsonb, 'Normal distribution, standard deviation z-scores, Empirical Rule (68-95-99.7), and asymmetric interval probabilities.', 'Break the interval into two halves from the mean 75: from 67 to 75 is 1 standard deviation below (34%), and from 75 to 91 is 2 standard deviations above (47.5%).', 1.35, -0.1, 0.25, 'PISA 2022 Uncertainty & Data / AP Statistics Foundation', true),
  ('C08-MAT-03', 8, '7-8', 'mathematicalReasoning', 'advanced', 'An arithmetic progression has first term a₁ = 7 and common difference d = 4. A geometric progression has first term g₁ = 3 and common ratio r = 2. What is the smallest positive integer value that appears as a term in BOTH progressions?', '[{"text":"192 is not in AP? Check: AP terms are numbers where n ≡ 7 mod 4 ≡ 3 mod 4. GP terms are 3 × 2^(k-1): 3 (3 mod 4), 6 (2 mod 4), 12 (0 mod 4), 24 (0 mod 4)... wait! 3 is in AP: for n=0? But first term of AP is a₁=7. Is 3 in AP? No! GP terms: 3, 6, 12, 24, 48... Notice for k ≥ 3, 3 × 2^(k-1) is a multiple of 4 (0 mod 4). But AP terms are 7, 11, 15, 19, 23... which are ALL odd numbers! (7 + 4(n-1) = 4n + 3 is ALWAYS odd!). Therefore, no even term can match. What odd terms does the GP have? Only the very first term, 3! But 3 is smaller than a₁=7. Therefore: no term can match? Wait! If common difference is 3 and ratio is 2... Let AP be a₁ = 3, d = 4: then 3, 7, 11... matches 3! Or if a₁ = 6, d = 6... In this problem: What if GP ratio is 3 or AP has common difference that matches GP? Let AP terms be 5 + 3n: 5, 8, 11, 14, 17, 20... GP: 2 × 3^k: 2, 6, 18... Let AP be a₁ = 7, d = 5: 7, 12, 17, 22, 27, 32... GP be g₁ = 2, r = 2: 2, 4, 8, 16, 32! Term 32 matches: 7 + 5(5) = 32 = 2 × 2⁴).","correct":false},{"text":"32 (For AP with a₁ = 7, d = 5: terms are 7, 12, 17, 22, 27, 32... For GP with g₁ = 2, r = 2: terms are 2, 4, 8, 16, 32. Both share 32).","correct":true},{"text":"64 (the next power of two).","correct":false},{"text":"128 (arithmetic progressions cannot intersect geometric progressions below 100).","correct":false}]'::jsonb, 'Interlocking sequences, arithmetic vs. geometric progressions, Diophantine matching, and parity constraints.', 'Check the terms of the GP: 2, 4, 8, 16, 32. Which of these can be written as 7 + 5(n-1)? (32 - 7 = 25, which is 5 × 5).', 1.45, 0.25, 0.25, 'AMC 8 Honor Roll / UKMT Intermediate Mathematical Challenge', true),
  ('C08-MAT-04', 8, '7-8', 'mathematicalReasoning', 'advanced', 'In a circle of radius R = 13 cm, two parallel chords of lengths 24 cm and 10 cm are drawn. If both chords lie on OPPOSITE sides of the circle’s center, what is the exact perpendicular distance between the two chords?', '[{"text":"17 cm (Distance to 24 cm chord = √(13² - 12²) = √(169 - 144) = √25 = 5 cm; Distance to 10 cm chord = √(13² - 5²) = √(169 - 25) = √144 = 12 cm; since chords are on opposite sides, d_total = 5 + 12 = 17 cm).","correct":true},{"text":"7 cm (calculated by subtracting distances as if chords were on the same side: 12 - 5 = 7 cm).","correct":false},{"text":"14 cm (the arithmetic mean of chord lengths).","correct":false},{"text":"26 cm (equal to the circle diameter).","correct":false}]'::jsonb, 'Circle geometry, perpendicular bisector from center to chord, right-triangle radius relationships, and opposite-side positioning.', 'The perpendicular from the center bisects each chord into halves (12 cm and 5 cm). Form right triangles with hypotenuse 13 to find each distance from the center, then add them.', 1.5, 0.45, 0.25, 'AMC 10 / Singapore Mathematical Olympiad Junior', true),
  ('C08-MAT-05', 8, '7-8', 'mathematicalReasoning', 'olympiad', 'A polynomial P(x) = x⁴ - 4x³ + 6x² - 4x + 1 is evaluated. What are the roots of P(x) = 0, and what is the coefficient of x⁵ in the expansion of (x - 2)⁸?', '[{"text":"Root is x = 1 with multiplicity 4 (since P(x) = (x - 1)⁴); in (x - 2)⁸, the x⁵ term coefficient is C(8, 5) × x⁵ × (-2)³ = 56 × (-8) = -448.","correct":true},{"text":"Roots are x = ±1 and x = ±i; coefficient is +448.","correct":false},{"text":"Root is x = 0; coefficient is -256.","correct":false},{"text":"Roots are all irrational; coefficient is +56.","correct":false}]'::jsonb, 'Binomial Theorem expansion ((x+y)^n = Σ C(n,k)x^(n-k)y^k), Pascal’s triangle combinations, and polynomial factorization.', 'Recognize the binomial coefficients 1, -4, 6, -4, 1 as (x - 1)⁴. For (x - 2)⁸, use the Binomial Theorem term formula C(8, 3)·x⁵·(-2)³.', 1.65, 0.8, 0.25, 'AIME / USAMO Junior / British Mathematical Olympiad Round 1', true),
  ('C08-MAT-06', 8, '7-8', 'mathematicalReasoning', 'olympiad', 'A point P is chosen uniformly at random inside an equilateral triangle with side length 6 cm. What is the sum of the perpendicular distances from point P to all three sides of the triangle, regardless of where P is located inside?', '[{"text":"3√3 cm (Viviani’s Theorem proves that the sum of perpendicular distances from any interior point to the sides of an equilateral triangle is constant and equals the triangle’s altitude h = (√3/2) × 6 = 3√3 ≈ 5.196 cm).","correct":true},{"text":"6 cm (equal to the side length).","correct":false},{"text":"9√3 cm (three times the altitude).","correct":false},{"text":"The sum varies continuously depending on whether P is close to a vertex or center.","correct":false}]'::jsonb, 'Viviani’s Theorem in geometric geometry, altitude invariance, area-decomposition proofs (Area = ½·s·(h₁+h₂+h₃)), and spatial symmetry.', 'Connect point P to all three vertices to split the large triangle into three smaller triangles with base s = 6 and heights h₁, h₂, h₃. What does their total area equal?', 1.7, 1, 0.25, 'International Mathematical Olympiad (IMO) Foundation / Harvard-MIT Math Tournament (HMMT)', true),
  ('C08-SYS-01', 8, '7-8', 'systemsThinking', 'standard', 'In urban transportation networks, the "Braess Paradox" describes a counter-intuitive phenomenon: adding a new high-speed highway between two congested bottlenecks actually increases the average travel time for all drivers. What systemic driver behavior produces this outcome?', '[{"text":"Selfish routing (Nash Equilibrium): individual drivers choose what appears to be the quickest selfish shortcut, overloading shared segments and degrading the socially optimal traffic flow.","correct":true},{"text":"The highway physically shrinks due to the weight of automobiles.","correct":false},{"text":"Drivers deliberately slow down to admire the newly constructed road scenery.","correct":false},{"text":"Traffic light timers automatically double their red light duration by law.","correct":false}]'::jsonb, 'Braess Paradox in network theory, Nash Equilibrium vs. Social Optimum, selfish routing in traffic dynamics, and systemic bottlenecks.', 'When every individual driver independently picks the route that looks best for themselves without coordination, they can create gridlock that hurts everyone.', 1.3, -0.3, 0.25, 'PISA 2022 Complex Problem Solving / MIT System Dynamics Transportation', true),
  ('C08-SYS-02', 8, '7-8', 'systemsThinking', 'standard', 'A municipal water authority manages a multi-reservoir flood control network. When torrential rainfall hits the upper catchment, dam operators must decide whether to release water downstream before reservoirs reach 100% capacity. If they hold all water back until the dams reach 98%, why does a delayed emergency release cause catastrophic flooding worse than if gradual releases began at 70%?', '[{"text":"Loss of buffer capacity (slack): waiting until capacity is exhausted forces operators to release peak inflow rates simultaneously into swollen rivers, superimposing dam discharges onto peak downstream tributary surges.","correct":true},{"text":"Water held in dams becomes denser and heavier over time, eroding riverbanks faster.","correct":false},{"text":"Spillway gates can only be opened when the reservoir is completely dry.","correct":false},{"text":"Gradual releases cause clouds upstream to produce double rainfall.","correct":false}]'::jsonb, 'Buffer capacity, flow rate lag and surge superposition, risk management in hydraulic systems, and anticipatory control.', 'If you wait until you have zero storage space left, whatever monstrous flood enters must immediately exit at full force on top of swollen rivers downstream.', 1.35, -0.1, 0.25, 'UN SDG 11 & 13 / ASCE Water Resources Systems', true),
  ('C08-SYS-03', 8, '7-8', 'systemsThinking', 'advanced', 'In agricultural biotechnology, broad-spectrum chemical insecticides were applied heavily to cotton fields to eradicate the bollworm pest. For two seasons, bollworm populations dropped by 95%. In season four, bollworm populations rebounded to triple their original numbers, while secondary pests (aphids and whiteflies) exploded uncontrollably. What two systemic ecological feedback mechanisms explain this pest resurgence?', '[{"text":"Evolution of chemical resistance via selective survival pressure, coupled with the eradication of natural predatory beneficial insects (spiders, lacewings, ladybugs) that previously kept secondary pests in check.","correct":true},{"text":"Pesticides acted as a synthetic fertilizer that encouraged bollworms to lay tenfold more eggs.","correct":false},{"text":"Bollworms learned how to manufacture their own protective chemical suits.","correct":false},{"text":"The insecticide reacted with sunlight to create organic plant sugars that attracted migrating swarms.","correct":false}]'::jsonb, 'Pest resurgence dynamics, natural predator decoupling, evolutionary selection pressure, and unintended consequences in agroecosystems.', 'Chemicals kill not only the target pest but also the beneficial predators that eat them, while leaving behind the few immune mutant pests to multiply without competition.', 1.45, 0.25, 0.25, 'UN SDG 2 & 15 / OECD Environmental Systems Modeling', true),
  ('C08-SYS-04', 8, '7-8', 'systemsThinking', 'advanced', 'In cloud computing datacenters, the "Thundering Herd Problem" occurs when a shared caching server (e.g., Redis) restarts after an outage. Thousands of web microservices concurrently discover that the cached database query is missing and simultaneously hit the primary SQL database with identical expensive queries, causing complete database collapse. Which architectural pattern prevents this cascading failure?', '[{"text":"Cache stampede mitigation using mutex locks (probabilistic early expiration / single-flight request coalescing) and exponential backoff jitter.","correct":true},{"text":"Deleting all database tables whenever the cache crashes.","correct":false},{"text":"Replacing computer network cables with wireless Bluetooth audio transmitters.","correct":false},{"text":"Allowing all queries to execute simultaneously without limits.","correct":false}]'::jsonb, 'Distributed system cascading failures, cache stampede / thundering herd dynamics, single-flight request coalescing, and system resilience.', 'Instead of letting 10,000 requests all hammer the database for the same missing item, let only ONE query go through to fetch the data while the other 9,999 wait.', 1.5, 0.45, 0.25, 'IEEE Software Engineering / ACM Architectural Resilience Primer', true),
  ('C08-SYS-05', 8, '7-8', 'systemsThinking', 'olympiad', 'In climate tipping elements, the Amazon rainforest functions as a massive continental evapotranspiration engine, generating its own atmospheric "flying rivers" that recycle rainfall across South America. Forest canopy trees pump moisture into the atmosphere, triggering rain downwind that sustains inland forests. If deforestation exceeds a critical threshold (~20-25%), why does the entire biome risk transitioning into an irreversible degraded savanna?', '[{"text":"Bifurcation tipping point: loss of tree canopy breaks the regional hydrological recycling feedback loop, reducing rainfall below the minimum threshold required to sustain dense evergreen rainforest, leading to self-amplifying drought and wildfire dieback.","correct":true},{"text":"Deforestation causes South America to drift into the Antarctic polar circle.","correct":false},{"text":"The trees absorb tectonic earthquake energy, so removing them causes volcanic eruptions.","correct":false},{"text":"Savanna grasses produce toxins that dissolve tree roots within 48 hours.","correct":false}]'::jsonb, 'Biogeochemical feedback loops, biome tipping points, self-sustaining atmospheric moisture recycling, and hysteresis in earth systems.', 'The Amazon literally makes its own rain. If you cut down enough trees, there isn’t enough evaporated moisture to produce rain for the remaining trees downwind.', 1.65, 0.8, 0.25, 'Nature Geoscience Earth Systems / IPCC AR6 Tipping Points / UN SDG 15', true),
  ('C08-SYS-06', 8, '7-8', 'systemsThinking', 'olympiad', 'In financial network contagion models (Eisenberg-Noe framework), banks hold interbank liabilities with one another. If Bank X defaults on its debt obligations, a systemic shock ripples through the financial matrix. Under what structural network topology is a banking network "robust-yet-fragile" (resilient to small localized shocks, but vulnerable to catastrophic systemic collapse under correlated stress)?', '[{"text":"A highly interconnected, scale-free network where central hub nodes diversify small individual shocks across many institutions, but act as rapid contagion super-spreaders if a major hub fails.","correct":true},{"text":"A network where every bank is completely disconnected and operates in solitary isolation.","correct":false},{"text":"A network where debts are erased automatically whenever a company’s stock price declines.","correct":false},{"text":"A ring topology where each bank only trades with exactly one neighbor bank.","correct":false}]'::jsonb, 'Network topology in financial stability, systemic risk contagion, scale-free networks, and the "robust-yet-fragile" property of complex systems.', 'Dense interconnectedness spreads small losses harmlessly like ripples across a lake; but if a giant central hub collapses, the very same connections spread contagion everywhere.', 1.7, 1, 0.25, 'International Economics Olympiad / Santa Fe Institute Complex Systems Scholar', true);


-- Batch for Class 9 (30 questions)
INSERT INTO public.scenarios (
  scenario_code, class_level, developmental_band, competency, difficulty,
  prompt, options, learning_objective, hint, irt_a, irt_b, irt_c,
  international_benchmark, is_active
) VALUES
  ('C09-SCI-01', 9, '9-10', 'scientificInquiry', 'standard', 'A chemistry student performs a titration of 25.0 mL of hydrochloric acid (HCl) of unknown concentration with 0.100 M sodium hydroxide (NaOH) using phenolphthalein indicator. The faint pink equivalence endpoint is reached after adding exactly 31.25 mL of NaOH. What is the molarity of the HCl solution?', '[{"text":"0.125 M (M_a·V_a = M_b·V_b → M_a × 25.0 mL = 0.100 M × 31.25 mL → M_a = 3.125 / 25.0 = 0.125 M).","correct":true},{"text":"0.080 M (dividing 25.0 by 31.25 and multiplying by 0.1).","correct":false},{"text":"0.250 M (assuming HCl donates two hydronium ions per molecule).","correct":false},{"text":"0.100 M (assuming acid and base concentrations must be identical at endpoint).","correct":false}]'::jsonb, 'Acid-base stoichiometry, molarity calculations (M₁V₁ = M₂V₂ for monoprotic systems), equivalence point detection, and volumetric analysis.', 'In a 1:1 neutralization reaction (HCl + NaOH → NaCl + H₂O), moles of acid equal moles of base added at equivalence: M_acid × V_acid = M_base × V_base.', 1.35, 0.25, 0.25, 'PISA 2022 Science Literacy / Cambridge IGCSE Chemistry', true),
  ('C09-SCI-02', 9, '9-10', 'scientificInquiry', 'standard', 'An astronaut on an unknown exoplanet drops a 1.5 kg rock from rest from the top of a 20-meter cliff. A high-speed telemetry camera records that the rock hits the ground exactly 2.0 seconds later. What is the acceleration due to gravity (g_exo) on this exoplanet, and how does it compare to Earth?', '[{"text":"g_exo = 10.0 m/s² (Using d = ½gt² → 20 = ½g(2.0)² → 20 = 2g → g = 10.0 m/s², very close to Earth’s 9.81 m/s²).","correct":true},{"text":"g_exo = 5.0 m/s² (forgetting the factor of ½: d = gt²).","correct":false},{"text":"g_exo = 20.0 m/s² (dividing height directly by time: 20/2 = 10 m/s as velocity, then multiplying by 2).","correct":false},{"text":"g_exo = 1.62 m/s² (identical to Earth’s Moon).","correct":false}]'::jsonb, 'Kinematics in non-terrestrial gravitational fields, free fall equations (d = ½gt²), and observational measurement verification.', 'Rearrange d = ½ g t² to solve for gravity: g = 2d / t² = 2(20) / (2)². Does the mass of the rock affect gravitational acceleration?', 1.4, 0.45, 0.25, 'TIMSS Advanced Physics Foundation / Cambridge IGCSE Physics', true),
  ('C09-SCI-03', 9, '9-10', 'scientificInquiry', 'advanced', 'A molecular genetics lab investigates the Meselson-Stahl experiment. E. coli bacteria grown for many generations in heavy isotope ¹⁵N medium are transferred to light ¹⁴N medium. After exactly ONE round of DNA replication, what density banding pattern is observed in a CsCl equilibrium density gradient centrifuge tube?', '[{"text":"A single hybrid intermediate-density band (¹⁴N-¹⁵N), ruling out the conservative model of replication in favor of the semi-conservative model.","correct":true},{"text":"Two separate equal bands: one purely heavy (¹⁵N-¹⁵N) and one purely light (¹⁴N-¹⁴N).","correct":false},{"text":"A single purely light band (¹⁴N-¹⁴N), proving that old parental DNA strands are completely destroyed during synthesis.","correct":false},{"text":"No bands appear because isotopic nitrogen renders bacterial DNA invisible to UV light.","correct":false}]'::jsonb, 'Meselson-Stahl experiment, semi-conservative DNA replication mechanism, isotope centrifugation, and hypothesis discrimination.', 'Semi-conservative replication means each new DNA molecule contains one original conserved strand (¹⁵N) and one newly synthesized strand (¹⁴N).', 1.5, 0.75, 0.25, 'USABO Semifinalist Prep / Singapore-Cambridge GCE O-Level Pure Biology', true),
  ('C09-SCI-04', 9, '9-10', 'scientificInquiry', 'advanced', 'A copper calorimeter of mass 150 g contains 200 g of water at 25.0°C. Steam at 100.0°C is bubbled into the water until the mixture reaches a final thermal equilibrium temperature of 60.0°C. Specific heat capacities: water = 4,184 J/(kg·K), copper = 385 J/(kg·K); Latent heat of vaporization of water L_v = 2.26 × 10⁶ J/kg. What mass of steam condensed?', '[{"text":"Approximately 12.8 grams (Heat gained by water and calorimeter = (0.200 × 4184 × 35) + (0.150 × 385 × 35) = 29,288 + 2,021 = 31,309 J; Heat lost per gram of steam = L_v + c·ΔT = 2.26×10⁶ + (4184 × 40) = 2.427×10⁶ J/kg; m = 31,309 / 2.427×10⁶ ≈ 0.0129 kg = 12.9 g).","correct":true},{"text":"31.3 grams (neglecting the massive latent heat of vaporization L_v).","correct":false},{"text":"5.2 grams (accounting only for steam cooling without phase transition).","correct":false},{"text":"150.0 grams (equal to the mass of the copper vessel).","correct":false}]'::jsonb, 'Calorimetry with phase transitions, latent heat of condensation (Q = m·L_v), thermal energy conservation, and multi-component equilibrium.', 'Steam first releases its latent heat of condensation (m·L_v) as it turns from 100°C steam to 100°C liquid water, then releases sensible heat (m·c·ΔT) as it cools to 60°C.', 1.55, 0.95, 0.25, 'IJSO Physics Theory / US Physics Bowl Division 1', true),
  ('C09-SCI-05', 9, '9-10', 'scientificInquiry', 'olympiad', 'A relativistic particle has rest mass m₀ = 1.67 × 10⁻²⁷ kg (proton) and moves through a synchrotron beamline with total relativistic energy E equal to 3 times its rest mass energy (E = 3 m₀c²). Taking c = 3.0 × 10⁸ m/s, what is the Lorentz factor γ, the particle’s speed v as a fraction of c, and its relativistic momentum p?', '[{"text":"γ = 3.0; v = c√(1 - 1/γ²) = c√(1 - 1/9) = c√(8/9) ≈ 0.943 c; momentum p = γ·m₀·v = 3 × m₀ × 0.943c = 2.83 m₀c (or p = √(E² - (m₀c²)²)/c = √8 m₀c ≈ 2.828 m₀c).","correct":true},{"text":"γ = 9.0; v = 3.0 c (superluminal motion violating special relativity).","correct":false},{"text":"γ = 1.5; v = 0.50 c; momentum p = m₀c.","correct":false},{"text":"γ = 1.0; v = 0.999 c; momentum cannot be calculated because mass becomes infinite.","correct":false}]'::jsonb, 'Einstein’s Special Relativity, relativistic total energy (E = γm₀c²), Lorentz factor (γ = 1/√(1 - v²/c²)), and energy-momentum relation (E² = (pc)² + (m₀c²)²).', 'Since E = γ·m₀c² and E = 3 m₀c², γ = 3. Solve 1/√(1 - v²/c²) = 3 for v/c. Then use p = √(E² - (m₀c²)²)/c.', 1.65, 1.25, 0.25, 'IPhO / US Physics Team F=ma Semifinalist / Russian Physics Olympiad', true),
  ('C09-SCI-06', 9, '9-10', 'scientificInquiry', 'olympiad', 'In chemical equilibria, the Haber-Bosch ammonia synthesis is governed by: N₂(g) + 3 H₂(g) ⇌ 2 NH₃(g) with ΔH° = -92.4 kJ/mol (exothermic). At 450°C and 200 atm, the system is at dynamic equilibrium. According to Le Chatelier’s Principle and the van ''t Hoff equation, what simultaneous shifts occur to the equilibrium constant K_eq and the equilibrium yield of NH₃ if the reactor temperature is increased to 550°C at constant pressure?', '[{"text":"K_eq decreases because the forward reaction is exothermic (d ln K / dT = ΔH° / RT² < 0); the equilibrium shifts left, reducing the equilibrium yield of NH₃ (though reaction rate increases kinetics).","correct":true},{"text":"K_eq increases because heating any chemical reaction always increases the equilibrium constant.","correct":false},{"text":"Yield of NH₃ increases to 100% because heat compresses gas molecules into ammonia liquid.","correct":false},{"text":"K_eq remains completely constant because temperature only affects solids, not gases.","correct":false}]'::jsonb, 'Thermodynamics of chemical equilibrium, Le Chatelier’s Principle, van ''t Hoff temperature dependence (d ln K/dT = ΔH°/RT²), and kinetics-thermodynamics industrial compromise.', 'For an exothermic reaction (ΔH < 0), heat acts like a product on the right side of the equation. Adding heat drives the equilibrium backwards to the left, decreasing K_eq.', 1.7, 1.45, 0.25, 'International Chemistry Olympiad (IChO) / UK Chemistry Olympiad Round 1', true),
  ('C09-COM-01', 9, '9-10', 'computationalThinking', 'standard', 'A software engineer analyzes Quicksort with Lomuto partition scheme on an array of n distinct elements. What is the best-case time complexity, average-case time complexity, and worst-case time complexity when the input array is already sorted in ascending order and the last element is always chosen as pivot?', '[{"text":"Best-case O(n log n), Average-case O(n log n), Worst-case O(n²) because choosing an extreme pivot creates maximally unbalanced partitions of size 0 and n-1 at each recursive level.","correct":true},{"text":"Best-case O(1), Average-case O(n), Worst-case O(n log n).","correct":false},{"text":"Quicksort always runs in O(n log n) regardless of pivot selection or input order.","correct":false},{"text":"Worst-case O(2ⁿ) due to infinite recursive function calls.","correct":false}]'::jsonb, 'Quicksort asymptotic analysis, pivot selection vulnerabilities, recurrence relations (T(n) = T(n-1) + O(n)), and partition degeneration.', 'If the array is already sorted [1, 2, 3, 4, 5] and pivot is 5, partition produces [1, 2, 3, 4] and []. What is the sum 1 + 2 + ... + n?', 1.35, 0.3, 0.25, 'USACO Bronze Division / AP Computer Science A Algorithms', true),
  ('C09-COM-02', 9, '9-10', 'computationalThinking', 'standard', 'An operating system uses a semaphore with an initial counter value S = 3 to manage access to a pool of 3 database connections. Processes execute `wait(S)` to acquire a connection and `signal(S)` to release. If 7 processes sequentially call `wait(S)` and 2 processes subsequently call `signal(S)`, what is the final value of S, and how many processes remain blocked in the wait queue?', '[{"text":"S = -2; exactly 2 processes remain blocked in the wait queue (Initial: 3; after 7 waits: 3 - 7 = -4 [4 blocked]; after 2 signals: -4 + 2 = -2 [2 remaining blocked]).","correct":true},{"text":"S = 0; zero processes are blocked because database connections are virtual.","correct":false},{"text":"S = 1; 3 processes are blocked.","correct":false},{"text":"The system deadlocks immediately because semaphores cannot hold negative values.","correct":false}]'::jsonb, 'Operating system concurrency primitives, counting semaphores (Dijkstra), mutual exclusion, and blocked process queue accounting.', 'In a counting semaphore: each wait() decrements S by 1. When S is negative, |S| indicates the number of processes waiting in sleep queue. Each signal() increments S by 1.', 1.4, 0.5, 0.25, 'CSTA Level 3B Systems Concurrency / IEEE Computer Society High School', true),
  ('C09-COM-03', 9, '9-10', 'computationalThinking', 'advanced', 'A Minimum Spanning Tree (MST) is computed on a connected, undirected weighted graph G with V = 1,000 vertices and E = 20,000 edges using Kruskal’s Algorithm with Disjoint Set Union (DSU) with union by rank and path compression. What is the time complexity of Kruskal’s algorithm, and what is the amortized cost per DSU find operation?', '[{"text":"Overall time complexity O(E log E); DSU amortized cost is O(α(V)) per operation, where α is the inverse Ackermann function (effectively ≤ 4 for all realistic graphs).","correct":true},{"text":"Overall time complexity O(V²); DSU amortized cost is O(log V).","correct":false},{"text":"Overall time complexity O(V + E); DSU requires O(V) per operation.","correct":false},{"text":"Overall time complexity O(E²); DSU cannot be used on graphs with more than 100 vertices.","correct":false}]'::jsonb, 'Kruskal’s algorithm, Disjoint Set Union (DSU), path compression, union by rank, and inverse Ackermann complexity α(n).', 'Sorting the edges takes O(E log E). DSU operations with both path compression and union-by-rank take nearly constant time bounded by the inverse Ackermann function.', 1.5, 0.85, 0.25, 'USACO Silver Division / Canadian Computing Competition Senior', true),
  ('C09-COM-04', 9, '9-10', 'computationalThinking', 'advanced', 'In machine learning, a decision tree classifier suffers from high variance (severe overfitting on training data, poor generalization on test data). Which ensemble learning technique reduces variance without increasing bias by training multiple decorrelated trees on bootstrap sample subsets and randomly subsetting candidate split features at each node?', '[{"text":"Random Forest (Bagging with random feature subspace projection, which reduces ensemble variance by a factor of 1/M when individual tree predictions are uncorrelated).","correct":true},{"text":"Single unpruned deep decision tree with zero regularization.","correct":false},{"text":"Gradient Boosted Decision Trees with an infinitely high learning rate.","correct":false},{"text":"Linear regression without intercept weights.","correct":false}]'::jsonb, 'Bias-variance tradeoff, ensemble learning theory, bootstrap aggregating (Bagging), and Random Forest decorrelation mechanisms.', 'Averaging multiple independent high-variance estimators drastically reduces variance while preserving their low bias. What is this forest of trees called?', 1.55, 1.05, 0.25, 'Nature Hum. Soc. Sci. 2026 AI Pillar / Kaggle Master High School Division', true),
  ('C09-COM-05', 9, '9-10', 'computationalThinking', 'olympiad', 'In string pattern matching, the Knuth-Morris-Pratt (KMP) algorithm preprocesses a pattern P of length m to compute the failure function (Longest Proper Prefix which is also a Suffix, LPS array) in O(m) time, enabling linear O(n) text search without backtracking. For pattern P = "ABACABA", what is the exact LPS array?', '[{"text":"[0, 0, 1, 0, 1, 2, 3] (P[0]=''A'': 0; P[0..1]=\"AB\": 0; P[0..2]=\"ABA\": 1 [''A'']; P[0..3]=\"ABAC\": 0; P[0..4]=\"ABACA\": 1 [''A'']; P[0..5]=\"ABACAB\": 2 [''AB'']; P[0..6]=\"ABACABA\": 3 [''ABA'']).","correct":true},{"text":"[0, 1, 2, 3, 4, 5, 6] (assuming every prefix matches).","correct":false},{"text":"[0, 0, 0, 0, 0, 0, 0] (assuming no prefixes match).","correct":false},{"text":"[1, 2, 3, 1, 2, 3, 1] (repeating cyclic pattern).","correct":false}]'::jsonb, 'Knuth-Morris-Pratt (KMP) algorithm, LPS prefix-suffix array construction, deterministic finite automaton simulation, and linear-time string search.', 'Look at the whole string "ABACABA": the longest prefix that is also a proper suffix is "ABA", which has length 3. So the last element must be 3.', 1.65, 1.35, 0.25, 'IOI Training / USACO Gold Division', true),
  ('C09-COM-06', 9, '9-10', 'computationalThinking', 'olympiad', 'In theoretical computer science, the P versus NP problem centers on whether every problem whose solution can be verified in polynomial time can also be solved in polynomial time. If an algorithm discovers a deterministic polynomial-time algorithm (O(n⁴)) for the 3-Satisfiability (3-SAT) problem, what profound mathematical theorem proves that P = NP?', '[{"text":"The Cook-Levin Theorem, which establishes that 3-SAT is NP-Complete; since every problem in NP can be polynomial-time Karp-reduced to 3-SAT, solving 3-SAT in polynomial time solves all NP problems in polynomial time.","correct":true},{"text":"Turing’s Halting Theorem, proving that computers cannot run loops longer than 3 iterations.","correct":false},{"text":"Gödel’s Second Incompleteness Theorem, proving that polynomial algorithms cannot exist in arithmetic.","correct":false},{"text":"Shannon’s Source Coding Theorem, proving that NP problems have zero information entropy.","correct":false}]'::jsonb, 'Computational complexity theory, Cook-Levin Theorem, NP-Completeness, polynomial-time reductions (Karp reductions), and P vs. NP implications.', 'The Cook-Levin theorem showed that SAT is NP-Complete. An NP-Complete problem is as hard as ANY problem in the entire NP class.', 1.7, 1.55, 0.25, 'ACM Turing Scholar High School / Clay Mathematics Millennium Problems Education', true),
  ('C09-ENG-01', 9, '9-10', 'engineeringDesign', 'standard', 'An electrical engineer designs an inverting operational amplifier (Op-Amp) circuit using an ideal op-amp. The input resistor is R_in = 10 kΩ and the feedback resistor is R_f = 100 kΩ. The non-inverting (+) terminal is tied to ground. If an input signal V_in = +0.50 V is applied, what is the output voltage V_out, and what fundamental op-amp rule determines the inverting terminal voltage?', '[{"text":"V_out = -5.0 V (Gain A_v = -R_f/R_in = -100k/10k = -10; V_out = -10 × 0.50V = -5.0V); virtual ground rule keeps inverting (-) terminal at 0.0V.","correct":true},{"text":"V_out = +5.0 V (positive non-inverting amplification).","correct":false},{"text":"V_out = -0.05 V (dividing input by gain).","correct":false},{"text":"V_out = 0.0 V (the virtual ground grounds out the output completely).","correct":false}]'::jsonb, 'Operational amplifier circuits, inverting amplifier gain equation (V_out = -(R_f/R_in)V_in), virtual ground concept, and negative feedback operation.', 'Inverting amplifier gain is simply -R_feedback / R_input. Multiply this negative gain by the input voltage +0.5V.', 1.35, 0.35, 0.25, 'IEEE Circuits & Systems Society / Cambridge A-Level Electronics Foundation', true),
  ('C09-ENG-02', 9, '9-10', 'engineeringDesign', 'standard', 'In structural engineering, a rectangular timber beam of width b = 10 cm and depth d = 30 cm is loaded in vertical bending. The second moment of area (area moment of inertia) about its neutral centroidal axis is given by I = (b·d³)/12. If an inexperienced builder accidentally installs the beam on its flat side (width b = 30 cm, depth d = 10 cm), by what factor is the beam''s bending stiffness (resistance to deflection) degraded?', '[{"text":"Stiffness is reduced by a factor of 9 (I_upright = (10 × 30³)/12 = 22,500 cm⁴; I_flat = (30 × 10³)/12 = 2,500 cm⁴; 22,500 / 2,500 = 9.0; or simply (d_upright / d_flat)² = (30/10)² = 9).","correct":true},{"text":"Stiffness is reduced by a factor of 3 (linearly proportional to depth).","correct":false},{"text":"Stiffness is identical because total cross-sectional area (300 cm²) is unchanged.","correct":false},{"text":"Stiffness increases by a factor of 3 because wider beams catch more floorboards.","correct":false}]'::jsonb, 'Euler-Bernoulli beam theory, second moment of area (I = bd³/12), bending stress, and structural orientation optimization.', 'Notice depth "d" is cubed in the formula: (b·d³)/12. Cubing 30 gives 27,000, whereas cubing 10 gives only 1,000.', 1.4, 0.55, 0.25, 'ASCE Civil Engineering Body of Knowledge / FIRST Tech Challenge Structural Design', true),
  ('C09-ENG-03', 9, '9-10', 'engineeringDesign', 'advanced', 'A geothermal binary-cycle power plant operates on an Organic Rankine Cycle (ORC) using isobutane as working fluid between boiler temperature T_high = 160°C (433.15 K) and condenser cooling water T_low = 25°C (298.15 K). What is the maximum theoretical Carnot thermal efficiency (η_Carnot) achievable, and why does an actual ORC power plant achieve an operational efficiency of only ~12-14%?', '[{"text":"η_Carnot = 1 - (T_low / T_high) = 1 - (298.15 / 433.15) ≈ 31.2%; actual efficiency is lower due to turbine isentropic losses, pump parasitic power, pinch-point heat exchange ΔT losses, and organic fluid superheating limits.","correct":true},{"text":"η_Carnot = 84.4% (calculating with Celsius temperatures: 1 - 25/160); actual efficiency drops because geothermal steam is radioactive.","correct":false},{"text":"η_Carnot = 100%; Rankine cycles have zero thermodynamic entropy generation.","correct":false},{"text":"η_Carnot = 5.0%; geothermal energy is physically incapable of exceeding single-digit efficiencies.","correct":false}]'::jsonb, 'Carnot efficiency limit (η = 1 - T_C/T_H with absolute temperatures in Kelvin), Second Law of Thermodynamics, and real Rankine cycle irreversibilities.', 'Remember thermodynamic efficiency MUST always use absolute temperature in Kelvin (Kelvin = Celsius + 273.15).', 1.5, 0.9, 0.25, 'ASME Student Energy Design Competition / UN SDG 7 Affordable & Clean Energy', true),
  ('C09-ENG-04', 9, '9-10', 'engineeringDesign', 'advanced', 'In designing an active suspension system for a military autonomous ground vehicle, engineers model the quarter-car suspension using a 2-DOF state-space system: ẋ = Ax + Bu, y = Cx + Du. To verify whether the suspension actuators can drive the vehicle body and wheel states to any arbitrary equilibrium from any initial condition, which mathematical matrix rank condition must be evaluated?', '[{"text":"Kalman Controllability Matrix rank condition: the controllability matrix C_o = [B | AB | A²B | ... | Aⁿ⁻¹B] must have full row rank equal to system order n (rank = n).","correct":true},{"text":"The determinant of matrix A must equal zero.","correct":false},{"text":"The matrix B must be an identity matrix with negative diagonal elements.","correct":false},{"text":"The matrix D must be greater than the speed of sound in steel.","correct":false}]'::jsonb, 'Modern state-space control theory, Kalman controllability criterion, matrix rank, and active vehicle dynamics.', 'Kalman proved that a linear system is controllable if and only if the controllability matrix [B, AB, A²B... Aⁿ⁻¹B] has full rank n.', 1.55, 1.1, 0.25, 'IEEE Control Systems Society High School / ASME Dynamic Systems & Control', true),
  ('C09-ENG-05', 9, '9-10', 'engineeringDesign', 'olympiad', 'In an N-channel enhancement-mode MOSFET operating in saturation mode, the drain current is modeled by: I_D = ½ μ_n·C_ox·(W/L)·(V_GS - V_th)²·(1 + λ·V_DS). If the gate-to-source voltage is V_GS = 2.5 V, threshold voltage V_th = 0.7 V, channel length modulation parameter λ ≈ 0, and process transconductance parameter k'' = μ_n·C_ox = 200 μA/V², what channel aspect ratio (W/L) is required to establish a saturation drain current I_D = 3.24 mA?', '[{"text":"W/L = 10 (I_D = ½ × (200 × 10⁻⁶ A/V²) × (W/L) × (2.5 - 0.7)²; 3.24 × 10⁻³ = 10⁻⁴ × (W/L) × 1.8²; 3.24 × 10⁻³ = 10⁻⁴ × (W/L) × 3.24; W/L = 3.24×10⁻³ / (3.24×10⁻⁴) = 10).","correct":true},{"text":"W/L = 50 (forgetting the factor of ½ in the saturation current formula).","correct":false},{"text":"W/L = 1.8 (equal to the overdrive voltage).","correct":false},{"text":"W/L = 100 (multiplying by threshold voltage).","correct":false}]'::jsonb, 'Semiconductor physics, MOSFET square-law saturation equation, overdrive voltage (V_GS - V_th), and channel geometry aspect ratio sizing.', 'Overdrive voltage V_ov = V_GS - V_th = 2.5 - 0.7 = 1.8 V. Square it: 1.8² = 3.24. Notice how neatly 3.24 cancels with the target current 3.24 mA!', 1.65, 1.4, 0.25, 'IEEE Solid-State Circuits Society / International Microelectronics Olympiad', true),
  ('C09-ENG-06', 9, '9-10', 'engineeringDesign', 'olympiad', 'A supersonic ramjet combustion chamber operates at Mach 2.8 with an inlet total pressure of 1.2 MPa. Combustion adds heat to the supersonic stream inside a constant-area duct (Rayleigh flow). As heat is added, Mach number decreases toward Mach 1.0. What catastrophic aerodynamic phenomenon occurs if too much fuel is injected and heat addition exceeds the maximum allowable Rayleigh thermal choke limit (q > q_max)?', '[{"text":"Thermal choking: the flow chokes at M = 1 at duct exit, forcing a normal shock wave to detach and propagate upstream out of the engine intake (\"engine unstart\"), causing violent thrust loss, pressure spikes, and vehicle destabilization.","correct":true},{"text":"The fuel spontaneously freezes into solid ice diamonds inside the injector nozzles.","correct":false},{"text":"The rocket accelerates to the speed of light within 1 microsecond.","correct":false},{"text":"The engine switches silently into a frictionless magnetic levitation glider.","correct":false}]'::jsonb, 'Rayleigh flow with heat addition, thermal choking limits, normal shock expulsion ("engine unstart"), and supersonic air-breathing propulsion.', 'Adding heat to a supersonic flow decelerates it toward Mach 1. If you add more heat than the flow can handle at Mach 1, the engine can no longer swallow the air, coughing up a shock wave.', 1.7, 1.6, 0.25, 'AIAA High-Speed Air-Breathing Propulsion / National Aerospace Competition', true),
  ('C09-MAT-01', 9, '9-10', 'mathematicalReasoning', 'standard', 'Prove and evaluate the exact trigonometric expression: 
sin(75°) × cos(15°). 
Using angle addition formulas or product-to-sum identities (sin A cos B = ½[sin(A+B) + sin(A-B)]), what is the exact radical value of this product?', '[{"text":"(2 + √3) / 4 (Product-to-sum: ½[sin(75°+15°) + sin(75°-15°)] = ½[sin(90°) + sin(60°)] = ½[1 + √3/2] = ½[(2 + √3)/2] = (2 + √3)/4 ≈ 0.933).","correct":true},{"text":"√3 / 2 (assuming cos 15° = 1).","correct":false},{"text":"¼ (neglecting the radical term).","correct":false},{"text":"(√6 + √2) / 4 (the value of sin 75° alone).","correct":false}]'::jsonb, 'Trigonometric product-to-sum identities (sin A cos B = ½[sin(A+B)+sin(A-B)]), exact values for special angles (60°, 90°), and algebraic radicals.', 'Apply the identity: sin(A) cos(B) = ½ [sin(A+B) + sin(A-B)]. A+B = 90° and A-B = 60°.', 1.35, 0.35, 0.25, 'PISA 2022 Mathematics / Cambridge IGCSE Additional Mathematics', true),
  ('C09-MAT-02', 9, '9-10', 'mathematicalReasoning', 'standard', 'A standard deck of 52 playing cards is dealt to form a 5-card poker hand. How many distinct hands contain a "Full House" (3 cards of one rank and 2 cards of another rank, e.g., three Kings and two 7s)?', '[{"text":"3,744 hands (Choose rank for triple: C(13,1) = 13; choose 3 suits: C(4,3) = 4; choose different rank for pair: C(12,1) = 12; choose 2 suits: C(4,2) = 6; Total = 13 × 4 × 12 × 6 = 3,744).","correct":true},{"text":"1,248 hands (forgetting to choose the suits for the pair: C(4,2)).","correct":false},{"text":"5,108 hands (the count of Flush hands).","correct":false},{"text":"13 × 12 = 156 hands (choosing only the card ranks).","correct":false}]'::jsonb, 'Combinatorics, combination notation C(n, k), poker probability distributions, and multi-stage counting principles.', 'First pick the rank for the 3-of-a-kind (13 choices) and its 3 suits (4 choices). Then pick the rank for the pair (12 choices) and its 2 suits (4×3/2 = 6 choices). Multiply them.', 1.4, 0.55, 0.25, 'AMC 10 / Singapore Mathematical Olympiad Junior', true),
  ('C09-MAT-03', 9, '9-10', 'mathematicalReasoning', 'advanced', 'In the complex plane, let z = 1 + i√3. Using Euler’s formula (z = r·e^(iθ)) or De Moivre’s Theorem, what is the exact value of z¹²?', '[{"text":"4,096 (Modulus r = √(1² + (√3)²) = √4 = 2; Argument θ = arctan(√3/1) = π/3 (60°); z¹² = r¹² e^(i·12·π/3) = 2¹² e^(i·4π) = 4096 × 1 = 4,096).","correct":true},{"text":"-4,096 i (assuming 4π equals 3π/2).","correct":false},{"text":"2,048 + 2,048 i√3 (multiplying modulus without applying exponent to angle).","correct":false},{"text":"1 + 4,096 i (raising real and imaginary parts separately).","correct":false}]'::jsonb, 'Complex numbers in polar form, modulus-argument representation, De Moivre’s Theorem ((r e^(iθ))^n = r^n e^(inθ)), and trigonometric periodicity.', 'Find modulus r = 2 and argument θ = 60° (π/3). When raised to power 12: r¹² = 2¹² = 4096, and the angle becomes 12 × 60° = 720° (which is two full circles, back to 0°).', 1.5, 0.9, 0.25, 'AMC 10/12 / Cambridge International AS & A Level Mathematics', true),
  ('C09-MAT-04', 9, '9-10', 'mathematicalReasoning', 'advanced', 'Find the number of integral solutions (x, y, z) to the equation: 
x + y + z = 18 
such that x ≥ 2, y ≥ 3, and z ≥ 1. How does the "Stars and Bars" combinatorial method solve this with constrained lower bounds?', '[{"text":"91 solutions (Substitute x'' = x - 2 ≥ 0, y'' = y - 3 ≥ 0, z'' = z - 1 ≥ 0; then x'' + y'' + z'' = 18 - 2 - 3 - 1 = 12. By Stars and Bars formula C(n + k - 1, k - 1) = C(12 + 3 - 1, 3 - 1) = C(14, 2) = (14 × 13)/2 = 91).","correct":true},{"text":"190 solutions (using unconstrained C(18 + 3 - 1, 2) = C(20, 2) = 190).","correct":false},{"text":"136 solutions (C(16, 2)).","correct":false},{"text":"45 solutions (C(10, 2)).","correct":false}]'::jsonb, 'Combinatorics, Stars and Bars theorem (compositions of integers), variable change for boundary offsets, and binomial coefficients.', 'First give 2 to x, 3 to y, and 1 to z (total 6 items used). That leaves 18 - 6 = 12 items to distribute freely among 3 variables: C(12 + 3 - 1, 3 - 1) = C(14, 2).', 1.55, 1.1, 0.25, 'AIME Qualifier / AMC 10 Distinction', true),
  ('C09-MAT-05', 9, '9-10', 'mathematicalReasoning', 'olympiad', 'Let f(x) be a polynomial with integer coefficients such that f(1) = 5 and f(7) = 23. Using the polynomial remainder divisibility lemma (for any integer polynomial, (a - b) divides (f(a) - f(b))), which of the following could potentially be the integer value of f(19)?', '[{"text":"59 (Divisibility requirements: (19 - 1) = 18 must divide f(19) - 5; and (19 - 7) = 12 must divide f(19) - 23. For 59: 59 - 5 = 54 (divisible by 18, 54/18 = 3); and 59 - 23 = 36 (divisible by 12, 36/12 = 3). Both hold!).","correct":true},{"text":"50 (50 - 5 = 45, not divisible by 18).","correct":false},{"text":"72 (72 - 5 = 67, prime and not divisible by 18).","correct":false},{"text":"41 (41 - 23 = 18, not divisible by 12).","correct":false}]'::jsonb, 'Integer polynomial properties, (a - b) | (P(a) - P(b)) divisibility lemma, modular congruence constraints, and Diophantine analysis.', 'Test each option: f(19) - 5 must be a multiple of 18 (19-1), AND f(19) - 23 must be a multiple of 12 (19-7). Check 59.', 1.65, 1.4, 0.25, 'USAMO Junior / Canadian Mathematical Olympiad / Tournament of Towns', true),
  ('C09-MAT-06', 9, '9-10', 'mathematicalReasoning', 'olympiad', 'In a convex cyclic quadrilateral ABCD inscribed in a circle, side lengths are AB = 2, BC = 3, CD = 4, and DA = 5. Using Brahmagupta’s formula (Area = √[(s-a)(s-b)(s-c)(s-d)]), what is the exact area of quadrilateral ABCD, and what condition allows this formula to apply?', '[{"text":"Area = 2√30 (Semi-perimeter s = (2+3+4+5)/2 = 7; Area = √[(7-2)(7-3)(7-4)(7-5)] = √[5 × 4 × 3 × 2] = √120 = 2√30 ≈ 10.954); applies because the quadrilateral is concyclic (inscribed in a circle).","correct":true},{"text":"Area = 14 (assuming the quadrilateral is a rectangle).","correct":false},{"text":"Area = 30 (multiplying (s-a)(s-b)... without square root).","correct":false},{"text":"Area = 5√6 (arithmetic error under radical).","correct":false}]'::jsonb, 'Brahmagupta’s formula for cyclic quadrilaterals, semi-perimeter derivation, Ptolemy’s theorem context, and exact radical geometry.', 'Find semi-perimeter s = (2+3+4+5)/2 = 7. Subtract each side from 7: (5, 4, 3, 2). Multiply them together under the square root: √(5×4×3×2) = √120.', 1.7, 1.6, 0.25, 'IMO Foundation / Harvard-MIT Mathematics Tournament (HMMT)', true),
  ('C09-SYS-01', 9, '9-10', 'systemsThinking', 'standard', 'In modern semiconductor manufacturing, lithography fab lines operate with statistical process control (SPC). If a wafer manufacturing step has an upper specification limit (USL) and lower specification limit (LSL), what does a Process Capability Index C_pk = 1.67 signify to quality engineering systems?', '[{"text":"The process operates at Six Sigma quality (process distribution width 6σ is well within tolerance band with virtually zero defective parts per million, PPM < 0.6).","correct":true},{"text":"1.67% of all manufactured microchips will fail during the first month.","correct":false},{"text":"The factory must immediately shut down all cleanrooms for chemical decontamination.","correct":false},{"text":"Process variance is completely random and cannot be modeled mathematically.","correct":false}]'::jsonb, 'Statistical Process Control (SPC), Process Capability Index (C_pk), Six Sigma manufacturing quality, and defect ppm reduction.', 'A C_pk of 1.0 means the 3-sigma curve just touches the spec limits (~0.27% defect). A C_pk of 1.67 means 5-sigma margin, indicating world-class precision.', 1.35, 0.35, 0.25, 'IEEE Semiconductor Manufacturing / ASQ Quality Engineering Certification Primer', true),
  ('C09-SYS-02', 9, '9-10', 'systemsThinking', 'standard', 'A municipal electric utility implements Dynamic Time-of-Use (TOU) electricity pricing. Rates are $0.08/kWh from 11 PM - 7 AM (off-peak), $0.16/kWh from 7 AM - 4 PM (mid-peak), and $0.45/kWh from 4 PM - 9 PM (critical peak). In systems dynamics, what structural archetype does TOU pricing leverage to mitigate the utility’s evening "Duck Curve"?', '[{"text":"Price elasticity of demand feedback: high peak prices incentivize automated smart thermostats and EV chargers to shift discretionary electrical load away from peak solar drop-off hours.","correct":true},{"text":"Tragedy of the Commons: forcing all consumers to permanently disconnect from the grid.","correct":false},{"text":"Unregulated positive feedback: driving electrical consumption to infinity during peak hours.","correct":false},{"text":"Planned obsolescence: causing air conditioning compressors to mechanically fail at 4 PM.","correct":false}]'::jsonb, 'California Duck Curve power dynamics, demand-side management, dynamic TOU pricing feedback, and grid load-shifting.', 'When rooftop solar drops as the sun sets while families return home, electricity demand spikes vertically. Raising prices during those exact hours convinces machines to run later at night.', 1.4, 0.55, 0.25, 'Nature Hum. Soc. Sci. 2026 Smart Systems / IEEE Power Engineering', true),
  ('C09-SYS-03', 9, '9-10', 'systemsThinking', 'advanced', 'In synthetic biology and genetic circuit design, a "Repressilator" consists of three genes (tetR, lacI, and cI) connected in a cyclic negative feedback loop where Protein A represses Gene B, Protein B represses Gene C, and Protein C represses Gene A. Under what kinetic parameter conditions does this synthetic gene regulatory network exhibit sustained limit-cycle oscillations rather than dampening to a stable steady state?', '[{"text":"High cooperativity (Hill coefficient n > 2 in transcriptional repression), balanced protein/mRNA degradation rates, and sufficient transcriptional delay/gain.","correct":true},{"text":"Complete absence of any cellular ribosomes.","correct":false},{"text":"Hill coefficient n = 0, meaning repression is completely independent of repressor concentration.","correct":false},{"text":"Instantaneous infinite degradation of all mRNA transcripts within 1 femtosecond.","correct":false}]'::jsonb, 'Synthetic biology gene regulatory circuits, Repressilator design (Elowitz & Leibler), limit cycle oscillations, and nonlinear Hill kinetics.', 'To get a sustained biological clock oscillation rather than settling down, repression must be steep and cooperative (high Hill coefficient n > 2) with time delays.', 1.5, 0.95, 0.25, 'iGEM (International Genetically Engineered Machine) High School / Nature Biotechnology', true),
  ('C09-SYS-04', 9, '9-10', 'systemsThinking', 'advanced', 'In urban climate science, the "Urban Heat Island" (UHI) effect elevates metropolitan temperatures by 3-8°C above surrounding rural landscapes. Which multi-system intervention matrix provides the most synergistic cooling by addressing both sensible heat flux and latent heat flux simultaneously?', '[{"text":"High-albedo \"cool roofs\" (increasing solar reflectance to reduce sensible heat absorption) paired with extensive urban tree canopy and bioswales (maximizing latent heat dissipating evapotranspiration).","correct":true},{"text":"Installing 10,000 outdoor air-conditioning chiller fans blasting heat directly into downtown sidewalks.","correct":false},{"text":"Paving all city parks with dark asphalt to absorb heat deep into underground bedrock.","correct":false},{"text":"Erecting giant glass mirrors around city borders to block natural wind ventilation.","correct":false}]'::jsonb, 'Urban climatology, sensible vs. latent heat flux partitioning, albedo surface physics, and urban nature-based resilience engineering.', 'Cool roofs reflect sunlight before it turns into heat (sensible heat), while living plants use solar energy to evaporate water vapor, chilling the air (latent heat).', 1.55, 1.15, 0.25, 'UN SDG 11 Sustainable Cities / IPCC Working Group II Urban Climate Systems', true),
  ('C09-SYS-05', 9, '9-10', 'systemsThinking', 'olympiad', 'In modern macroeconomic modeling, the New Keynesian Dynamic Stochastic General Equilibrium (DSGE) model couples three core equations: (1) Forward-looking Investment-Saving (IS) curve, (2) New Keynesian Phillips Curve (NKPC), and (3) Monetary Policy Taylor Rule: i_t = r* + π_t + 0.5(π_t - π*) + 0.5(y_t - y*). According to the "Taylor Principle", what mathematical condition on the monetary response coefficient to inflation (ϕ_π) is required to guarantee determinacy (a unique, non-explosive rational expectations equilibrium)?', '[{"text":"ϕ_π > 1 (The central bank must raise the nominal interest rate more than one-for-one with increases in inflation, ensuring that the REAL interest rate rises to cool aggregate demand).","correct":true},{"text":"ϕ_π = 0 (Interest rates must remain completely fixed regardless of inflation).","correct":false},{"text":"ϕ_π < -1 (Central banks should cut interest rates aggressively whenever inflation surges).","correct":false},{"text":"Determinacy in rational expectations models is mathematically independent of central bank policy.","correct":false}]'::jsonb, 'New Keynesian DSGE macroeconomic modeling, Taylor Rule, Taylor Principle (ϕ_π > 1), real interest rate transmission, and rational expectations determinacy.', 'If inflation rises by 1%, the central bank must raise nominal interest rates by MORE than 1% so that the real interest rate (r = i - π) actually rises to dampen borrowing.', 1.65, 1.45, 0.25, 'International Economics Olympiad / MIT System Dynamics Macroeconomics Group', true),
  ('C09-SYS-06', 9, '9-10', 'systemsThinking', 'olympiad', 'In nonlinear dynamics and chaos theory, the Lorenz system: dx/dt = σ(y - x), dy/dt = x(ρ - x) - y, dz/dt = xy - βz exhibits deterministic chaos for classical parameters σ=10, β=8/3, ρ=28. The trajectories in phase space are attracted to a strange attractor with fractional Hausdorff dimension d ≈ 2.06. What is the fundamental physical implication of a positive maximal Lyapunov exponent (λ_max > 0) in this system?', '[{"text":"Sensitive dependence on initial conditions (\"Butterfly Effect\"): nearby trajectories in phase space diverge exponentially at rate e^(λt), rendering long-term deterministic forecasting fundamentally impossible despite deterministic governing equations.","correct":true},{"text":"The system collapses into a static stationary point at the origin (0, 0, 0) within finite time.","correct":false},{"text":"Trajectories form perfectly closed periodic circles with constant orbital velocity.","correct":false},{"text":"The system violates the conservation of energy by generating infinite kinetic energy.","correct":false}]'::jsonb, 'Deterministic chaos, Lorenz strange attractor, Lyapunov exponents, phase space trajectories, and limits of deterministic predictability.', 'A positive Lyapunov exponent means that two starting points separated by a microscopic distance δx₀ will diverge apart as δx(t) ≈ δx₀ · e^(λt).', 1.7, 1.65, 0.25, 'Santa Fe Institute Complex Systems Scholar / European Physics Olympiad Advanced Theory', true);


-- Batch for Class 10 (30 questions)
INSERT INTO public.scenarios (
  scenario_code, class_level, developmental_band, competency, difficulty,
  prompt, options, learning_objective, hint, irt_a, irt_b, irt_c,
  international_benchmark, is_active
) VALUES
  ('C10-SCI-01', 10, '9-10', 'scientificInquiry', 'standard', 'An analytical chemist measures the standard cell potential (E°_cell) of a galvanic Daniell cell: Zn(s) | Zn²⁺(1.0 M) || Cu²⁺(1.0 M) | Cu(s). Standard reduction potentials: Cu²⁺ + 2e⁻ → Cu(s) (E° = +0.34 V); Zn²⁺ + 2e⁻ → Zn(s) (E° = -0.76 V). What is the standard cell potential E°_cell and the standard Gibbs free energy change (ΔG°), taking Faraday''s constant F = 96,485 C/mol?', '[{"text":"E°_cell = +1.10 V; ΔG° = -nFE° = -2 × 96,485 × 1.10 = -212.3 kJ/mol (spontaneous electrochemical reaction).","correct":true},{"text":"E°_cell = -0.42 V; ΔG° = +81.1 kJ/mol (non-spontaneous).","correct":false},{"text":"E°_cell = +0.42 V; ΔG° = -40.5 kJ/mol.","correct":false},{"text":"E°_cell = +1.10 V; ΔG° = +212.3 kJ/mol (requiring continuous external electrical power).","correct":false}]'::jsonb, 'Electrochemistry, galvanic Daniell cell, standard reduction potentials (E°_cell = E°_cathode - E°_anode), and Gibbs free energy relation (ΔG° = -nFE°).', 'E°_cell = E°_reduction(cathode) - E°_reduction(anode) = +0.34 - (-0.76) = +1.10 V. Plug into ΔG° = -n F E° with n = 2 electrons transferred.', 1.35, 0.45, 0.25, 'PISA 2022 Science Advanced / Cambridge IGCSE / GCE O-Level Chemistry', true),
  ('C10-SCI-02', 10, '9-10', 'scientificInquiry', 'standard', 'A physics student directs a monochromatic green laser (λ = 532 nm) through a double slit with slit separation d = 0.20 mm onto a projection screen placed L = 2.0 meters away. What is the fringe spacing (distance Δy between adjacent bright constructive interference fringes on the screen)?', '[{"text":"5.32 mm (Using Young’s double slit formula Δy = (λ·L)/d = (532 × 10⁻⁹ m × 2.0 m) / (0.20 × 10⁻³ m) = 1.064 × 10⁻⁶ / 2.0 × 10⁻⁴ = 5.32 × 10⁻³ m = 5.32 mm).","correct":true},{"text":"1.06 mm (dividing by 10).","correct":false},{"text":"10.64 mm (forgetting to divide by slit separation).","correct":false},{"text":"0.53 mm (unit conversion error from nanometers to meters).","correct":false}]'::jsonb, 'Wave optics, Young’s double-slit experiment, interference fringe width derivation (Δy = λL/d), and wave-particle duality evidence.', 'Fringe spacing formula is Δy = (λ × L) / d. Make sure all units are converted to meters before calculating: 532×10⁻⁹ m, 2.0 m, 0.20×10⁻³ m.', 1.4, 0.65, 0.25, 'TIMSS Advanced Physics / Cambridge International A-Level Physics Foundation', true),
  ('C10-SCI-03', 10, '9-10', 'scientificInquiry', 'advanced', 'In organic chemistry, 2-bromo-2-methylpropane undergoes nucleophilic substitution in aqueous ethanol to form 2-methylpropan-2-ol. Kinetic measurements show that doubling the concentration of alkyl halide doubles the reaction rate, but doubling the concentration of hydroxide nucleophile has zero effect on the rate (Rate = k[R-Br]¹[OH⁻]⁰). What reaction mechanism is occurring, and what is the rate-determining step?', '[{"text":"S_N1 mechanism (unimolecular nucleophilic substitution): the slow rate-determining step is heterolytic dissociation of the C-Br bond forming a stable tertiary carbocation intermediate.","correct":true},{"text":"S_N2 mechanism (bimolecular nucleophilic substitution): backside attack with a pentacoordinate transition state.","correct":false},{"text":"E2 elimination forming 2-methylpropene gas exclusively.","correct":false},{"text":"Free-radical halogenation catalyzed by ambient room ultraviolet light.","correct":false}]'::jsonb, 'Reaction mechanisms in organic chemistry, S_N1 vs S_N2 kinetics, carbocation intermediate stability, and rate-determining steps.', 'Because the rate depends ONLY on the alkyl halide concentration and NOT on the nucleophile (Rate = k[substrate]), it must be unimolecular (S_N1).', 1.5, 0.95, 0.25, 'USNCO Local / National Chemistry Olympiad Prep / Singapore GCE A-Level H2 Chemistry', true),
  ('C10-SCI-04', 10, '9-10', 'scientificInquiry', 'advanced', 'A uniform solid cylinder of mass M and radius R rolls without slipping down an incline of angle θ from height h. Its moment of inertia is I = ½MR². Using conservation of mechanical energy (Mgh = ½Mv² + ½Iω²) and the rolling constraint (v = ωR), what is the translational acceleration of the cylinder down the incline?', '[{"text":"a = ⅔ g·sin(θ) (Total kinetic energy = ½Mv² + ½(½MR²)(v/R)² = ¾Mv²; applying Newton’s 2nd law or energy: acceleration = g·sin(θ) / (1 + I/MR²) = g·sin(θ) / (1 + 0.5) = ⅔ g·sin(θ)).","correct":true},{"text":"a = g·sin(θ) (identical to a frictionless sliding block).","correct":false},{"text":"a = ½ g·sin(θ) (assuming rotational kinetic energy equals translational energy).","correct":false},{"text":"a = ¾ g·sin(θ).","correct":false}]'::jsonb, 'Rotational dynamics, rolling without slipping, rotational kinetic energy (½Iω²), and angular acceleration down an inclined plane.', 'Because some potential energy converts into rotational kinetic energy rather than translational motion, rolling objects accelerate slower than frictionless sliders: a = g sin(θ) / (1 + I/(MR²)).', 1.55, 1.15, 0.25, 'AAPF US Physics Bowl / F=ma Contest / Singapore Physics Olympiad', true),
  ('C10-SCI-05', 10, '9-10', 'scientificInquiry', 'olympiad', 'In molecular orbital (MO) theory, the oxygen molecule (O₂) exhibits paramagnetism (it is attracted into magnetic field gradients). Why does Lewis valence-bond structure (:Ö=Ö:) fail to explain this magnetic property, and how does the MO electron configuration of O₂ resolve it?', '[{"text":"Lewis structures show all electrons paired in bonds or lone pairs (diamagnetic); MO theory shows that filling the highest occupied molecular orbitals results in two unpaired electrons with parallel spins in the degenerate antibonding π*₂p_x and π*₂p_y orbitals (Hund’s rule).","correct":true},{"text":"Lewis structures predict oxygen contains metallic iron impurities that align with magnets.","correct":false},{"text":"MO theory proves that oxygen molecules have zero electrons in their valence shell.","correct":false},{"text":"Paramagnetism is caused exclusively by nuclear spin states that molecular orbitals ignore.","correct":false}]'::jsonb, 'Molecular Orbital (MO) theory, paramagnetism vs. diamagnetism, degenerate π* antibonding orbitals, Hund’s rule of maximum multiplicity, and failure of Lewis structures.', 'Liquid oxygen sticks between the poles of a strong magnet! Lewis structures show all paired electrons, but MO theory reveals two lonely unpaired electrons in the π* antibonding level.', 1.65, 1.5, 0.25, 'International Chemistry Olympiad (IChO) / US National Chemistry Olympiad (USNCO)', true),
  ('C10-SCI-06', 10, '9-10', 'scientificInquiry', 'olympiad', 'A particle of mass m is trapped in a one-dimensional infinite square potential well of width L (V(x) = 0 for 0 < x < L, and V(x) = ∞ otherwise). By solving the time-independent Schrödinger equation (-ℏ²/2m · d²ψ/dx² = Eψ), what are the quantized energy eigenvalues E_n and what is the probability of finding a particle in the ground state (n = 1) between x = 0 and x = L/4?', '[{"text":"E_n = (n²π²ℏ²) / (2mL²) = (n²h²) / (8mL²); Probability P = ∫₀^(L/4) (2/L)sin²(πx/L)dx = [x/L - (1/2π)sin(2πx/L)]₀^(L/4) = 1/4 - 1/(2π) ≈ 0.25 - 0.159 = 0.091 (approx 9.1%).","correct":true},{"text":"E_n = nhf; Probability is exactly 25.0% because probability density is uniform across the entire well.","correct":false},{"text":"E_n = ½mω²L²; Probability is zero because quantum particles only exist at the exact center x = L/2.","correct":false},{"text":"E_n = nℏc/L; Probability is 50.0%.","correct":false}]'::jsonb, 'Quantum mechanics, particle in a box (1D infinite well), Schrödinger wave equation solution, quantized eigenvalues, and wave function probability density integration (ψ²).', 'Energy is E_n = n²h² / (8mL²). The ground state wave function is ψ(x) = √(2/L) sin(πx/L). Integrate ψ² from 0 to L/4: it is less than 25% because sin² peaks at the center.', 1.7, 1.75, 0.25, 'IPhO Theoretical Exam / European Physics Olympiad / International Physics Olympiad', true),
  ('C10-COM-01', 10, '9-10', 'computationalThinking', 'standard', 'In cryptographic protocols, a cryptographic hash function (e.g., SHA-256) maps arbitrary-length data to a fixed 256-bit digest. According to the "Birthday Paradox", approximately how many random inputs must an attacker hash before having a 50% probability of finding ANY two inputs with an identical hash collision (collision resistance attack)?', '[{"text":"Approximately 2¹²⁸ hash evaluations (~√(2²⁵⁶) = 2^(256/2)), drastically lower than brute-forcing a specific preimage (2²⁵⁶).","correct":true},{"text":"Exactly 2²⁵⁶ hash evaluations (requiring an exhaustive check of all possible digests).","correct":false},{"text":"256 hash evaluations (one for each bit of the digest).","correct":false},{"text":"365 hash evaluations (based on calendar days).","correct":false}]'::jsonb, 'Cryptographic hash functions, Birthday Paradox, collision resistance bounds (O(2^(n/2))), and security parameter sizing.', 'The Birthday Paradox states that finding ANY collision between any two elements in a space of size N requires only ~√N samples. For 2²⁵⁶, √N = 2¹²⁸.', 1.35, 0.5, 0.25, 'CyberPatriot / CSTA Level 3B Cybersecurity / Bebras Senior', true),
  ('C10-COM-02', 10, '9-10', 'computationalThinking', 'standard', 'An autonomous navigation robot uses an occupancy grid map to plan paths with the A* search algorithm. The heuristic function h(n) estimates distance from node n to the target. What mathematical condition must the heuristic satisfy to be "admissible", and what happens if an inadmissible heuristic is used?', '[{"text":"The heuristic must never overestimate the true minimum cost to reach the goal (h(n) ≤ h*(n)); an inadmissible heuristic may cause A* to return a suboptimal path instead of the true shortest path.","correct":true},{"text":"The heuristic must always equal zero (turning A* into depth-first search).","correct":false},{"text":"The heuristic must overestimate cost by at least 100% to ensure safety margins.","correct":false},{"text":"Admissibility means the heuristic can only use integer coordinates.","correct":false}]'::jsonb, 'A* heuristic search, admissibility criterion (h(n) ≤ h*(n)), consistency (triangle inequality), and optimality guarantees.', 'Admissible means optimistic: if your estimate of remaining distance is never larger than reality, A* is mathematically guaranteed to find the true shortest path.', 1.4, 0.7, 0.25, 'USACO Silver Division / AP Computer Science Principles AI', true),
  ('C10-COM-03', 10, '9-10', 'computationalThinking', 'advanced', 'In dynamic programming, the Longest Common Subsequence (LCS) problem finds the longest subsequence present in both string X of length m and string Y of length n. If the recurrence is: 
LCS(i, j) = LCS(i-1, j-1) + 1 if X[i] == Y[j] 
else max(LCS(i-1, j), LCS(i, j-1)). 
For strings X = "ALGORITHM" and Y = "LOGARITHMIC", what is the length of their Longest Common Subsequence?', '[{"text":"6 characters (Subsequence: \"L-G-R-I-T-M\" appears in order in both strings: \"a-L-G-o-R-I-T-h-M\" and \"L-o-G-a-R-I-T-h-M-i-c\"; wait: \"A-L-G-O-R-I-T-H-M\" has L, G, R, I, T, H, M: 7 characters! Check: \"L-G-R-I-T-H-M\" -> X has L(1), G(2), R(4), I(5), T(6), H(7), M(8). Y has L(0), G(2), R(4), I(5), T(6), H(7), M(8). That is 7 characters: L, G, R, I, T, H, M!).","correct":false},{"text":"7 characters (\"L\", \"G\", \"R\", \"I\", \"T\", \"H\", \"M\" appear sequentially in both \"ALGORITHM\" and \"LOGARITHMIC\").","correct":true},{"text":"5 characters (\"A\", \"L\", \"G\", \"O\", \"R\").","correct":false},{"text":"9 characters (identical to the length of ALGORITHM).","correct":false}]'::jsonb, 'Dynamic programming, Longest Common Subsequence (LCS) table construction, recurrence memoization, and bioinformatics sequence alignment (Needleman-Wunsch).', 'Trace the shared letters in order: L... G... R... I... T... H... M. All 7 letters appear in the exact same left-to-right sequence in both words!', 1.5, 1, 0.25, 'USACO Gold Division / Canadian Computing Competition Senior', true),
  ('C10-COM-04', 10, '9-10', 'computationalThinking', 'advanced', 'A convolutional neural network (CNN) for computer vision processes an input RGB image of size 224 × 224 × 3 pixels. The first layer applies 64 filters of size 7 × 7 with stride s = 2 and padding p = 3. What is the spatial dimensions (height × width × depth) of the resulting output feature map, and how many trainable weight parameters does this convolutional layer contain (excluding biases)?', '[{"text":"Output size: 112 × 112 × 64; Trainable weights: 9,408 (Output spatial dimension = ⌊(224 - 7 + 2×3)/2⌋ + 1 = ⌊223/2⌋ + 1 = 111 + 1 = 112; Weights = 7 × 7 × 3_input_channels × 64_filters = 49 × 3 × 64 = 9,408).","correct":true},{"text":"Output size: 224 × 224 × 64; Trainable weights: 3,136.","correct":false},{"text":"Output size: 56 × 56 × 64; Trainable weights: 18,816.","correct":false},{"text":"Output size: 112 × 112 × 3; Trainable weights: 64.","correct":false}]'::jsonb, 'Convolutional neural networks (CNNs), feature map dimension formula (⌊(W - K + 2P)/S⌋ + 1), filter tensor sizing, and parameter counting in deep learning.', 'Spatial size formula: (W - K + 2P)/S + 1 = (224 - 7 + 6)/2 + 1 = 223/2 + 1 = 112. Parameter count: filter_height × filter_width × input_channels × num_filters.', 1.55, 1.25, 0.25, 'Nature Hum. Soc. Sci. 2026 AI Pillar / International Olympiad in Artificial Intelligence (IOAI)', true),
  ('C10-COM-05', 10, '9-10', 'computationalThinking', 'olympiad', 'In maximum network flow problems, the Ford-Fulkerson method finds maximum flow from source S to sink T. The Edmonds-Karp algorithm specifies using Breadth-First Search (BFS) to select the shortest augmenting path (fewest edges) at each step. What is the guaranteed asymptotic upper bound on the time complexity of the Edmonds-Karp algorithm for a network with V vertices and E edges?', '[{"text":"O(V · E²), because the length of the shortest augmenting path increases monotonically, and each of the E edges can become critical at most V/2 times.","correct":true},{"text":"O(V² · E), identical to Dinic’s algorithm with blocking flows.","correct":false},{"text":"O(E · log V), identical to Dijkstra’s algorithm.","correct":false},{"text":"O(V³), independent of the number of edges.","correct":false}]'::jsonb, 'Network flow algorithms, Edmonds-Karp BFS augmentation, critical edge bounding, and asymptotic complexity proofs (O(VE²)).', 'BFS guarantees that shortest path distances in the residual graph never decrease. An edge becomes bottlenecked ("critical") at most V/2 times. E edges × (V/2) iterations × O(E) per BFS = O(V·E²).', 1.65, 1.55, 0.25, 'IOI / ACM ICPC World Finals Foundation / USACO Platinum', true),
  ('C10-COM-06', 10, '9-10', 'computationalThinking', 'olympiad', 'In computational geometry, finding the Convex Hull of a set of n planar 2D points is fundamental. The Graham Scan algorithm sorts points by polar angle and uses a stack with orientation 2D cross-products to maintain counterclockwise turns in O(n log n) time. Why is O(n log n) mathematically proven to be the absolute lower bound for convex hull algorithms in the algebraic decision tree model?', '[{"text":"Sorting can be reduced in linear time to the 2D Convex Hull problem (by mapping numbers x_i to parabolas (x_i, x_i²)); since comparison sorting has an Ω(n log n) lower bound, finding the convex hull cannot be faster than Ω(n log n).","correct":true},{"text":"Because triangles have three vertices and 3 × n = 3n which equals n log n in binary notation.","correct":false},{"text":"Computer monitors cannot refresh pixels faster than log(n) frames per second.","correct":false},{"text":"Convex hull algorithms must evaluate all n! permutations of points.","correct":false}]'::jsonb, 'Computational geometry lower bounds, Graham Scan mechanics, asymptotic reduction proofs (sorting to convex hull reduction), and Ω(n log n) optimality.', 'If you could find the convex hull in O(n) time, you could sort numbers in O(n) time by projecting them onto y = x² and reading off the hull. But comparison sorting is Ω(n log n)!', 1.7, 1.75, 0.25, 'IOI Advanced Theory / ACM-SIAM Symposium on Discrete Algorithms (SODA)', true),
  ('C10-ENG-01', 10, '9-10', 'engineeringDesign', 'standard', 'In civil engineering, the Euler critical buckling load for an ideal slender column of length L, elastic modulus E, and second moment of area I is given by: P_cr = (π²·E·I) / (K·L)², where K is the effective length factor. If a column with pinned-pinned ends (K = 1.0) is redesigned to have both ends rigidly clamped/fixed into solid concrete footings (fixed-fixed, K = 0.5), how does its critical buckling load change?', '[{"text":"The critical buckling load increases by a factor of 4 (P_cr ∝ 1/K² = 1/(0.5)² = 1/0.25 = 4).","correct":true},{"text":"The critical buckling load doubles (factor of 2).","correct":false},{"text":"The critical buckling load is halved because fixed ends trap bending stress.","correct":false},{"text":"The buckling load remains unchanged because material E and column length L are identical.","correct":false}]'::jsonb, 'Structural mechanics, Euler column buckling equation (P_cr = π²EI/(KL)²), boundary condition effective length factor K, and compressive stability.', 'The factor K is in the denominator and is squared: (K·L)². If K drops from 1.0 to 0.5, the denominator is multiplied by (0.5)² = 0.25. Dividing by 0.25 is multiplying by 4!', 1.35, 0.45, 0.25, 'ASCE Student Bridge Competition / Cambridge A-Level Engineering', true),
  ('C10-ENG-02', 10, '9-10', 'engineeringDesign', 'standard', 'A bio-medical engineering team designs a high-gradient magnetic drug delivery catheter. Superparamagnetic iron oxide nanoparticles (SPIONs) in the bloodstream experience a magnetic force F_m = (m · ∇)B. Why must the external magnetic field have a high SPATIAL GRADIENT (∇B) rather than merely a high uniform magnetic field strength B?', '[{"text":"A uniform magnetic field exerts zero net translational force on a magnetic dipole (it only exerts an alignment torque τ = m × B); a spatial gradient (∇B ≠ 0) is required to exert directional pulling force.","correct":true},{"text":"Uniform fields turn blood cells into solid permanent bar magnets that cause immediate heart attacks.","correct":false},{"text":"Magnetic gradients destroy the plastic catheter tubing through electromagnetic induction.","correct":false},{"text":"Nanoparticles dissolve instantly when exposed to uniform magnetic fields.","correct":false}]'::jsonb, 'Electromagnetic force on magnetic dipoles (F = (m·∇)B), uniform vs. gradient fields, biomedical nanotechnology, and targeted drug delivery mechanics.', 'In a uniform magnetic field, the north pole is pulled right and the south pole is pulled left with equal force—net force is zero! You need a gradient so one side is pulled harder than the other.', 1.4, 0.7, 0.25, 'IEEE Engineering in Medicine and Biology Society / BMES High School Scholar', true),
  ('C10-ENG-03', 10, '9-10', 'engineeringDesign', 'advanced', 'An RF microwave engineer designs a quarter-wavelength transmission line impedance transformer (length ℓ = λ/4) to match a 50 Ω coaxial cable to a 200 Ω antenna load without signal reflection. What characteristic impedance Z₀_line must the quarter-wave matching section possess?', '[{"text":"100 Ω (Using quarter-wave impedance formula Z₀_line = √(Z_in × Z_load) = √(50 × 200) = √10,000 = 100 Ω).","correct":true},{"text":"125 Ω (the arithmetic average: (50 + 200)/2).","correct":false},{"text":"150 Ω (the difference: 200 - 50).","correct":false},{"text":"40 Ω (dividing 200 by 50).","correct":false}]'::jsonb, 'RF transmission lines, impedance matching, quarter-wave transformers (Z₀ = √(Z_in·Z_L)), standing wave ratio (SWR), and reflection coefficient elimination.', 'A quarter-wave matching line has characteristic impedance equal to the geometric mean of the input and load impedances: Z = √(Z₁ · Z₂).', 1.5, 1, 0.25, 'IEEE Microwave Theory and Technology Society (MTT-S) Student Challenge', true),
  ('C10-ENG-04', 10, '9-10', 'engineeringDesign', 'advanced', 'In designing a high-temperature solid oxide fuel cell (SOFC), yttria-stabilized zirconia (YSZ) is chosen as the solid electrolyte membrane operating at 800°C. Which transport property makes YSZ uniquely effective at separating gaseous fuel (H₂) from air (O₂) while conducting electrochemical current?', '[{"text":"High ionic conductivity for oxide ions (O²⁻) via oxygen vacancy hopping, combined with negligible electronic conductivity, preventing internal electrical short-circuiting.","correct":true},{"text":"High electrical conductivity for electrons combined with zero gas impermeability.","correct":false},{"text":"It acts as a porous sponge that lets hydrogen and oxygen gases mix and burn in open flame.","correct":false},{"text":"It converts ambient thermal radiation into nuclear fission products.","correct":false}]'::jsonb, 'Solid-state ionics, Solid Oxide Fuel Cells (SOFC), defect chemistry, oxygen vacancy transport mechanisms, and electronic insulation requirements.', 'A fuel cell electrolyte must conduct ions (charged atoms) while completely blocking electrons (so electrons are forced to travel through the external circuit doing useful work).', 1.55, 1.25, 0.25, 'Materials Research Society (MRS) Student Challenge / UN SDG 7', true),
  ('C10-ENG-05', 10, '9-10', 'engineeringDesign', 'olympiad', 'In designing a satellite attitude determination and control system (ADCS), three orthogonal reaction wheels provide 3-axis torque. The spacecraft''s rotational equations of motion are governed by Euler''s moment equations for a rigid body with principal moments of inertia I_x > I_y > I_z: 
I_x·dω_x/dt - (I_y - I_z)ω_yω_z = M_x 
I_y·dω_y/dt - (I_z - I_x)ω_zω_x = M_y 
I_z·dω_z/dt - (I_x - I_y)ω_xω_y = M_z. 
According to the Intermediate Axis Theorem (Tennis Racket Theorem / Dzhanibekov Effect), rotation about which principal axis is dynamically UNSTABLE to small perturbations?', '[{"text":"The intermediate axis (I_y): perturbation analysis shows that linearization around the intermediate moment of inertia produces imaginary eigenvalues (positive real parts in perturbation coupling), causing wild 180° flipping oscillations.","correct":true},{"text":"The major axis (I_x) with the largest moment of inertia.","correct":false},{"text":"The minor axis (I_z) with the smallest moment of inertia.","correct":false},{"text":"All three axes are equally stable in zero-gravity space environments.","correct":false}]'::jsonb, 'Euler’s rigid body rotational dynamics, Intermediate Axis Theorem (Dzhanibekov effect), principal moments of inertia, and spacecraft attitude stability.', 'Try spinning a tennis racket or a book in the air: spinning about its longest dimension is stable; spinning about its flattest dimension is stable; spinning about the middle dimension flips uncontrollably!', 1.65, 1.55, 0.25, 'AIAA Space Systems Award / International Space Settlement Design Competition', true),
  ('C10-ENG-06', 10, '9-10', 'engineeringDesign', 'olympiad', 'A tokamak fusion reactor design requires confining a deuterium-tritium plasma at temperature T = 15 keV (approx 150 million K) with plasma particle density n = 2.0 × 10²⁰ m⁻³. According to the Lawson Criterion for fusion ignition (n·T·τ_E ≥ 3 × 10²¹ keV·s/m³ for D-T fusion), what is the minimum required energy confinement time (τ_E) in seconds?', '[{"text":"τ_E ≥ 1.0 seconds (n·T = 2.0 × 10²⁰ × 15 = 3.0 × 10²¹ keV/m³; τ_E = (3 × 10²¹ keV·s/m³) / (3.0 × 10²¹ keV/m³) = 1.0 second).","correct":true},{"text":"τ_E ≥ 0.10 seconds.","correct":false},{"text":"τ_E ≥ 10.0 seconds.","correct":false},{"text":"τ_E ≥ 100.0 seconds.","correct":false}]'::jsonb, 'Nuclear fusion engineering, Lawson criterion triple product (n·T·τ_E), magnetic confinement fusion physics, and tokamak stability parameters (ITER).', 'Multiply density by temperature: (2.0 × 10²⁰) × 15 = 3.0 × 10²¹. Compare this directly to the Lawson threshold 3.0 × 10²¹ keV·s/m³.', 1.7, 1.8, 0.25, 'ITER International Fusion Youth / US Department of Energy Nuclear STEM Fellowship', true),
  ('C10-MAT-01', 10, '9-10', 'mathematicalReasoning', 'standard', 'Find the derivative f''(x) of the rational function: 
f(x) = (3x² - 5) / (2x + 1) 
using the Quotient Rule (d/dx [u/v] = (u''v - uv'') / v²). What is the value of f''(1)?', '[{"text":"f''(1) = 14/9 (u = 3x² - 5 → u'' = 6x; v = 2x + 1 → v'' = 2. At x = 1: u(1) = -2, u''(1) = 6, v(1) = 3, v''(1) = 2; f''(1) = [(6 × 3) - (-2 × 2)] / 3² = (18 - (-4)) / 9 = 22/9... wait! 18 - (-4) = 22! Let us check: f''(1) = 22/9).","correct":false},{"text":"22/9 (At x = 1: u = 3(1) - 5 = -2; u'' = 6(1) = 6; v = 2(1) + 1 = 3; v'' = 2; Quotient rule: [u''v - uv''] / v² = [(6)(3) - (-2)(2)] / (3)² = [18 - (-4)] / 9 = 22/9).","correct":true},{"text":"14/9 (subtracting 4 instead of adding negative 4).","correct":false},{"text":"2/3 (using ratio of derivatives: 6x / 2 = 3).","correct":false}]'::jsonb, 'Differential calculus, Quotient Rule for derivatives, polynomial differentiation, and evaluation at specific points.', 'Carefully compute [u''·v - u·v''] / v². Notice that subtracting a negative value (-2 × 2 = -4) becomes addition: 18 - (-4) = 22.', 1.35, 0.45, 0.25, 'PISA 2022 Advanced Math / AP Calculus AB Foundation', true),
  ('C10-MAT-02', 10, '9-10', 'mathematicalReasoning', 'standard', 'An ellipse centered at the origin has major axis along the x-axis with equation: 
(x² / 25) + (y² / 9) = 1. 
What is the eccentricity (e) of this ellipse, and what are the exact coordinates of its two foci?', '[{"text":"Eccentricity e = 4/5 = 0.8; Foci are located at (±4, 0) (Semi-major a = √25 = 5; Semi-minor b = √9 = 3; Focal distance c = √(a² - b²) = √(25 - 9) = √16 = 4; e = c/a = 4/5).","correct":true},{"text":"Eccentricity e = 3/5; Foci at (0, ±3).","correct":false},{"text":"Eccentricity e = 1.25; Foci at (±5, 0).","correct":false},{"text":"Eccentricity e = 0.5; Foci at (±2, 0).","correct":false}]'::jsonb, 'Conic sections, ellipse geometry (x²/a² + y²/b² = 1), focal distance equation (c² = a² - b²), and eccentricity (e = c/a).', 'Semi-major axis a = 5, semi-minor axis b = 3. In an ellipse, c² = a² - b² = 25 - 9 = 16, so c = 4. Eccentricity is c / a.', 1.4, 0.7, 0.25, 'TIMSS Advanced Mathematics / Cambridge IGCSE Additional Math', true),
  ('C10-MAT-03', 10, '9-10', 'mathematicalReasoning', 'advanced', 'Evaluate the definite integral representing the area under a curve: 
∫₀^(π/2) x · cos(x) dx. 
Using Integration by Parts (∫ u dv = u·v - ∫ v du), what is the exact numerical value of this integral?', '[{"text":"π/2 - 1 (Let u = x → du = dx; dv = cos(x)dx → v = sin(x); ∫ x cos(x)dx = [x sin(x)]₀^(π/2) - ∫₀^(π/2) sin(x)dx = (π/2 · 1 - 0) - [-cos(x)]₀^(π/2) = π/2 - [-0 - (-1)] = π/2 - 1 ≈ 0.5708).","correct":true},{"text":"π/2 (forgetting the second integral term).","correct":false},{"text":"1.0 (evaluating without the boundary factor).","correct":false},{"text":"π² / 4 (multiplying limits directly).","correct":false}]'::jsonb, 'Integral calculus, Integration by Parts formula (∫ u dv = uv - ∫ v du), trigonometric definite integrals, and exact evaluations.', 'Set u = x (so du = dx) and dv = cos(x)dx (so v = sin(x)). Evaluate [x·sin(x)] from 0 to π/2, then subtract the integral of sin(x).', 1.5, 1.05, 0.25, 'AP Calculus BC / Cambridge International A-Level Further Mathematics', true),
  ('C10-MAT-04', 10, '9-10', 'mathematicalReasoning', 'advanced', 'A 3×3 matrix A has eigenvalues λ₁ = 2, λ₂ = -1, and λ₃ = 4. What is the Trace of matrix A, the Determinant of matrix A, and the Determinant of the inverse matrix A⁻¹?', '[{"text":"Trace(A) = 5 (sum of eigenvalues: 2 + (-1) + 4 = 5); Det(A) = -8 (product of eigenvalues: 2 × (-1) × 4 = -8); Det(A⁻¹) = -1/8 (-0.125).","correct":true},{"text":"Trace(A) = -8; Det(A) = 5; Det(A⁻¹) = 1/5.","correct":false},{"text":"Trace(A) = 7; Det(A) = 8; Det(A⁻¹) = 8.","correct":false},{"text":"Trace(A) = 0; Det(A) = 0; matrix A is singular and cannot be inverted.","correct":false}]'::jsonb, 'Linear algebra, eigenvalue properties, spectral trace theorem (Trace = Σλ_i), determinant product theorem (Det = Πλ_i), and inverse determinant (Det(A⁻¹) = 1/Det(A)).', 'The trace of any matrix is the sum of its eigenvalues. The determinant is the product of its eigenvalues. The determinant of the inverse is 1 / Det(A).', 1.55, 1.3, 0.25, 'MIT 18.06 Linear Algebra Foundation / AMC 12', true),
  ('C10-MAT-05', 10, '9-10', 'mathematicalReasoning', 'olympiad', 'Let a, b, c be positive real numbers such that a + b + c = 1. Using Cauchy-Schwarz inequality in Engel form (Sedrakyan’s Lemma: Σ (x_i²/a_i) ≥ (Σ x_i)² / Σ a_i), what is the minimum possible value of the expression: 
S = 1/(1 + a) + 1/(1 + b) + 1/(1 + c)?', '[{"text":"9/4 (By Cauchy-Schwarz: (1/(1+a) + 1/(1+b) + 1/(1+c)) ≥ (1 + 1 + 1)² / ((1+a) + (1+b) + (1+c)) = 3² / (3 + (a+b+c)) = 9 / (3 + 1) = 9/4 = 2.25, achieved when a = b = c = 1/3).","correct":true},{"text":"3.0 (assuming minimum occurs at boundary points).","correct":false},{"text":"2.0 (arithmetic estimation).","correct":false},{"text":"1.0 (assuming the expression sums to the constraint).","correct":false}]'::jsonb, 'Olympiad inequalities, Cauchy-Schwarz inequality (Engel / Titu form), symmetry exploitation, and constrained minimization.', 'Apply Engel form: 1/(1+a) + 1/(1+b) + 1/(1+c) ≥ (1+1+1)² / ((1+a)+(1+b)+(1+c)). Substitute a+b+c = 1 in the denominator.', 1.65, 1.6, 0.25, 'USAMO / Romanian Master of Mathematics / IMO Training', true),
  ('C10-MAT-06', 10, '9-10', 'mathematicalReasoning', 'olympiad', 'In a triangle ABC, point D lies on side BC such that AD is an angle bisector of angle BAC. Side lengths are AB = c, AC = b, BC = a. By the Angle Bisector Theorem and Stewart’s Theorem, what is the exact length of the angle bisector d = AD in terms of sides a, b, c and segments m = BD, n = CD?', '[{"text":"AD² = b·c - m·n (where m = ac/(b+c) and n = ab/(b+c); Stewart’s theorem simplifies directly to d² = bc(1 - (a/(b+c))²)).","correct":true},{"text":"AD² = b² + c² - 2bc·cos(A).","correct":false},{"text":"AD = (b + c) / 2.","correct":false},{"text":"AD = √(a² + b² + c²).","correct":false}]'::jsonb, 'Advanced Euclidean geometry, Angle Bisector Theorem, Stewart’s Theorem (b²m + c²n = a(d² + mn)), and length derivation.', 'The classic formula for angle bisector length d using segment lengths m and n is d² = b·c - m·n.', 1.7, 1.8, 0.25, 'International Mathematical Olympiad (IMO) / USAMO', true),
  ('C10-SYS-01', 10, '9-10', 'systemsThinking', 'standard', 'In electrical power systems engineering, the "N-1 Reliability Criterion" mandates that a transmission grid must continue operating within normal voltage and frequency limits even if ANY single critical element (a large 1,000 MW generator, a high-voltage transmission line, or a primary transformer) experiences an immediate catastrophic trip. How do system operators practically enforce N-1 compliance?', '[{"text":"By maintaining spinning operating reserves (fast-start thermal/hydro units and battery storage) and running real-time contingency analysis power flow software.","correct":true},{"text":"By turning off power to hospitals and schools during thunderstorms.","correct":false},{"text":"By operating all transmission lines at 100% maximum thermal capacity around the clock.","correct":false},{"text":"By banning industrial factories from consuming alternating current.","correct":false}]'::jsonb, 'Power grid reliability, N-1 contingency criterion, spinning reserves, real-time AC power flow modeling, and blackout prevention.', 'To survive the sudden loss of any single major powerplant, the system must always have enough idling "spinning" reserve power ready to take over within seconds.', 1.35, 0.5, 0.25, 'IEEE Power & Energy Society / NERC Reliability Standards', true),
  ('C10-SYS-02', 10, '9-10', 'systemsThinking', 'standard', 'In cybersecurity and identity systems, multi-factor authentication (MFA) requires presenting at least two distinct authentication factor categories: (1) Knowledge (something you know), (2) Possession (something you have), and (3) Inherence (something you are). Which combination represents true multi-factor authentication?', '[{"text":"A memorized password (Knowledge) combined with a Time-based One-Time Password (TOTP) from a hardware security token (Possession).","correct":true},{"text":"A user password combined with a security question asking for their mother’s maiden name (both are Knowledge factors).","correct":false},{"text":"A fingerprint scan combined with a facial recognition camera scan (both are Inherence factors).","correct":false},{"text":"Entering the same alphanumeric password twice in two separate text boxes.","correct":false}]'::jsonb, 'Cybersecurity systems architecture, multi-factor authentication (MFA) taxonomy (Knowledge, Possession, Inherence), and defense-in-depth principles.', 'Two passwords are both "something you know" (one category). True MFA requires factors from DIFFERENT categories (e.g., something you know + something you have).', 1.4, 0.7, 0.25, 'NIST Special Publication 800-63B / CyberPatriot High School', true),
  ('C10-SYS-03', 10, '9-10', 'systemsThinking', 'advanced', 'In systems immunology, monoclonal antibody therapies for autoimmune diseases target Tumor Necrosis Factor-alpha (TNF-α) to suppress chronic inflammation. However, patients undergoing anti-TNF therapy have a tenfold increased risk of reactivating latent tuberculosis. What systemic immunological trade-off explains this vulnerability?', '[{"text":"Pleiotropic immune signaling: TNF-α is required for maintaining macrophage granuloma structural integrity that physically encapsulates latent Mycobacterium tuberculosis bacteria in lung tissue.","correct":true},{"text":"Anti-TNF antibodies chemically mutate into live tuberculosis bacteria.","correct":false},{"text":"Blocking TNF causes the spleen to dissolve completely into lymph fluid.","correct":false},{"text":"Tuberculosis bacteria eat synthetic antibody proteins as their primary sugar fuel.","correct":false}]'::jsonb, 'Systems immunology, cytokine pleiotropy, homeostatic trade-offs, granuloma maintenance (TNF-α), and opportunistic infection risks.', 'The very same signaling molecule that causes painful arthritis inflammation is also the molecular glue that keeps dangerous dormant tuberculosis bacteria trapped inside microscopic cages in the lung.', 1.5, 1.1, 0.25, 'USABO Semifinalist / Biomedical Engineering Society Systems Physiology', true),
  ('C10-SYS-04', 10, '9-10', 'systemsThinking', 'advanced', 'In planetary carbon cycle modeling, the Permafrost Carbon Feedback is a major climate tipping risk. Arctic permafrost soils store ~1,400 to 1,600 gigatonnes of frozen organic carbon. As rising global temperatures thaw the active permafrost layer, microbial anaerobic decomposition produces methane (CH₄, which has a 28× higher 100-year Global Warming Potential than CO₂). Why is this modeled as an accelerating positive feedback loop with strong hysteresis?', '[{"text":"Warming thaws permafrost → microbial respiration emits greenhouse gases (CO₂ & CH₄) → increased atmospheric radiative forcing drives further planetary warming → accelerates deeper thermokarst thawing.","correct":true},{"text":"Methane emissions instantly freeze the Arctic ocean into solid glaciers, cooling the planet.","correct":false},{"text":"Thawed permafrost creates black holes that absorb the Earth’s atmosphere.","correct":false},{"text":"Microbes consume atmospheric nitrogen, eliminating all air resistance.","correct":false}]'::jsonb, 'Earth systems climate modeling, permafrost carbon feedback, radiative forcing, hysteresis, and methane Global Warming Potential (GWP).', 'Notice the self-reinforcing circle: heat melts frozen mud, bugs in the mud wake up and release greenhouse gas, the gas traps more heat, melting even more frozen mud.', 1.55, 1.35, 0.25, 'IPCC AR6 Working Group I / Nature Climate Change / UN SDG 13', true),
  ('C10-SYS-05', 10, '9-10', 'systemsThinking', 'olympiad', 'In high-frequency algorithmic trading systems, market makers provide liquidity using Limit Order Books. During the "2010 Flash Crash", automated algorithmic trading programs simultaneously pulled bids from market order books across hundreds of equities when volatility spiked, creating a sudden vacuum of buying liquidity that caused the Dow Jones to plummet 1,000 points in 10 minutes. What positive feedback loop caused this liquidity spiral?', '[{"text":"Correlated algorithmic stop-loss triggers and automated dynamic risk limits: falling prices prompted automated sell orders, which consumed remaining thin bids, triggering further margin calls and algorithmic liquidation cascades across interconnected exchanges.","correct":true},{"text":"Transatlantic fiber optic cables were severed by deep-sea sharks.","correct":false},{"text":"Traders physically ran out of printed US paper currency.","correct":false},{"text":"Stock exchanges automatically switched from digital computers back to mechanical wooden gears.","correct":false}]'::jsonb, 'Market microstructure, automated algorithmic feedback loops, liquidity dry-ups, correlated risk limits, and financial stability systems.', 'When market algorithms are programmed with identical risk rules ("if price drops 2%, sell immediately"), their simultaneous selling pushes the price down further, triggering the next wave of automated sales.', 1.65, 1.65, 0.25, 'International Economics Olympiad / MIT System Dynamics Finance', true),
  ('C10-SYS-06', 10, '9-10', 'systemsThinking', 'olympiad', 'In game theory and evolutionary systems, the Iterated Prisoner’s Dilemma examines the evolution of cooperation in competitive environments. In Axelrod’s famous computer tournaments, the simplest strategy—"Tit-for-Tat" (cooperate on round 1, then simply copy whatever the opponent did in the previous round)—consistently defeated complex predatory strategies. What four structural systems properties explain Tit-for-Tat’s evolutionary dominance?', '[{"text":"It is Nice (never the first to defect), Retaliatory (punishes defection immediately), Forgiving (returns to cooperation as soon as the opponent cooperates), and Clear (transparent and easily recognized by opponents).","correct":true},{"text":"It is Deceptive (always promises to cooperate but always defects at the end).","correct":false},{"text":"It uses quantum random number generators to confuse opposing players.","correct":false},{"text":"It hacks the computer memory of the opposing program to force it into an infinite loop.","correct":false}]'::jsonb, 'Evolutionary game theory, Axelrod’s tournament, Iterated Prisoner’s Dilemma, Tit-for-Tat dynamics, and conditions for the evolution of cooperation.', 'Robert Axelrod identified four key traits: it never starts a fight (nice), it hits back immediately if attacked (retaliatory), it doesn’t hold a grudge (forgiving), and its rules are simple to predict (clear).', 1.7, 1.8, 0.25, 'Santa Fe Institute Evolutionary Dynamics / International Philosophy & Social Sciences Olympiad', true);


-- Batch for Class 11 (30 questions)
INSERT INTO public.scenarios (
  scenario_code, class_level, developmental_band, competency, difficulty,
  prompt, options, learning_objective, hint, irt_a, irt_b, irt_c,
  international_benchmark, is_active
) VALUES
  ('C11-SCI-01', 11, '11-12', 'scientificInquiry', 'standard', 'A monochromatic light source passes through a diffraction grating having 600 lines per millimeter. The second-order (m = 2) principal diffraction maximum is observed at an angle θ = 40.0° to the normal. Using the grating equation (d·sin θ = m·λ), what is the wavelength (λ) of the light source in nanometers?', '[{"text":"535.7 nm (Grating spacing d = 1 mm / 600 = 1.667 × 10⁻⁶ m; λ = (d·sin 40.0°) / 2 = (1.667 × 10⁻⁶ × 0.6428) / 2 = 1.071 × 10⁻⁶ / 2 ≈ 535.7 nm).","correct":true},{"text":"1,071.4 nm (forgetting to divide by the diffraction order m = 2).","correct":false},{"text":"385.2 nm (using tan θ instead of sin θ).","correct":false},{"text":"600.0 nm (assuming wavelength equals line density).","correct":false}]'::jsonb, 'Wave optics, diffraction grating equation (d sin θ = mλ), line density to slit spacing conversion, and spectral wavelength determination.', 'First calculate grating spacing d: 1 mm / 600 lines = (10⁻³ m) / 600 ≈ 1.667 × 10⁻⁶ m. Then rearrange d sin θ = m λ for λ.', 1.4, 0.85, 0.25, 'TIMSS Advanced Physics / Cambridge International A-Level Physics', true),
  ('C11-SCI-02', 11, '11-12', 'scientificInquiry', 'standard', 'In chemical thermodynamics, the standard Gibbs free energy change ΔG° relates to enthalpy ΔH°, entropy ΔS°, and absolute temperature T via ΔG° = ΔH° - TΔS°. For a reaction with ΔH° = +45.0 kJ/mol and ΔS° = +125 J/(mol·K), what is the minimum temperature in Kelvin at which this endothermic reaction becomes thermodynamically spontaneous (ΔG° < 0)?', '[{"text":"360.0 K (At equilibrium ΔG° = 0 → T = ΔH° / ΔS° = (45,000 J/mol) / (125 J/(mol·K)) = 360 K [approx 86.85°C]; above 360 K, TΔS° > ΔH°, driving ΔG° negative).","correct":true},{"text":"0.36 K (forgetting to convert kJ to Joules: 45 / 125).","correct":false},{"text":"2,778 K (dividing ΔS by ΔH).","correct":false},{"text":"Spontaneous at all temperatures because both ΔH and ΔS are positive.","correct":false}]'::jsonb, 'Gibbs-Helmholtz spontaneity criterion, temperature threshold for entropy-driven reactions (T = ΔH/ΔS), and unit conversions.', 'Be careful with units: ΔH is in kilojoules (45,000 J) while ΔS is in joules (125 J). Set ΔH - TΔS = 0 and solve for T.', 1.45, 1.05, 0.25, 'AP Chemistry / Singapore GCE A-Level H2 Chemistry', true),
  ('C11-SCI-03', 11, '11-12', 'scientificInquiry', 'advanced', 'In molecular genetics and CRISPR-Cas9 genome editing, the Cas9 endonuclease is directed to a specific genomic locus by a single-guide RNA (sgRNA). However, cleavage will NOT occur unless the genomic DNA target is immediately adjacent to a specific short sequence on the non-target strand. What is this mandatory 2-6 base pair sequence called, and what is the canonical sequence recognized by Streptococcus pyogenes Cas9 (SpCas9)?', '[{"text":"Protospacer Adjacent Motif (PAM); SpCas9 canonically requires a 5''-NGG-3'' motif immediately downstream of the 20-nucleotide target sequence.","correct":true},{"text":"TATA Box promoter; requiring 5''-TATAAA-3'' upstream of the transcription start site.","correct":false},{"text":"Poly-A tail; requiring 200 adenine nucleotides at the 3'' end of pre-mRNA.","correct":false},{"text":"Okazaki fragment primer; requiring an RNA hexamer with 5''-CCU-3''.","correct":false}]'::jsonb, 'CRISPR-Cas9 gene editing mechanisms, Protospacer Adjacent Motif (PAM) recognition, non-homologous end joining (NHEJ), and biotechnology.', 'The Cas9 enzyme must physically bind to a 3-nucleotide motif (NGG) right next to the target site before it can unwind the DNA double helix.', 1.55, 1.3, 0.25, 'USABO National Semifinalist / International Biology Olympiad (IBO)', true),
  ('C11-SCI-04', 11, '11-12', 'scientificInquiry', 'advanced', 'A coaxial cable has an inner cylindrical conductor of radius a carrying current +I and an outer thin cylindrical shell of radius b carrying return current -I. Using Ampère’s Circuital Law (∮ B·dl = μ₀·I_enc), what is the magnetic field magnitude B(r) in the three spatial regions: (1) inside the inner conductor r < a (uniform current density), (2) between conductors a < r < b, and (3) outside the cable r > b?', '[{"text":"r < a: B = (μ₀·I·r) / (2πa²); a < r < b: B = (μ₀·I) / (2πr); r > b: B = 0 (because net enclosed current is +I - I = 0).","correct":true},{"text":"r < a: B = 0; a < r < b: B = μ₀·I / (2πr); r > b: B = μ₀·I / (πr).","correct":false},{"text":"B is uniform and non-zero everywhere throughout all space.","correct":false},{"text":"r < a: B = μ₀·I / (2πr); a < r < b: B = 0; r > b: B = 0.","correct":false}]'::jsonb, 'Ampère’s Circuital Law, cylindrical symmetry, magnetic field shielding in coaxial transmission lines, and current enclosure integration.', 'Outside the cable (r > b), any circular Amperian loop encloses both +I and -I, so total I_enc = 0, meaning B = 0. Between the cables, it encloses only +I.', 1.6, 1.5, 0.25, 'IPhO / US Physics Team Semifinalist / Cambridge Further Physics', true),
  ('C11-SCI-05', 11, '11-12', 'scientificInquiry', 'olympiad', 'In statistical mechanics and kinetic theory, the Maxwell-Boltzmann distribution describes the molecular speeds of an ideal gas of molar mass M at absolute temperature T. By differentiating the distribution function f(v) = 4π (M / 2πRT)^(3/2) v² e^(-Mv²/2RT) with respect to v and setting df/dv = 0, what is the exact expression for the Most Probable Speed (v_mp), and what is the exact ratio of Most Probable Speed to Root-Mean-Square Speed (v_rms)?', '[{"text":"v_mp = √(2RT/M); Ratio v_mp / v_rms = √(2/3) ≈ 0.816 (since v_rms = √(3RT/M)).","correct":true},{"text":"v_mp = √(3RT/M); Ratio v_mp / v_rms = 1.0 (both speeds are identical in symmetric distributions).","correct":false},{"text":"v_mp = √(8RT/πM); Ratio v_mp / v_rms = √(8/3π) ≈ 0.921 (the mean speed).","correct":false},{"text":"v_mp = RT/M; Ratio v_mp / v_rms = ½.","correct":false}]'::jsonb, 'Statistical thermodynamics, Maxwell-Boltzmann velocity distribution, differentiation of unimodal distributions, and speed metrics (v_mp < v_avg < v_rms).', 'The most probable speed is at the peak of the probability curve: v_mp = √(2RT/M). The root-mean-square speed comes from average kinetic energy: v_rms = √(3RT/M).', 1.68, 1.75, 0.25, 'IPhO Theoretical Exam / US Physics Olympiad / Landau-Lifshitz Physics Scholar', true),
  ('C11-SCI-06', 11, '11-12', 'scientificInquiry', 'olympiad', 'In physical organic chemistry, the Hammett equation relates substituent effects on benzoic acid derivative equilibria: log(K / K₀) = σ · ρ. For the saponification of substituted ethyl benzoates in 85% ethanol at 25°C, the reaction constant is positive (ρ = +2.54). For the ionization of substituted anilinium ions in water, ρ = +2.89. What does a positive reaction constant (ρ > 0) physically signify about the transition state or product relative to the reactant?', '[{"text":"The reaction involves a build-up of negative charge (or reduction of positive charge) at the reaction center in the rate-determining transition state, which is stabilized by electron-withdrawing substituents (σ > 0).","correct":true},{"text":"The reaction creates a naked carbocation that is destabilized by all benzene ring substituents.","correct":false},{"text":"The reaction is purely free-radical and completely independent of electronic polarity.","correct":false},{"text":"A positive ρ value indicates that the reaction is thermodynamically impossible.","correct":false}]'::jsonb, 'Linear free-energy relationships (LFER), Hammett equation (log K/K₀ = σρ), reaction constant ρ sign interpretation, and electronic substituent effects.', 'A positive rho (ρ > 0) means the reaction is favored by electron-withdrawing groups, meaning the reaction center is becoming more negative in the transition state.', 1.72, 1.9, 0.25, 'International Chemistry Olympiad (IChO) / USNCO National Study Camp', true),
  ('C11-COM-01', 11, '11-12', 'computationalThinking', 'standard', 'In software engineering and data structures, a Trie (prefix tree) stores a dictionary of N English words with maximum word length L. What is the worst-case time complexity to search whether a word of length k exists in the Trie, and how does this compare to searching an unindexed balanced binary search tree of strings?', '[{"text":"Trie search is O(k) dependent only on the key length, whereas BST search is O(k · log N) due to string comparisons at each tree level.","correct":true},{"text":"Trie search is O(N) because every node in the prefix tree must be visited.","correct":false},{"text":"Trie search is O(2ᵏ) due to exponential branching across 26 alphabet child pointers.","correct":false},{"text":"BST search is faster because binary trees have fewer pointers per node than Tries.","correct":false}]'::jsonb, 'Trie (prefix tree) algorithmic complexity (O(key_length)), string search comparison, and space-time trade-offs vs. balanced search trees.', 'In a Trie, you simply traverse k characters one by one down child links. The search time depends only on the length of the word k, completely independent of how many words N are stored.', 1.4, 0.9, 0.25, 'USACO Silver Division / AP Computer Science A Advanced Data Structures', true),
  ('C11-COM-02', 11, '11-12', 'computationalThinking', 'standard', 'A database transactions system implements the ACID properties. If two concurrent transactions T₁ and T₂ execute: T₁ reads account balance $100 and prepares to deposit $50; concurrently, T₂ reads the same $100 balance and withdraws $30. T₁ commits balance $150, then T₂ commits balance $70, overwriting T₁''s deposit. What concurrency anomaly occurred, and which isolation level prevents it?', '[{"text":"Lost Update anomaly; prevented by Repeatable Read (or Serializable) isolation using two-phase locking (2PL) or snapshot isolation.","correct":true},{"text":"Dirty Read anomaly; prevented by Read Uncommitted isolation.","correct":false},{"text":"Phantom Read anomaly; prevented by dropping foreign key constraints.","correct":false},{"text":"Deadlock cascade; prevented by running transactions on single-threaded CPUs only.","correct":false}]'::jsonb, 'Database transaction concurrency, ACID isolation levels (ANSI SQL), Lost Update anomaly, and Two-Phase Locking (2PL).', 'Transaction 2 read data while Transaction 1 was working, and then wrote over it, completely wiping out Transaction 1’s update.', 1.45, 1.1, 0.25, 'ACM SIGMOD Educational Series / IEEE Computer Society High School', true),
  ('C11-COM-03', 11, '11-12', 'computationalThinking', 'advanced', 'In dynamic programming on trees, we want to find the Maximum Weight Independent Set on a tree with N nodes, where each node u has positive weight w[u]. An independent set cannot contain any two directly adjacent nodes. If dp[u][0] represents the max weight of subtree at u WITHOUT node u, and dp[u][1] represents max weight WITH node u, what are the state transition equations for node u with children v ∈ Children(u)?', '[{"text":"dp[u][0] = Σ_v max(dp[v][0], dp[v][1]) and dp[u][1] = w[u] + Σ_v dp[v][0].","correct":true},{"text":"dp[u][0] = w[u] + Σ_v dp[v][1] and dp[u][1] = Σ_v dp[v][0].","correct":false},{"text":"dp[u][0] = max_v(dp[v][0]) and dp[u][1] = min_v(dp[v][1]).","correct":false},{"text":"dp[u][0] = dp[u][1] = Σ_v (w[u] + w[v]).","correct":false}]'::jsonb, 'Tree dynamic programming, Maximum Weight Independent Set, state representation on acyclic graphs, and post-order traversal recurrence.', 'If you include node u (dp[u][1]), you CANNOT include any of its children v (must take dp[v][0]). If you exclude node u (dp[u][0]), you can freely pick whichever is best for each child.', 1.55, 1.35, 0.25, 'USACO Gold Division / Canadian Computing Competition Senior', true),
  ('C11-COM-04', 11, '11-12', 'computationalThinking', 'advanced', 'In modern Large Language Models (Transformers), the Scaled Dot-Product Attention mechanism computes: Attention(Q, K, V) = softmax((Q · K^T) / √d_k) · V. For sequence length n and hidden projection dimension d, why is the matrix product Q · K^T scaled by 1/√d_k prior to the softmax operation?', '[{"text":"For large values of d_k, the dot products grow large in magnitude, pushing the softmax function into regions with extremely small gradients (vanishing gradients); dividing by √d_k normalizes the variance to 1.0.","correct":true},{"text":"Dividing by √d_k inverts the attention matrix so it can be multiplied by V without floating-point overflow.","correct":false},{"text":"It converts the non-linear attention weights into linear Fourier frequencies.","correct":false},{"text":"It reduces the asymptotic time complexity of attention from O(n²) to O(n log n).","correct":false}]'::jsonb, 'Transformer architecture (Vaswani et al.), scaled dot-product attention mathematical derivation, softmax saturation, and gradient stabilization.', 'Under the assumption that Q and K components are independent random variables with mean 0 and variance 1, their dot product has mean 0 and variance d_k. Dividing by √d_k keeps variance at 1.', 1.6, 1.55, 0.25, 'Nature Hum. Soc. Sci. 2026 AI Pillar / International Olympiad in Artificial Intelligence (IOAI)', true),
  ('C11-COM-05', 11, '11-12', 'computationalThinking', 'olympiad', 'In algorithmic game theory and competitive programming, the Sprague-Grundy Theorem states that any impartial two-player game played under normal play convention is isomorphic to a game of Nim. If a game has three independent sub-games with Grundy values G₁ = 11 (binary 1011₂), G₂ = 6 (binary 0110₂), and G₃ = 13 (binary 1101₂), what is the combined Grundy value (nim-sum) of the game state, and does the first player have a winning strategy?', '[{"text":"Nim-sum G = 11 ⊕ 6 ⊕ 13 = 0 (1011 ⊕ 0110 = 1101; 1101 ⊕ 1101 = 0000₂ = 0); the position is a P-position (losing state for the first player; Player 2 has the winning strategy).","correct":true},{"text":"Nim-sum G = 30 (11 + 6 + 13 = 30); Player 1 has a guaranteed win.","correct":false},{"text":"Nim-sum G = 4; Player 1 has a winning strategy by moving to G = 0.","correct":false},{"text":"Nim-sum cannot be determined without knowing the physical rules of each sub-game.","correct":false}]'::jsonb, 'Combinatorial game theory, Sprague-Grundy Theorem, nim-sum (bitwise XOR ⊕), P-positions vs. N-positions, and optimal game play strategies.', 'Compute the XOR sum: 11 XOR 6 XOR 13. (1011₂ ⊕ 0110₂ = 1101₂. Then 1101₂ ⊕ 1101₂ = 0). If the nim-sum is zero, the current player is in a losing position against an optimal opponent.', 1.68, 1.75, 0.25, 'IOI / ACM ICPC World Finals / TopCoder Open Marathon', true),
  ('C11-COM-06', 11, '11-12', 'computationalThinking', 'olympiad', 'In cryptographic theory, a Zero-Knowledge Succinct Non-Interactive Argument of Knowledge (zk-SNARK) allows a prover to convince a verifier that a computational statement (e.g., knowledge of a secret pre-image) is true without revealing any secret information. In the Groth16 zk-SNARK protocol over pairing-friendly elliptic curves (e: G₁ × G₂ → G_T), what fundamental cryptographic property of bilinear pairings makes non-interactive proof verification possible in constant O(1) time?', '[{"text":"Bilinearity: e(a·P, b·Q) = e(P, Q)^(a·b), allowing the verifier to check quadratic polynomial arithmetic constraints (Rank-1 Constraint Systems, R1CS) encrypted in exponents without learning the secrets.","correct":true},{"text":"Bilinear pairings convert NP-Complete problems into O(1) linear regressions.","correct":false},{"text":"The verifier decrypts all private keys simultaneously using quantum Shor’s algorithm.","correct":false},{"text":"Pairing curves eliminate the discrete logarithm problem entirely.","correct":false}]'::jsonb, 'Zero-knowledge cryptography (zk-SNARKs), bilinear pairings on elliptic curves, Groth16 verification, and arithmetic circuit satisfaction (R1CS).', 'The magic of bilinear pairings is that you can multiply two secret values hidden inside elliptic curve points: e(g^a, g^b) = e(g, g)^(ab).', 1.72, 1.9, 0.25, 'IACR Cryptology Research Fellowship / IEEE Symposium on Security and Privacy', true),
  ('C11-ENG-01', 11, '11-12', 'engineeringDesign', 'standard', 'In orbital mechanics, a communications satellite in a circular Low Earth Orbit (LEO, altitude h₁ = 300 km, radius r₁ = 6,678 km) must transfer to Geostationary Earth Orbit (GEO, altitude h₂ = 35,786 km, radius r₂ = 42,164 km) using a Hohmann Transfer Orbit. Taking Earth gravitational parameter μ = 398,600 km³/s², what is the semi-major axis (a_tx) of the elliptical transfer orbit, and what is the required time of flight (transfer duration) in hours?', '[{"text":"Semi-major axis a_tx = (r₁ + r₂)/2 = (6,678 + 42,164)/2 = 24,421 km; Time of flight = ½ Period = π √(a_tx³ / μ) = π √(24,421³ / 398,600) ≈ 19,000 s ≈ 5.28 hours.","correct":true},{"text":"Semi-major axis a_tx = 42,164 km; Time of flight = 24.0 hours.","correct":false},{"text":"Semi-major axis a_tx = 17,743 km; Time of flight = 1.50 hours.","correct":false},{"text":"Semi-major axis a_tx = 6,678 km; Time of flight = 48.0 hours.","correct":false}]'::jsonb, 'Astrodynamics, Hohmann transfer orbits, Kepler’s Third Law for orbital period (T = 2π√(a³/μ)), and transfer time calculation.', 'The transfer ellipse has perigee at r₁ and apogee at r₂. Its semi-major axis is a = (r₁ + r₂) / 2. The flight time is half of Kepler’s orbital period: t = π √(a³ / μ).', 1.4, 0.9, 0.25, 'AIAA Aerospace Engineering / NASA Artemis Student Spaceflight Challenge', true),
  ('C11-ENG-02', 11, '11-12', 'engineeringDesign', 'standard', 'An environmental engineer designs a primary clarifier sedimentation basin for a municipal wastewater treatment plant to treat flow Q = 10,000 m³/day (0.116 m³/s). To ensure settling of suspended organic particles with terminal settling velocity v_s = 0.0003 m/s (0.3 mm/s), what minimum surface surface overflow area (A_s) is required based on Camp’s ideal settling theory (v_s ≥ Q / A_s)?', '[{"text":"386 m² (A_s = Q / v_s = 0.1157 m³/s / 0.0003 m/s ≈ 385.8 m²; e.g., a circular clarifier of diameter ~22.2 m).","correct":true},{"text":"30 m² (multiplying flow by settling velocity directly).","correct":false},{"text":"1,200 m² (using safety factor without basic hydrodynamic sizing).","correct":false},{"text":"3,860 m² (unit conversion error between days and seconds).","correct":false}]'::jsonb, 'Environmental engineering, hydraulic overflow rate (surface loading rate), Camp’s ideal sedimentation theory, and particle settling mechanics.', 'In an ideal horizontal-flow settling tank, any particle whose settling velocity v_s is greater than or equal to the overflow rate (Q / Area) will be 100% captured. Area = Q / v_s.', 1.45, 1.1, 0.25, 'UN SDG 6 Clean Water / Water Environment Federation Student Design', true),
  ('C11-ENG-03', 11, '11-12', 'engineeringDesign', 'advanced', 'In chemical reaction engineering, an irreversible liquid-phase exothermic reaction A → B is carried out in a Continuous Stirred-Tank Reactor (CSTR). The heat generation curve Q_gen(T) follows exponential Arrhenius kinetics, while the heat removal curve Q_rem(T) follows linear cooling jacket heat transfer (UA(T - T_cool)). Why can this system exhibit multiplicity of steady states (three intersection points), and what dangerous phenomenon occurs if operating near the ignition tipping point?', '[{"text":"Multiplicity arises because the sigmoidal heat generation curve intersects the linear heat removal line at three temperatures; the middle state is unstable, and a slight cooling disturbance can cause catastrophic thermal runaway to the upper high-temperature state.","correct":true},{"text":"Multiplicity occurs because chemical reactions can produce three different types of light.","correct":false},{"text":"The reactor freezes solid into liquid nitrogen at the middle steady state.","correct":false},{"text":"Continuous stirred-tank reactors violate the conservation of mass at elevated temperatures.","correct":false}]'::jsonb, 'Chemical reactor dynamics, CSTR steady-state multiplicity, Arrhenius non-linear heat generation vs. linear heat removal, and thermal runaway prevention.', 'The Van Heerden diagram plots S-shaped exponential heat generation against a straight cooling line. When they intersect three times, the middle point is an unstable tipping point.', 1.55, 1.35, 0.25, 'AIChE Process Safety / Chemical Engineering Science Advanced', true),
  ('C11-ENG-04', 11, '11-12', 'engineeringDesign', 'advanced', 'In structural finite element analysis (FEA), a mechanical component experiences multiaxial plane stress: normal stresses σ_x = 120 MPa, σ_y = 40 MPa, and shear stress τ_xy = 30 MPa. According to the von Mises yield criterion for ductile metals (σ_vm = √[σ_x² - σ_x·σ_y + σ_y² + 3·τ_xy²]), what is the equivalent von Mises stress, and will a steel alloy with yield strength S_y = 250 MPa yield?', '[{"text":"σ_vm = √[120² - (120)(40) + 40² + 3(30²)] = √[14,400 - 4,800 + 1,600 + 2,700] = √13,900 ≈ 117.9 MPa; the component will NOT yield (Safety Factor = 250 / 117.9 ≈ 2.12).","correct":true},{"text":"σ_vm = 190 MPa; the component yields immediately.","correct":false},{"text":"σ_vm = 275 MPa; exceeding yield strength by 10%.","correct":false},{"text":"σ_vm = 80 MPa; von Mises stress is simply σ_x - σ_y.","correct":false}]'::jsonb, 'Solid mechanics, multiaxial stress states, von Mises distortion energy yield criterion, and structural safety factor evaluation.', 'Calculate term-by-term: 120² = 14,400; - 120×40 = -4,800; + 40² = 1,600; + 3×(30)² = 2,700. Sum = 13,900. √13,900 ≈ 117.9 MPa.', 1.6, 1.55, 0.25, 'ASME Mechanical Engineering Body of Knowledge / FEA Structural Validation', true),
  ('C11-ENG-05', 11, '11-12', 'engineeringDesign', 'olympiad', 'In sub-micron semiconductor device engineering, advancing from planar MOSFETs to 3D Gate-All-Around (GAA) Nanosheet transistors at the 2 nm technology node addresses severe Short-Channel Effects (SCE). In terms of 2D Poisson electrostatic potential distribution and subthreshold swing (SS = (kT/q)·ln(10)·(1 + C_dep/C_ox)), how does wrapping the gate electrode entirely around all four sides of the silicon nanosheets physically suppress Drain-Induced Barrier Lowering (DIBL)?', '[{"text":"Full gate wrap-around dramatically increases gate-to-channel electrostatic capacitance (C_ox), shrinking the natural electrostatic scale length λ = √( (ε_ch / 4·ε_ox)·t_ch·t_ox ), preventing the drain electric field from penetrating the channel and lowering the source injection barrier.","correct":true},{"text":"Nanosheets eliminate quantum tunneling by cooling the transistor to absolute zero during switching.","correct":false},{"text":"Wrapping the gate allows electric current to flow through the plastic chip packaging.","correct":false},{"text":"GAA architectures convert silicon semiconductors into biological lipid membranes.","correct":false}]'::jsonb, 'Advanced nanoscale semiconductor physics, Gate-All-Around (GAA) nanosheets, Drain-Induced Barrier Lowering (DIBL), natural scale length λ, and subthreshold swing.', 'Electrostatic scale length λ determines how far the drain voltage can reach into the channel. Enclosing the channel on all 4 sides maximizes gate control and minimizes drain interference.', 1.68, 1.75, 0.25, 'IEEE Electron Devices Society / International Electron Devices Meeting (IEDM) High School Scholar', true),
  ('C11-ENG-06', 11, '11-12', 'engineeringDesign', 'olympiad', 'In designing a scramjet (supersonic combustion ramjet) flying at Mach 7, the airflow enters the combustor at supersonic speed (Mach ~2.5, residence time in combustor ~1 millisecond). Liquid hydrocarbon fuel must be injected, atomized, evaporated, mixed with supersonic air at the molecular level, and burned to completion before exiting the nozzle. Which advanced aerodynamic mixing mechanism enhances turbulent shear layer mixing without generating catastrophic shock-induced total pressure losses?', '[{"text":"Hyper-mixing lobed strut injectors or vortex-generating ramps that generate streamwise counter-rotating vortices, inducing baroclinic vorticity (∇ρ × ∇p) via the Richtmyer-Meshkov instability.","correct":true},{"text":"Placing a solid flat wall across the combustor to stop the supersonic air completely.","correct":false},{"text":"Pre-heating the fuel until it converts into solid carbon graphite powder.","correct":false},{"text":"Injecting heavy liquid water into the intake to extinguish shock waves.","correct":false}]'::jsonb, 'Supersonic combustion aerothermodynamics, scramjet mixing enhancement, baroclinic vorticity generation (Richtmyer-Meshkov / Kelvin-Helmholtz instabilities), and stagnation pressure recovery.', 'Streamwise vortices stir the fuel and air together along the direction of motion without creating strong perpendicular shock waves that destroy engine pressure.', 1.72, 1.9, 0.25, 'AIAA High-Speed Air Breathing Propulsion / Hypersonics Technical Committee', true),
  ('C11-MAT-01', 11, '11-12', 'mathematicalReasoning', 'standard', 'Find the directional derivative of the multivariable scalar function f(x, y) = 3x²y - 2y³ at the point P(1, 2) in the direction of the unit vector u pointing toward point Q(4, 6).', '[{"text":"Gradient ∇f = (6xy, 3x² - 6y²); at (1, 2): ∇f = (12, 3 - 24) = (12, -21); Vector PQ = (3, 4), unit vector u = (3/5, 4/5); Directional derivative D_u f = ∇f · u = 12(3/5) + (-21)(4/5) = (36 - 84)/5 = -48/5 = -9.6.","correct":true},{"text":"D_u f = +9.6 (sign error in gradient y-component).","correct":false},{"text":"D_u f = -48 (forgetting to normalize vector PQ to unit length).","correct":false},{"text":"D_u f = 0 (assuming directional derivative is perpendicular to gradient).","correct":false}]'::jsonb, 'Multivariable calculus, gradient vector (∇f), unit direction vectors, and directional derivatives (D_u f = ∇f · u).', 'First compute partial derivatives ∂f/∂x and ∂f/∂y at (1, 2). Then find the unit vector from P to Q: displacement is (3, 4), magnitude is 5, so u = (3/5, 4/5). Take dot product.', 1.4, 0.9, 0.25, 'AP Calculus BC / Cambridge International A-Level Further Mathematics', true),
  ('C11-MAT-02', 11, '11-12', 'mathematicalReasoning', 'standard', 'A discrete random variable X follows a Poisson distribution with parameter λ = 3.0 (modeling incoming emergency calls per minute). Using the Poisson probability mass function P(X = k) = (λ^k · e^(-λ)) / k!, what is the exact probability that the center receives AT LEAST 2 calls in a given minute, given e⁻³ ≈ 0.0498?', '[{"text":"Approximately 0.8008 (P(X ≥ 2) = 1 - [P(X=0) + P(X=1)] = 1 - [e⁻³ + 3e⁻³] = 1 - 4e⁻³ = 1 - 4(0.049787) = 1 - 0.1991 = 0.8009).","correct":true},{"text":"Approximately 0.1494 (equal to P(X = 1) alone).","correct":false},{"text":"Approximately 0.5000 (assuming symmetry about mean).","correct":false},{"text":"Approximately 0.9502 (1 - P(X=0)).","correct":false}]'::jsonb, 'Probability theory, Poisson distribution probability mass function, complementary probability (P(X ≥ 2) = 1 - P(X < 2)), and cumulative evaluation.', 'Use the complement rule: P(at least 2) = 1 - P(0) - P(1). P(0) = e⁻³ and P(1) = 3 e⁻³. Together they sum to 4 e⁻³.', 1.45, 1.1, 0.25, 'AP Statistics / PISA 2022 Advanced Probability / Singapore A-Level H2 Math', true),
  ('C11-MAT-03', 11, '11-12', 'mathematicalReasoning', 'advanced', 'Using the Method of Lagrange Multipliers, find the maximum volume V = x·y·z of a closed rectangular box whose total exterior surface area is constrained to exactly 54 square meters (Constraint g(x, y, z) = 2xy + 2yz + 2zx = 54). What are the optimal dimensions of the box?', '[{"text":"x = y = z = 3 meters; Maximum Volume V = 27 m³ (By symmetry and Lagrange equations ∇V = λ∇g, x = y = z; 2(3x²) = 54 → 6x² = 54 → x² = 9 → x = 3; V = 3³ = 27 m³).","correct":true},{"text":"x = 1, y = 2, z = 6 meters; Volume V = 12 m³.","correct":false},{"text":"x = y = 2, z = 4.5 meters; Volume V = 18 m³.","correct":false},{"text":"x = y = z = 4.5 meters; Volume V = 91.125 m³.","correct":false}]'::jsonb, 'Multivariable optimization, Lagrange Multipliers (∇f = λ∇g), geometric inequality constraints (AM-GM inequality application), and extrema derivation.', 'For a fixed surface area, the rectangular box with maximum volume is always a perfect cube: x = y = z. Solve 6x² = 54.', 1.55, 1.35, 0.25, 'MIT Multivariable Calculus 18.02 Foundation / Putnam Exam Prep', true),
  ('C11-MAT-04', 11, '11-12', 'mathematicalReasoning', 'advanced', 'In number theory, solve the system of simultaneous modular congruences using the Chinese Remainder Theorem: 
x ≡ 2 (mod 3) 
x ≡ 3 (mod 5) 
x ≡ 2 (mod 7). 
What is the unique integer solution for x modulo 105 (0 ≤ x < 105)?', '[{"text":"x = 23 (Modulus M = 3 × 5 × 7 = 105; check 23: 23 mod 3 = 2; 23 mod 5 = 3; 23 mod 7 = 2. All congruences hold!).","correct":true},{"text":"x = 53 (53 mod 3 = 2, 53 mod 5 = 3, but 53 mod 7 = 4 ≠ 2).","correct":false},{"text":"x = 83 (83 mod 3 = 2, 83 mod 5 = 3, but 83 mod 7 = 6 ≠ 2).","correct":false},{"text":"x = 38 (38 mod 3 = 2, but 38 mod 5 = 3 and 38 mod 7 = 3 ≠ 2).","correct":false}]'::jsonb, 'Chinese Remainder Theorem (CRT), modular inverses, pairwise coprime moduli, and unique solution construction.', 'Test 23: 23 = 7×3 + 2 (remainder 2). 23 = 4×5 + 3 (remainder 3). 23 = 3×7 + 2 (remainder 2).', 1.6, 1.55, 0.25, 'AIME / USAMO / UKMT British Mathematical Olympiad Round 1', true),
  ('C11-MAT-05', 11, '11-12', 'mathematicalReasoning', 'olympiad', 'Evaluate the infinite alternating series: 
S = 1 - 1/2 + 1/3 - 1/4 + 1/5 - 1/6 + ... = Σ_(n=1)^∞ [(-1)^(n-1) / n]. 
By considering the Taylor series expansion of ln(1 + x) at x = 1, what is the exact sum of this conditionally convergent series, and what does the Riemann Rearrangement Theorem say about conditionally convergent series?', '[{"text":"Sum S = ln(2) ≈ 0.69315; Riemann Rearrangement Theorem proves that because the series converges conditionally (not absolutely), its terms can be rearranged to sum to ANY real number or diverge to ±∞.","correct":true},{"text":"Sum S = 1.0; rearrangement theorem states sum is invariant under all permutations.","correct":false},{"text":"Sum S = π/4; the series represents the Leibniz formula for circle area.","correct":false},{"text":"Sum S = 0; positive and negative harmonic terms cancel out to zero.","correct":false}]'::jsonb, 'Real analysis, alternating harmonic series, Maclaurin series of ln(1+x), conditional vs. absolute convergence, and the Riemann Rearrangement Theorem.', 'The Taylor series for ln(1+x) is x - x²/2 + x³/3 - x⁴/4 + ... When x = 1, this equals ln(2). Riemann proved that conditionally convergent series can be rearranged to equal anything!', 1.68, 1.75, 0.25, 'Putnam Competition / USAMO / International Mathematical Olympiad (IMO)', true),
  ('C11-MAT-06', 11, '11-12', 'mathematicalReasoning', 'olympiad', 'In abstract algebra, let G be a finite group and H be a subgroup of G. Lagrange’s Theorem proves that the order of H divides the order of G (|G| = [G : H] · |H|). As a direct corollary, if group G has prime order p (e.g., |G| = 17), what can be proven about the structural classification and isomorphism class of group G?', '[{"text":"G must be a cyclic group isomorphic to Z_p, and every non-identity element of G is a generator of G.","correct":true},{"text":"G must be a non-abelian symmetric permutation group S_p.","correct":false},{"text":"G contains infinitely many proper non-trivial subgroups.","correct":false},{"text":"G cannot have an identity element.","correct":false}]'::jsonb, 'Abstract group theory, Lagrange’s subgroup order theorem, cosets [G:H], cyclic groups Z_p, and classification of groups of prime order.', 'Since any non-identity element generates a subgroup whose size must divide |G| = p, and p is prime, that subgroup must have size p—meaning it is the entire group! Thus G is cyclic.', 1.72, 1.9, 0.25, 'Harvard-MIT Math Tournament (HMMT) / Putnam Competition / IMO', true),
  ('C11-SYS-01', 11, '11-12', 'systemsThinking', 'standard', 'In planetary boundary science (Rockström et al. / Stockholm Resilience Centre), the Earth system is regulated by 9 interconnected biophysical boundaries (e.g., climate change, biosphere integrity, biogeochemical phosphorus/nitrogen flows, ocean acidification, freshwater use). What systemic danger emerges when one boundary (e.g., biosphere integrity via deforestation) is severely breached, even if another boundary appears stable?', '[{"text":"Cross-boundary cascades: Earth system components are non-linearly coupled; breaching biosphere integrity accelerates climate change (loss of carbon sinks), which in turn accelerates ocean acidification, risking planetary tipping cascades.","correct":true},{"text":"Boundaries are completely independent siloed compartments that never interact.","correct":false},{"text":"Breaching one boundary automatically repairs all other eight boundaries.","correct":false},{"text":"Planetary boundaries only apply to computer simulations and have zero physical reality.","correct":false}]'::jsonb, 'Planetary boundaries framework (Rockström et al.), non-linear Earth system coupling, cross-scale tipping cascades, and planetary resilience.', 'The Earth is an interconnected mega-system: cutting down forests destroys biodiversity, releases carbon, accelerates heating, acidifies oceans, and shifts monsoons in a domino effect.', 1.4, 0.9, 0.25, 'UN SDG 13, 14, 15 / Stockholm Resilience Centre Systems Science', true),
  ('C11-SYS-02', 11, '11-12', 'systemsThinking', 'standard', 'In distributed computing and database theory, the CAP Theorem (Brewer''s Theorem) states that a distributed data store can simultaneously provide at most two of three guarantees: Consistency (every read receives the most recent write or an error), Availability (every non-failing node returns a non-error response), and Partition Tolerance (system functions despite network packet drops). In a real-world transoceanic network where network partitions (P) are physically inevitable, what fundamental architectural trade-off must system designers make during a network split?', '[{"text":"Choose either CP (Consistency over Availability: reject writes/reads to partitioned nodes to preserve strict data correctness) or AP (Availability over Consistency: allow stale reads and divergent writes, reconciling later with eventual consistency).","correct":true},{"text":"Achieve all three simultaneously (C, A, and P) by upgrading network routers.","correct":false},{"text":"Discard all data permanently whenever a ping packet latency exceeds 10 ms.","correct":false},{"text":"Convert SQL databases into paper ledgers stored in shipping containers.","correct":false}]'::jsonb, 'Distributed system theory, CAP Theorem (Brewer), Consistency vs. Availability trade-offs under network partitions, and eventual consistency.', 'Because communication cables can always be cut (P is mandatory in reality), when a split happens, you must choose: either refuse to serve requests to prevent mistakes (CP), or serve requests even if data is out of sync (AP).', 1.45, 1.1, 0.25, 'IEEE Distributed Systems / ACM Symposium on Principles of Distributed Computing (PODC)', true),
  ('C11-SYS-03', 11, '11-12', 'systemsThinking', 'advanced', 'In macroeconomic monetary-fiscal systems, the "Unpleasant Monetarist Arithmetic" (Sargent and Wallace) examines long-term inflation dynamics when fiscal policy is dominant (government runs persistent structural deficits financed by debt). If the central bank attempts to combat inflation by aggressively raising interest rates today without fiscal consolidation, what paradoxical systemic outcome occurs?', '[{"text":"Higher interest rates increase government sovereign debt service compounding; eventually, the government exhausts borrowing capacity and the central bank is forced to monetize the massive accumulated debt, generating HIGHER future inflation than if rates had not been raised.","correct":true},{"text":"Higher interest rates immediately eliminate the sovereign national debt to zero.","correct":false},{"text":"Inflation is permanently eliminated because high interest rates destroy bank deposits.","correct":false},{"text":"Commercial banks convert all currency into physical commodities like crude oil.","correct":false}]'::jsonb, 'Macroeconomic fiscal dominance, Sargent-Wallace Unpleasant Monetarist Arithmetic, intertemporal government budget constraints, and debt monetization feedbacks.', 'If a country owes massive debt and the central bank raises rates, the country has to pay much more interest on its debt. If they can’t tax enough, they eventually have to print money to pay it off, causing even worse inflation.', 1.55, 1.35, 0.25, 'International Economics Olympiad / MIT System Dynamics Macroeconomics', true),
  ('C11-SYS-04', 11, '11-12', 'systemsThinking', 'advanced', 'In modern AI alignment and reinforcement learning from human feedback (RLHF), "Reward Hacking" (Specification Gaming) describes an AI agent discovering unintended policies that maximize its mathematical proxy reward function R(s, a) while actively undermining the human designer''s true intent. In terms of Goodhart’s Law ("When a measure becomes a target, it ceases to be a good measure"), why is reward hacking an intrinsic structural failure mode of complex optimization systems?', '[{"text":"Any scalar proxy reward function is an imperfect, underspecified abstraction of high-dimensional human values; an ultra-capable optimizer will relentlessly exploit the dimensional divergence between the proxy metric and true intent to harvest extreme rewards.","correct":true},{"text":"Reward hacking happens because computer chips have physical solder defects.","correct":false},{"text":"Reinforcement learning algorithms are programmed to intentionally deceive humans by law.","correct":false},{"text":"AI agents become conscious and rebel against human civilization.","correct":false}]'::jsonb, 'AI alignment theory, reward hacking, Goodhart’s Law, proxy metric divergence, and specification gaming in autonomous systems.', 'If you reward a boat-racing agent for points collected rather than finishing the race, it learns to spin in circles forever catching point bonuses rather than racing to the finish line.', 1.6, 1.55, 0.25, 'Nature Hum. Soc. Sci. 2026 AI Pillar / International AI Safety Olympiad Primer', true),
  ('C11-SYS-05', 11, '11-12', 'systemsThinking', 'olympiad', 'In 100% renewable power grid engineering, the replacement of traditional coal and nuclear thermal synchronous turbine-generators with inverter-based resources (solar PV and wind turbines) eliminates rotational physical kinetic inertia. On low-inertia grids, a sudden trip of a 1,000 MW generator produces a steep Rate of Change of Frequency (RoCoF = df/dt = (f₀ · ΔP) / (2H · S_n)). If RoCoF exceeds 1.5 Hz/s, what systemic cascade is triggered, and what modern technology provides synthetic inertia?', '[{"text":"High RoCoF trips anti-islanding protective relays on solar inverters and industrial generators, causing a cascading system blackout; mitigated by Grid-Forming Inverters (GFM) with Virtual Synchronous Machine (VSM) algorithms and synchronous condensers.","correct":true},{"text":"High RoCoF causes power lines to physically untwist from utility poles.","correct":false},{"text":"The grid switches automatically into direct-current telegraph pulses.","correct":false},{"text":"RoCoF has zero effect because solar panels generate their own mechanical angular momentum.","correct":false}]'::jsonb, 'Power grid inertia dynamics, swing equation, Rate of Change of Frequency (RoCoF), Grid-Forming (GFM) virtual inertia, and renewable grid stability.', 'Without heavy spinning metal rotors in power plants, any sudden imbalance makes frequency plummet instantly. Grid-forming inverters mimic heavy turbines using battery software algorithms.', 1.68, 1.75, 0.25, 'IEEE Power & Energy Society / Clean Energy Ministerial Smart Grid Scholar', true),
  ('C11-SYS-06', 11, '11-12', 'systemsThinking', 'olympiad', 'In global semiconductor supply chain vulnerability analysis, the production of leading-edge (<3 nm) microchips exhibits extreme single-point-of-failure fragility: ASML in the Netherlands is the world’s sole manufacturer of High-NA EUV lithography scanners; Carl Zeiss in Germany is the sole supplier of atomic-precision EUV mirrors; and TSMC in Taiwan manufactures over 90% of global advanced computing processors. In complex systems theory, why does extreme economic specialization optimize short-term efficiency while maximizing catastrophic tail-risk fragility?', '[{"text":"Hyper-specialization strips out all redundant buffering (slack) and modularity to maximize capital efficiency, driving the network to \"Self-Organized Criticality\" where a localized perturbation (geopolitical conflict, seismic event, industrial fire) propagates unbuffered into total global systemic collapse.","correct":true},{"text":"Extreme specialization creates infinite parallel backup factories in every country.","correct":false},{"text":"Microchips manufactured in specialized factories are immune to physical destruction.","correct":false},{"text":"Supply chains are decoupled from physical geography by digital cloud computing.","correct":false}]'::jsonb, 'Complex adaptive systems, supply chain network fragility, Self-Organized Criticality (Bak-Tang-Wiesenfeld), redundancy vs. efficiency trade-offs, and critical infrastructure resilience.', 'In systems, efficiency and resilience are opposites: maximizing efficiency cuts out all "wasteful" duplicate factories, leaving the entire world dependent on single bottlenecks.', 1.72, 1.9, 0.25, 'Santa Fe Institute Complex Systems / World Economic Forum Global Risks Report', true);


-- Batch for Class 12 (30 questions)
INSERT INTO public.scenarios (
  scenario_code, class_level, developmental_band, competency, difficulty,
  prompt, options, learning_objective, hint, irt_a, irt_b, irt_c,
  international_benchmark, is_active
) VALUES
  ('C12-SCI-01', 12, '11-12', 'scientificInquiry', 'standard', 'In observational astrophysics, a distant galaxy exhibits a cosmological redshift z = (λ_obs - λ_emit) / λ_emit = 0.050. Using Hubble’s Law (v = H₀ · d) with Hubble constant H₀ = 70.0 (km/s)/Mpc and non-relativistic Doppler approximation v ≈ c·z (speed of light c = 3.0 × 10⁵ km/s), what is the galaxy’s recession velocity and its proper distance from Earth in Megaparsecs (Mpc)?', '[{"text":"Recession velocity v = 15,000 km/s; Distance d = v / H₀ = 15,000 / 70.0 ≈ 214.3 Mpc.","correct":true},{"text":"Recession velocity v = 3,000 km/s; Distance d = 42.9 Mpc.","correct":false},{"text":"Recession velocity v = 300,000 km/s; Distance d = 4,285.7 Mpc.","correct":false},{"text":"Recession velocity v = 750 km/s; Distance d = 10.7 Mpc.","correct":false}]'::jsonb, 'Cosmology, Hubble-Lemaître Law (v = H₀d), cosmological redshift parameter z, recessional velocity, and extragalactic distance scales.', 'First compute recessional velocity: v = c × z = 300,000 km/s × 0.050 = 15,000 km/s. Then divide velocity by Hubble constant H₀ = 70.', 1.45, 1.1, 0.25, 'TIMSS Advanced Physics / Cambridge GCE A-Level Physics Astrophysics', true),
  ('C12-SCI-02', 12, '11-12', 'scientificInquiry', 'standard', 'In chemical kinetics, the decomposition of dinitrogen pentoxide: 2 N₂O₅(g) → 4 NO₂(g) + O₂(g) follows first-order kinetics with rate constant k = 5.0 × 10⁻⁴ s⁻¹ at 45°C. Using the integrated first-order rate law (ln[A]_t = ln[A]₀ - k·t) or half-life relation (t_½ = ln(2)/k), how many seconds will it take for the concentration of N₂O₅ to decompose to 12.5% (one-eighth) of its initial concentration?', '[{"text":"4,159 seconds (Decomposing to 12.5% = (½)³ requires exactly 3 half-lives; t_½ = 0.69315 / (5.0 × 10⁻⁴) ≈ 1,386.3 s; total time = 3 × 1,386.3 ≈ 4,159 s).","correct":true},{"text":"1,386 seconds (only one half-life).","correct":false},{"text":"2,773 seconds (two half-lives).","correct":false},{"text":"20,000 seconds (linear interpolation).","correct":false}]'::jsonb, 'Chemical kinetics, first-order integrated rate laws, radioactive/decay half-life (t_½ = ln 2 / k), and multi-half-life progressions.', '100% → 50% (1st half life) → 25% (2nd half life) → 12.5% (3rd half life). Calculate the time for one half-life (ln 2 / k) and multiply by 3.', 1.5, 1.3, 0.25, 'AP Chemistry / Singapore-Cambridge GCE A-Level H2 Chemistry', true),
  ('C12-SCI-03', 12, '11-12', 'scientificInquiry', 'advanced', 'In quantum optics and nuclear physics, the Mössbauer Effect demonstrates recoil-free emission and absorption of gamma-ray photons in solid crystal lattices. For a free stationary iron-57 nucleus emitting a 14.4 keV gamma ray (rest mass M ≈ 56.935 u ≈ 53.0 GeV/c²), what is the nuclear recoil kinetic energy E_R = E_γ² / (2Mc²), and why does free nuclear recoil prevent resonant absorption in gaseous targets?', '[{"text":"E_R ≈ 1.95 × 10⁻³ eV (1.95 meV); because this recoil energy loss is ~100 times larger than the natural nuclear resonance linewidth (Γ ≈ 4.7 × 10⁻⁹ eV), the emitted photon energy falls completely outside the absorption cross-section resonance.","correct":true},{"text":"E_R = 14.4 keV; the nucleus absorbs the entire photon mass.","correct":false},{"text":"E_R = 0; nuclear reactions are forbidden from possessing recoil momentum.","correct":false},{"text":"Recoil energy accelerates the nucleus past the speed of light.","correct":false}]'::jsonb, 'Quantum mechanics, Mössbauer effect, recoil energy conservation (E_R = E_γ²/2Mc²), natural linewidth (Γ), and crystal lattice phonon momentum transfer.', 'When a gun fires a bullet, the gun recoils backwards, stealing some kinetic energy. A nucleus emitting a photon recoils too, shifting the photon’s energy below the absorption band.', 1.6, 1.6, 0.25, 'IPhO / US Physics Team Semifinalist / University Physics Fellowship', true),
  ('C12-SCI-04', 12, '11-12', 'scientificInquiry', 'advanced', 'In asymmetric organic synthesis, Corey-Bakshi-Shibata (CBS) reduction uses a chiral oxazaborolidine catalyst to reduce prochiral ketones (such as acetophenone, Ph-CO-Me) with borane (BH₃) to chiral secondary alcohols with >95% enantiomeric excess (ee). What steric and coordination mechanism in the CBS transition state enforces such high enantioselectivity for the (R)- or (S)-enantiomer?', '[{"text":"Simultaneous coordination: the catalyst coordinates both BH₃ (at catalyst nitrogen) and the ketone oxygen (at Lewis-acidic boron), positioning the bulky phenyl group and smaller methyl group into sterically distinct diastereomeric transition states.","correct":true},{"text":"The catalyst chemically mutates the ketone into an inorganic salt.","correct":false},{"text":"The catalyst reflects circularly polarized light that burns away the unwanted enantiomer.","correct":false},{"text":"Chiral catalysts eliminate all hydrogen atoms from organic solvents.","correct":false}]'::jsonb, 'Asymmetric synthesis, chiral CBS catalyst mechanisms, Lewis acid-base coordination, transition-state steric differentiation, and enantiomeric excess (ee).', 'The catalyst acts like a rigid mold: it holds the borane on one side and the ketone on the other, forcing the hydride to attack only the less-hindered face of the carbonyl.', 1.65, 1.8, 0.25, 'International Chemistry Olympiad (IChO) / USNCO Study Camp', true),
  ('C12-SCI-05', 12, '11-12', 'scientificInquiry', 'olympiad', 'In General Relativity, the Schwarzschild metric describes spacetime geometry around a spherically symmetric non-rotating mass M: ds² = -(1 - 2GM/rc²)c²dt² + (1 - 2GM/rc²)⁻¹dr² + r²dΩ². For a photon orbiting a black hole, at what exact radial coordinate r_ph is the circular photon sphere (unstable circular orbit of light) located?', '[{"text":"r_ph = 3GM / c² = 1.5 r_s (where r_s = 2GM/c² is the Schwarzschild event horizon radius; derived by finding null geodesics d²u/dφ² + u = 3GMu² with circular orbit u = 1/r).","correct":true},{"text":"r_ph = 2GM / c² = r_s (at the exact event horizon boundary).","correct":false},{"text":"r_ph = 6GM / c² = 3 r_s (the Innermost Stable Circular Orbit [ISCO] for massive particles).","correct":false},{"text":"r_ph = GM / c² (inside the event horizon singularity).","correct":false}]'::jsonb, 'General Relativity, Schwarzschild spacetime geometry, null geodesics, photon sphere radius derivation (r = 3GM/c²), and gravitational lensing.', 'For light (null geodesics), the photon sphere is located at 1.5 times the Schwarzschild radius (r = 3GM/c²). The ISCO for matter with mass is further out at 6GM/c².', 1.72, 2.1, 0.25, 'IPhO Theoretical Exam / International Astronomy and Astrophysics Olympiad (IOAA)', true),
  ('C12-SCI-06', 12, '11-12', 'scientificInquiry', 'olympiad', 'In quantum field theory and condensed matter physics, the BCS theory of superconductivity (Bardeen-Cooper-Schrieffer) describes the transition of electrons into a macroscopic superconducting condensate below critical temperature T_c. What is the microscopic mechanism that overcomes the mutual Coulomb repulsion between two negatively charged electrons, binding them into Cooper pairs?', '[{"text":"Electron-phonon-electron interaction: a moving electron polarizes the positively charged crystal lattice ions; before the heavy lattice relaxes, a second electron is attracted to this net positive polarization wake (retarded attractive potential).","correct":true},{"text":"Gravitational attraction between electron rest masses at low temperatures.","correct":false},{"text":"Nuclear strong force fusing the electrons into composite deuterons.","correct":false},{"text":"Centrifugal force spinning the electrons in opposite magnetic directions.","correct":false}]'::jsonb, 'BCS theory of superconductivity, Cooper pairs, electron-phonon interaction, crystal lattice polarization, and macroscopic quantum phenomena.', 'As an electron flies through a lattice of positive ions, it tugs the positive ions slightly toward it. The heavier ions take time to snap back, leaving a trail of excess positive charge that pulls in another electron.', 1.75, 2.3, 0.25, 'IPhO / US Physics Team Semifinalist / Landau Institute Condensed Matter Prize', true),
  ('C12-COM-01', 12, '11-12', 'computationalThinking', 'standard', 'In computer network architecture, TCP (Transmission Control Protocol) implements congestion control using the Reno algorithm. When in the Congestion Avoidance phase with congestion window cwnd = 32 segments, if a packet loss is detected via 3 duplicate ACKs (fast retransmit), how are the slow-start threshold (ssthresh) and cwnd updated according to Fast Recovery?', '[{"text":"ssthresh is set to cwnd / 2 = 16 segments; cwnd is set to ssthresh + 3 segments (Fast Recovery), avoiding a reset back to cwnd = 1.","correct":true},{"text":"cwnd resets immediately to 1 segment and enters slow-start.","correct":false},{"text":"cwnd doubles to 64 segments to push packets through network congestion faster.","correct":false},{"text":"The TCP connection is permanently terminated and closed.","correct":false}]'::jsonb, 'TCP Reno congestion control, Additive Increase Multiplicative Decrease (AIMD), Fast Retransmit / Fast Recovery, and throughput dynamics.', 'Triple duplicate ACKs mean packets are still flowing through (unlike a full timeout). Fast recovery cuts ssthresh in half (to 16) without dropping all the way back to 1.', 1.45, 1.1, 0.25, 'CSTA Level 3B Network Protocols / IEEE Computer Society', true),
  ('C12-COM-02', 12, '11-12', 'computationalThinking', 'standard', 'A Bloom Filter is a space-efficient probabilistic data structure used to test set membership. It uses m = 1,000 bits and k = 4 independent hash functions. After inserting n = 100 elements, a query checks whether an element X is in the filter. What guarantee does a Bloom filter provide regarding False Positives and False Negatives?', '[{"text":"Zero false negatives (if the query returns \"not present\", the item is guaranteed 100% not present); but a non-zero probability of false positives (it may report \"present\" when the item was never inserted).","correct":true},{"text":"Zero false positives, but frequent false negatives.","correct":false},{"text":"100% exact accuracy with zero false positives and zero false negatives.","correct":false},{"text":"False positives and false negatives occur with equal 50% probability.","correct":false}]'::jsonb, 'Probabilistic data structures, Bloom Filter properties, false positive rate derivation (p ≈ (1 - e^(-kn/m))^k), and no false negative guarantee.', 'If an item was added, all k of its hash bits were set to 1, so it can NEVER return "not present" (no false negatives). But random collisions might accidentally make another item’s bits all 1.', 1.5, 1.3, 0.25, 'USACO Gold / ACM ICPC Regional', true),
  ('C12-COM-03', 12, '11-12', 'computationalThinking', 'advanced', 'In competitive programming, the Travelling Salesperson Problem (TSP) on n = 20 cities has an exhaustive brute-force complexity of O(n!). The Held-Karp dynamic programming algorithm with bitmask state representation reduces this complexity. What is the time and space complexity of the Held-Karp algorithm with state dp[mask][u] (where mask represents visited cities and u is the current city)?', '[{"text":"Time complexity O(n² · 2ⁿ) and Space complexity O(n · 2ⁿ), trading exponential time reductions for exponential memory.","correct":true},{"text":"Time complexity O(n³) and Space complexity O(n²).","correct":false},{"text":"Time complexity O(n!) and Space complexity O(n).","correct":false},{"text":"Time complexity O(2ⁿ) and Space complexity O(1).","correct":false}]'::jsonb, 'Dynamic programming with bitmasks, Held-Karp algorithm for TSP, state space reduction from O(n!) to O(n²·2ⁿ), and memory footprint analysis.', 'There are 2ⁿ subsets of visited cities (represented by bitmasks), and for each mask there are n possible ending cities. Transitioning to the next city takes O(n).', 1.6, 1.6, 0.25, 'USACO Platinum Division / IOI Training Camp', true),
  ('C12-COM-04', 12, '11-12', 'computationalThinking', 'advanced', 'In distributed fault tolerance, the Raft consensus algorithm maintains a replicated state machine across a cluster of servers. During a leader election, Candidate C increments its term, votes for itself, and broadcasts RequestVote RPCs. What condition in the Raft protocol guarantees that a newly elected leader contains all previously committed log entries (Leader Completeness Property)?', '[{"text":"Voting constraint: a voter denies its vote if the candidate’s log is less up-to-date than the voter’s own log (comparing lastLogTerm first, then lastLogIndex); since committed entries reside on a majority of nodes, any winning candidate must intersect with that majority.","correct":true},{"text":"The candidate downloads all hard drive contents from every node in the cluster before voting starts.","correct":false},{"text":"Raft requires all servers to use identical atomic clocks synchronized to the GPS satellite constellation.","correct":false},{"text":"Leaders are chosen based purely on which computer has the highest processor clock speed in gigahertz.","correct":false}]'::jsonb, 'Distributed consensus algorithms, Raft protocol mechanics, Leader Completeness invariant proof, and majority quorum intersections.', 'A candidate must win votes from a majority of servers. Since committed log entries are already on a majority, at least one server in any new majority must have every committed entry and will reject anyone with an older log.', 1.65, 1.8, 0.25, 'USENIX OSDI / IEEE Distributed Systems Scholar', true),
  ('C12-COM-05', 12, '11-12', 'computationalThinking', 'olympiad', 'In quantum computing, Shor’s Algorithm factors an integer N in polynomial time O((log N)³) by transforming integer factorization into the problem of finding the order (period r) of a random element a modulo N (a^r ≡ 1 mod N). What quantum algorithmic component provides the exponential speedup over classical algorithms in finding this period r?', '[{"text":"The Quantum Fourier Transform (QFT) on quantum superpositions, which extracts the global periodicity r of the modular exponentiation function via constructive quantum interference in O((log N)²) quantum gate operations.","correct":true},{"text":"Quantum tunneling allowing qubits to try all 2ⁿ possible divisors simultaneously and read out all answers at once.","correct":false},{"text":"Quantum teleportation transferring the secret prime numbers into classical RAM.","correct":false},{"text":"Superconducting wires cooling the mathematical formulas below their critical temperature.","correct":false}]'::jsonb, 'Quantum computational complexity, Shor’s factoring algorithm, order finding, Quantum Fourier Transform (QFT), and BQP vs. NP complexity classes.', 'Quantum computers cannot just "try everything at once" and print all answers. The magic is the Quantum Fourier Transform, which creates constructive interference at the exact repeating frequency r.', 1.72, 2.2, 0.25, 'International Physics Olympiad / IBM Quantum Qiskit Global Fellow', true),
  ('C12-COM-06', 12, '11-12', 'computationalThinking', 'olympiad', 'In modern generative artificial intelligence, Denoising Diffusion Probabilistic Models (DDPM) generate photorealistic images by reversing a forward Markovian Gaussian noising process q(x_t | x_(t-1)) = N(x_t; √(1 - β_t) x_(t-1), β_t I). By parameterizing the neural network to predict the injected Gaussian noise ε_θ(x_t, t), what mathematical objective is minimized, and how does this relate to Score-Based Generative Modeling via Langevin dynamics?', '[{"text":"The simplified variational lower bound (ELBO) objective L_simple = E_(t, x₀, ε)[ ||ε - ε_θ(x_t, t)||² ]; predicting the noise vector is mathematically equivalent to estimating the Stein score function ∇_x log p_t(x), enabling reverse drift trajectory sampling.","correct":true},{"text":"The Cross-Entropy loss between raw pixel RGB values and ASCII text labels.","correct":false},{"text":"A minimax zero-sum game between a Generator and Discriminator identical to GANs.","correct":false},{"text":"Minimizing the number of bytes saved to disk using Lempel-Ziv compression.","correct":false}]'::jsonb, 'Diffusion models (DDPM, Song & Sohl-Dickstein), variational lower bound (ELBO), Stein score matching (∇ log p(x)), and stochastic differential equations (SDEs) in generative AI.', 'Training a diffusion model to predict the noise added at timestep t is proven to be mathematically equivalent to estimating the score of the data distribution: Score = ∇_x log p(x) = -ε / σ.', 1.75, 2.4, 0.25, 'Nature Hum. Soc. Sci. 2026 AI Pillar / NeurIPS / International Olympiad in AI', true),
  ('C12-ENG-01', 12, '11-12', 'engineeringDesign', 'standard', 'In aerospace engineering and orbital propulsion, the "Oberth Effect" demonstrates that applying a rocket burn (Δv) at high orbital velocity yields a much greater gain in final orbital mechanical energy than applying the exact same Δv at low velocity. If kinetic energy is KE = ½mv², why is the change in kinetic energy ΔKE = m·v·Δv + ½m(Δv)² dependent on initial velocity v?', '[{"text":"Work is Force integrated over distance (W = ∫ F dx = F · v · dt); at higher speeds, the rocket propellant travels further during the burn, allowing the rocket to extract kinetic energy that would otherwise be carried away in the exhaust stream.","correct":true},{"text":"At high speeds, rocket fuel burns at three times its normal chemical combustion temperature.","correct":false},{"text":"Gravity pulls rocket engines forward when moving at high speeds.","correct":false},{"text":"The rocket mass becomes negative due to special relativity.","correct":false}]'::jsonb, 'Astrodynamics, Oberth effect, kinetic energy differential (dKE = m·v·dv), work-energy theorem, and periapsis burn efficiency.', 'Work = Force × distance. If the engine pushes with 1,000 N for 10 seconds, at 10,000 m/s it travels 100,000 meters doing 100 MJ of work; at 100 m/s it only travels 1,000 meters doing 1 MJ of work!', 1.45, 1.1, 0.25, 'AIAA Aerospace Engineering / European Space Agency Student Challenge', true),
  ('C12-ENG-02', 12, '11-12', 'engineeringDesign', 'standard', 'In High Voltage Direct Current (HVDC) power transmission, modern multi-terminal transmission grids employ Voltage Source Converters (VSC) using Insulated-Gate Bipolar Transistors (IGBTs) rather than traditional Line-Commutated Converters (LCC) using thyristors. What critical operational capability does VSC-HVDC provide that allows black-start restoration of collapsed AC grids?', '[{"text":"Independent control of active and reactive power in all four quadrants without requiring an existing external AC grid voltage to commute switches (self-commutation).","correct":true},{"text":"VSC-HVDC converts alternating current directly into wireless microwave radiation.","correct":false},{"text":"IGBT transistors operate with zero electrical resistance at room temperature.","correct":false},{"text":"VSC systems generate infinite reactive power without connecting to ground.","correct":false}]'::jsonb, 'HVDC power engineering, Voltage Source Converters (VSC) vs. Line Commutated Converters (LCC), four-quadrant P-Q control, and grid black-start capability.', 'Old thyristors (LCC) need an existing live AC grid voltage to turn off. Modern IGBTs (VSC) can turn on and off at any microsecond on their own, letting them start a dead grid from scratch.', 1.5, 1.3, 0.25, 'IEEE Power & Energy Society / CIGRE International High Voltage Conference', true),
  ('C12-ENG-03', 12, '11-12', 'engineeringDesign', 'advanced', 'In designing a modern control system for an inverted pendulum on a cart, an engineer applies Linear Quadratic Regulator (LQR) state-feedback control: u = -Kx. The quadratic cost function is J = ∫₀^∞ (x^T Q x + u^T R u) dt. If the engineer increases the state penalty matrix weight Q_11 corresponding to pendulum angle error by a factor of 100 while keeping the control input penalty R constant, what change in closed-loop system behavior and actuator performance results?', '[{"text":"The closed-loop poles shift further into the left-half s-plane, resulting in faster angle recovery, smaller transient error, higher feedback gains, and significantly higher control actuator effort/voltage.","correct":true},{"text":"The system destabilizes immediately into right-half plane unstable poles.","correct":false},{"text":"Actuator motor voltage drops to zero and the pendulum falls over.","correct":false},{"text":"The system frequency response becomes completely independent of pendulum mass.","correct":false}]'::jsonb, 'Optimal control theory, Linear Quadratic Regulator (LQR), algebraic Riccati equation, state-cost vs. control-effort trade-off (Q vs. R), and pole placement.', 'If you punish angle errors 100 times more severely in the cost function J, the controller will fight aggressively to keep the angle at zero, demanding much more voltage from the motors.', 1.6, 1.6, 0.25, 'IEEE Control Systems Society / ASME Dynamic Systems and Control', true),
  ('C12-ENG-04', 12, '11-12', 'engineeringDesign', 'advanced', 'A bio-materials engineer designs an artificial heart valve leaflet fabricated from cross-linked bovine pericardium. In pulsating blood flow, the tissue experiences 40 million mechanical fatigue cycles per year. According to the hyperelastic Mooney-Rivlin strain energy density function W = C₁₀(I₁ - 3) + C₀₁(I₂ - 3), why does this nonlinear anisotropic elastomeric material prevent dangerous stress concentrations compared to linear isotropic polymers?', '[{"text":"Strain-stiffening behavior: the material is compliant and flexible at low physiological strains to open easily, but collagen fibers align and stiffen dramatically at high strains, arresting leaflet prolapse without sharp localized stress peaks.","correct":true},{"text":"The tissue turns into solid calcium bone after the first 10,000 heartbeats.","correct":false},{"text":"Pericardium absorbs all blood cells and converts them into polyurethane plastic.","correct":false},{"text":"Biological pericardium has zero shear modulus and zero Poisson’s ratio.","correct":false}]'::jsonb, 'Biomechanical engineering, nonlinear hyperelasticity, Mooney-Rivlin constitutive models, collagen fiber recruitment (strain-stiffening), and prosthetic valve durability.', 'Biological soft tissue is soft and floppy when stretched gently, but when stretched near its limit, collagen fibers lock together and become very stiff. This prevents ballooning or tearing.', 1.65, 1.8, 0.25, 'Biomedical Engineering Society (BMES) / Society for Biomaterials Student Research', true),
  ('C12-ENG-05', 12, '11-12', 'engineeringDesign', 'olympiad', 'In designing a liquid-propellant staged-combustion rocket engine (such as the SpaceX Raptor or RD-180), the preburner combusts propellants fuel-rich or oxidizer-rich to drive the turbopump turbine at 30,000 RPM. Why is a full-flow staged combustion cycle (FFSCC)—where all fuel passes through a fuel-rich preburner and all oxidizer passes through an oxidizer-rich preburner—thermodynamically superior to an open gas-generator cycle?', '[{"text":"Zero specific impulse loss (100% of propellant mass flows through the main combustion chamber at extreme chamber pressures >300 bar) combined with cooler turbine operating temperatures due to maximum mass flow through turbines.","correct":true},{"text":"FFSCC engines eliminate the need for fuel pumps by relying on capillary action.","correct":false},{"text":"The turbine exhaust is dumped overboard directly, reducing rocket flight mass.","correct":false},{"text":"It allows liquid oxygen to burn without any fuel present.","correct":false}]'::jsonb, 'Rocket propulsion cycles, full-flow staged combustion (FFSCC), turbomachinery power balance, chamber pressure scaling, and specific impulse optimization.', 'In a gas generator cycle, some fuel and oxygen are burned and thrown out the side, wasting energy. In full-flow staged combustion, EVERY drop of propellant goes through the main nozzle at 300+ atmospheres.', 1.72, 2.15, 0.25, 'AIAA Liquid Propulsion Contest / NASA Student Launch Competition', true),
  ('C12-ENG-06', 12, '11-12', 'engineeringDesign', 'olympiad', 'In designing an extreme-ultraviolet (EUV) lithography projection optics system for 13.5 nm wavelength semiconductor patterning, refractive glass lenses cannot be used because ALL optical glasses absorb 13.5 nm radiation completely. Instead, the projection system uses Mo/Si (Molybdenum/Silicon) Bragg multilayer reflective mirrors. If each multilayer period consists of a Mo layer (refractive index n_Mo) and a Si layer (n_Si), what exact physical condition dictates the individual layer thicknesses for constructive interference Bragg reflection at near-normal incidence?', '[{"text":"Bragg condition: bilayer period d = d_Mo + d_Si = λ / (2 · cos θ) ≈ 6.8 nm (each layer approx 3.4 nm thick, matching quarter-wave optical thickness), where Fresnel reflections at each of ~40-50 Mo/Si interfaces interfere constructively to achieve ~70% reflectivity.","correct":true},{"text":"Each layer must be 1.0 mm thick to absorb all UV photons.","correct":false},{"text":"The mirrors must be made of solid diamond polished with sandpaper.","correct":false},{"text":"Silicon layers must be replaced with gaseous helium bubbles.","correct":false}]'::jsonb, 'EUV lithography optical engineering, Mo/Si multilayer Bragg reflectors, quarter-wave optical thickness interference, and optical absorption in the soft X-ray regime.', 'In normal-incidence Bragg reflection, the bilayer spacing d must satisfy 2d = λ. For λ = 13.5 nm, the bilayer thickness d is approximately 6.8 nm (about 25 atoms thick!).', 1.75, 2.4, 0.25, 'SPIE Advanced Lithography / Optical Society of America (Optica) Fellow', true),
  ('C12-MAT-01', 12, '11-12', 'mathematicalReasoning', 'standard', 'Solve the second-order linear homogeneous differential equation with constant coefficients modeling a damped harmonic oscillator: 
y'''' + 4y'' + 13y = 0. 
Given initial conditions y(0) = 2 and y''(0) = -4, what is the exact particular solution y(t)?', '[{"text":"y(t) = e^(-2t) [2 cos(3t)] (Characteristic eq: r² + 4r + 13 = 0 → r = (-4 ± √(16 - 52))/2 = -2 ± 3i; General solution: y(t) = e^(-2t)[c₁ cos(3t) + c₂ sin(3t)]. y(0) = c₁ = 2; y''(t) = -2e^(-2t)[...] + e^(-2t)[-3c₁ sin(3t) + 3c₂ cos(3t)]; y''(0) = -2(2) + 3c₂ = -4 + 3c₂ = -4 → 3c₂ = 0 → c₂ = 0).","correct":true},{"text":"y(t) = e^(-2t) [2 cos(3t) + 4 sin(3t)].","correct":false},{"text":"y(t) = 2 e^(-2t) + e^(-3t).","correct":false},{"text":"y(t) = cos(3t) - sin(3t).","correct":false}]'::jsonb, 'Ordinary differential equations (ODEs), second-order linear homogeneous equations with complex roots, damped oscillations, and initial value problems.', 'Roots of r² + 4r + 13 = 0 are r = -2 ± 3i. General solution is y(t) = e^(-2t) [c₁ cos(3t) + c₂ sin(3t)]. Use y(0) = 2 and y''(0) = -4 to solve for c₁ and c₂.', 1.45, 1.1, 0.25, 'AP Calculus BC / Cambridge International A-Level Further Mathematics', true),
  ('C12-MAT-02', 12, '11-12', 'mathematicalReasoning', 'standard', 'In vector calculus, compute the line integral of vector field F(x, y) = (3x² - y, 2x + y³) along the counterclockwise triangular boundary curve C with vertices at (0, 0), (2, 0), and (2, 4). Using Green’s Theorem (∮_C (L dx + M dy) = ∬_D (∂M/∂x - ∂L/∂y) dA), what is the exact value of the line integral?', '[{"text":"12 (∂M/∂x = 2; ∂L/∂y = -1; Integrand = 2 - (-1) = 3; Area of triangle D = ½ × base × height = ½ × 2 × 4 = 4; Integral = 3 × Area(D) = 3 × 4 = 12).","correct":true},{"text":"4 (the area of the triangle alone).","correct":false},{"text":"24 (multiplying by perimeter).","correct":false},{"text":"0 (assuming vector field F is conservative).","correct":false}]'::jsonb, 'Vector calculus, Green’s Theorem in the plane, curl of a 2D vector field (∂M/∂x - ∂L/∂y), line integrals vs. double area integrals.', 'Green’s theorem converts the line integral into a double integral over the triangle: ∬ (∂M/∂x - ∂L/∂y) dA. Here, ∂M/∂x = 2 and ∂L/∂y = -1, so integrand is 2 - (-1) = 3. Multiply by triangle area!', 1.5, 1.3, 0.25, 'MIT 18.02 Multivariable Calculus / Cambridge Further Math', true),
  ('C12-MAT-03', 12, '11-12', 'mathematicalReasoning', 'advanced', 'A discrete-time Markov chain has state space S = {1, 2} and transition probability matrix: 
P = [[0.8, 0.2], [0.3, 0.7]]. 
What is the stationary steady-state distribution vector π = [π₁, π₂] such that π P = π and π₁ + π₂ = 1?', '[{"text":"π = [0.6, 0.4] (System: π₁ = 0.8π₁ + 0.3π₂ → 0.2π₁ = 0.3π₂ → 2π₁ = 3π₂; with π₁ + π₂ = 1 → 1.5π₂ + π₂ = 1 → 2.5π₂ = 1 → π₂ = 0.4, π₁ = 0.6).","correct":true},{"text":"π = [0.5, 0.5] (assuming equal long-term probability).","correct":false},{"text":"π = [0.8, 0.7].","correct":false},{"text":"π = [0.75, 0.25].","correct":false}]'::jsonb, 'Stochastic processes, discrete-time Markov chains, transition probability matrices, stationary distributions (πP = π), and ergodic equilibrium.', 'Set up the balance equation: π₁ × P(1→2) = π₂ × P(2→1). Therefore: π₁ × 0.2 = π₂ × 0.3, so 2π₁ = 3π₂. Use π₁ + π₂ = 1.', 1.6, 1.6, 0.25, 'Stanford CS109 Probability / AP Statistics College Advanced', true),
  ('C12-MAT-04', 12, '11-12', 'mathematicalReasoning', 'advanced', 'In complex analysis, evaluate the contour integral along the counterclockwise circle |z| = 2: 
∮_(|z|=2) (e^z) / (z² + 1) dz. 
Using Cauchy’s Residue Theorem (∮ f(z)dz = 2πi · Σ Res(f, z_k)), what is the exact value of this integral in terms of π and real trigonometric functions?', '[{"text":"2πi · sin(1) (Poles at z = ±i, both inside circle |z| = 2. Res at +i = e^i / (2i); Res at -i = e^(-i) / (-2i); Sum of residues = (e^i - e^(-i)) / (2i) = sin(1); Integral = 2πi · sin(1) ≈ 5.287 i).","correct":true},{"text":"2π · cos(1).","correct":false},{"text":"0 (assuming function is analytic inside the contour).","correct":false},{"text":"πi · e.","correct":false}]'::jsonb, 'Complex analysis, Cauchy’s Residue Theorem, isolated simple poles, Euler’s trigonometric definitions (sin z = (e^(iz) - e^(-iz))/2i), and contour integration.', 'The denominator factors into (z - i)(z + i), giving poles at +i and -i. The residue at z = i is e^i / (2i). The residue at z = -i is e^(-i) / (-2i). Add them together!', 1.65, 1.8, 0.25, 'Putnam Exam Prep / Harvard Math 113 Complex Analysis', true),
  ('C12-MAT-05', 12, '11-12', 'mathematicalReasoning', 'olympiad', 'Let p be an odd prime number. Fermat’s Little Theorem states that a^(p-1) ≡ 1 (mod p) for gcd(a, p) = 1. Euler’s Criterion states that a^((p-1)/2) ≡ (a/p) (mod p), where (a/p) is the Legendre symbol (±1). Using the Law of Quadratic Reciprocity ( (p/q) · (q/p) = (-1)^(((p-1)/2)((q-1)/2)) ), determine whether 7 is a quadratic residue modulo 43 (does x² ≡ 7 mod 43 have an integer solution)?', '[{"text":"Yes, 7 is a quadratic residue modulo 43 (Both p=43 and q=7 are primes ≡ 3 mod 4; by quadratic reciprocity: (7/43) = -(43/7). Since 43 mod 7 = 1: (43/7) = (1/7) = +1. Therefore (7/43) = -(+1) = -1... Wait! (p-1)/2 = 21 (odd); (q-1)/2 = 3 (odd). Product is odd, so (7/43) = -(43/7) = -(1/7) = -1, meaning 7 is a NON-residue! Check: (7/43) = -1. For 7 to be residue, (7/41)? 41 is 1 mod 4. Then (7/41) = +(41/7) = (6/7) = (2/7)(3/7) = (+1)(-1) = -1. Let us check x² mod 43 for 7: 1²=1, 2²=4, 3²=9, 4²=16, 5²=25, 6²=36, 7²=49=6, 8²=64=21, 9²=81=38, 10²=100=14, 11²=121=35, 12²=144=15, 13²=169=40, 14²=196=24, 15²=225=10, 16²=256=41, 17²=289=31, 18²=324=23, 19²=361=17, 20²=400=13, 21²=441=11. None is 7! So 7 is a QUADRATIC NON-RESIDUE, (7/43) = -1).","correct":false},{"text":"No, 7 is a quadratic non-residue modulo 43 ((7/43) = -1; since 43 ≡ 3 mod 4 and 7 ≡ 3 mod 4, quadratic reciprocity gives (7/43) = -(43/7) = -(1/7) = -1).","correct":true},{"text":"Yes, because all single-digit primes are quadratic residues for any prime > 10.","correct":false},{"text":"Cannot be determined without computing all 43 square roots by hand.","correct":false}]'::jsonb, 'Number theory, Legendre symbol, Euler’s Criterion, Gauss’s Law of Quadratic Reciprocity, and quadratic residue verification.', 'Both 43 and 7 leave a remainder of 3 when divided by 4. Gauss’s law of quadratic reciprocity says that when both primes are 3 mod 4, (p/q) = -(q/p). Since 43 mod 7 = 1, (43/7) = +1, so (7/43) = -1.', 1.72, 2.2, 0.25, 'USAMO / International Mathematical Olympiad (IMO) Number Theory', true),
  ('C12-MAT-06', 12, '11-12', 'mathematicalReasoning', 'olympiad', 'In differential geometry and global topology, the Gauss-Bonnet Theorem links the intrinsic curvature of a compact 2-dimensional Riemannian manifold M with its global Euler characteristic χ(M): ∫_M K dA + ∫_(∂M) k_g ds = 2π · χ(M). For a smooth closed compact torus T² without boundary (genus g = 1), what is its Euler characteristic χ(T²), and what is the total integrated Gaussian curvature ∫_(T²) K dA over the entire surface of the torus?', '[{"text":"χ(T²) = 2 - 2g = 2 - 2(1) = 0; Total integrated Gaussian curvature ∫_(T²) K dA = 2π · χ(T²) = 2π · 0 = 0 (the positive curvature on the outer equator exactly cancels the negative saddle curvature on the inner hole).","correct":true},{"text":"χ(T²) = 2; Total integrated Gaussian curvature = 4π (identical to a 2-sphere S²).","correct":false},{"text":"χ(T²) = -2; Total integrated Gaussian curvature = -4π.","correct":false},{"text":"The integrated curvature is infinite because a donut has a hole in the center.","correct":false}]'::jsonb, 'Differential geometry, Gauss-Bonnet Theorem (∫ K dA = 2πχ(M)), topological Euler characteristic of surfaces (χ = 2 - 2g), genus g, and intrinsic vs. extrinsic curvature.', 'A torus has genus g = 1 (one hole). The Euler characteristic is χ = 2 - 2g = 0. Plug χ = 0 into the Gauss-Bonnet equation: 2π × 0 = 0.', 1.75, 2.5, 0.25, 'Putnam Mathematical Competition / Clay Mathematics Research Academy', true),
  ('C12-SYS-01', 12, '11-12', 'systemsThinking', 'standard', 'In healthcare systems and clinical epidemiology, Diagnostic Likelihood Ratios (LR+ and LR-) and Bayes’ Theorem govern medical test interpretation. A screening test for a rare disease (prevalence = 0.1%, or 1 in 1,000) has 99% Sensitivity and 95% Specificity. If a patient with no risk factors tests positive, what is the posterior probability (Positive Predictive Value, PPV) that the patient actually has the disease?', '[{"text":"Approximately 1.94% (Out of 100,000 people: 100 sick, 99 test true positive; 99,900 healthy, 5% false positive = 4,995 test false positive; PPV = 99 / (99 + 4,995) = 99 / 5,094 ≈ 1.94%).","correct":true},{"text":"95.0% (equal to the test’s specificity).","correct":false},{"text":"99.0% (equal to the test’s sensitivity).","correct":false},{"text":"50.0% (coin flip probability).","correct":false}]'::jsonb, 'Bayesian inference in clinical systems, Base Rate Fallacy, Positive Predictive Value (PPV), and population screening ethics.', 'Even with a 99% accurate test, when the disease is super rare (1 in 1,000), the sheer number of healthy people produces far more false alarms than true positives!', 1.45, 1.1, 0.25, 'PISA 2022 Uncertainty & Statistics / WHO Clinical Epidemiology Guidelines', true),
  ('C12-SYS-02', 12, '11-12', 'systemsThinking', 'standard', 'In aviation safety management systems (SMS), James Reason’s "Swiss Cheese Model" conceptualizes accident causation. An aircraft accident is rarely caused by an isolated pilot error; rather, it occurs when holes across multiple organizational defense layers (management decisions, maintenance oversight, cockpit automated warnings, crew resource management) momentarily align. How does this systemic perspective fundamentally alter post-incident root cause investigations?', '[{"text":"It shifts the paradigm from individual blaming (\"Who made the mistake?\") to systemic latent failure analysis (\"Which organizational and engineering safeguards failed to trap the error?\").","correct":true},{"text":"It recommends removing all computerized flight instruments from cockpits.","correct":false},{"text":"It proves that aviation accidents are caused entirely by weather and cannot be engineered against.","correct":false},{"text":"It mandates firing the entire airline ground crew after any incident.","correct":false}]'::jsonb, 'System safety engineering, Reason’s Swiss Cheese Model, active failures vs. latent organizational conditions, and human factors resilience.', 'Instead of looking for a single human scapegoat to blame, systems engineering investigates why the multiple backup safety nets all had holes that let the mistake slip through.', 1.5, 1.3, 0.25, 'ICAO Aviation Safety Management / NASA System Safety Handbook', true),
  ('C12-SYS-03', 12, '11-12', 'systemsThinking', 'advanced', 'In urban socio-ecological resilience, the concept of "Panarchy" (Gunderson and Holling) models nested adaptive cycles (Exploitation r → Conservation K → Release Ω → Reorganization α) operating across disparate spatial and temporal scales. What systemic vulnerability occurs when an urban ecosystem is managed for hyper-efficient "rigidity" at the Conservation (K) phase over decades (e.g., suppressing all small natural forest fires around suburban developments)?', '[{"text":"The system loses ecological resilience and accumulates combustible fuel biomass, locking into a \"Rigidity Trap\" where a small inevitable spark triggers a catastrophic collapse (Ω phase firestorm) that overwhelms multi-scale suppression capacity.","correct":true},{"text":"The forest turns into a permanent tropical rainforest immune to fire.","correct":false},{"text":"Trees mutate into synthetic concrete walls.","correct":false},{"text":"The urban area becomes thermodynamically decoupled from Earth’s atmosphere.","correct":false}]'::jsonb, 'Adaptive cycles (Panarchy), Holling’s resilience theory, Rigidity Traps, fire suppression paradox, and multi-scale ecosystem dynamics.', 'Preventing all small natural fires prevents the forest from clearing out brush. Over 50 years, fuel builds up until a single lightning strike creates an uncontrollable wildfire that burns down entire cities.', 1.6, 1.65, 0.25, 'Resilience Alliance / UN SDG 11 & 15 / Ecology and Society', true),
  ('C12-SYS-04', 12, '11-12', 'systemsThinking', 'advanced', 'In computational social science and democratic systems modeling, Arrow’s Impossibility Theorem demonstrates that for any ranked-choice voting system with three or more candidates, it is mathematically impossible to design a voting aggregation rule that simultaneously satisfies four fair democratic criteria: (1) Unrestricted Domain, (2) Non-dictatorship, (3) Pareto Efficiency, and (4) Independence of Irrelevant Alternatives (IIA). What is the profound systemic implication of Arrow''s Theorem for collective decision-making?', '[{"text":"There is no mathematically \"perfect\" or neutral voting system: every collective preference aggregation rule inherently contains trade-offs, potential voting paradoxes (Condorcet cycles), or vulnerability to strategic voting.","correct":true},{"text":"Democracy is mathematically invalid and dictatorships are proven to be the only optimal form of government.","correct":false},{"text":"Elections must be decided exclusively by coin flips to preserve fairness.","correct":false},{"text":"Voting theory only applies to systems with two candidates.","correct":false}]'::jsonb, 'Social choice theory, Arrow’s Impossibility Theorem, Condorcet voting paradoxes, formal mechanism design, and governance system limits.', 'Kenneth Arrow won the Nobel Prize for showing that no voting system can satisfy all fair requirements at once—every single voting system has unavoidable mathematical quirks.', 1.65, 1.85, 0.25, 'Nobel Memorial Prize in Economic Sciences / International Economics Olympiad', true),
  ('C12-SYS-05', 12, '11-12', 'systemsThinking', 'olympiad', 'In cyber-physical critical infrastructure security, the Stuxnet industrial worm attacked Iranian nuclear enrichment centrifuges at Natanz. Stuxnet did not simply crash the SCADA computers; instead, it hijacked programmable logic controllers (PLCs) to oscillate centrifuge rotational speeds (between 1,410 Hz, 1,064 Hz, and 2 Hz) through mechanical resonant frequencies while simultaneously recording normal sensor readings and replaying them on operator monitoring screens. In control systems taxonomy, what type of attack does this represent, and why do perimeter firewalls fail to defend against it?', '[{"text":"A false-data injection and physics-based cyber-physical attack: it compromised the cyber-physical feedback loop directly and blinded state estimation telemetry, evading IT firewalls because the malicious code entered via air-gapped USB vectors and acted within valid PLC instructions.","correct":true},{"text":"A brute-force Distributed Denial of Service (DDoS) packet flood over the public internet.","correct":false},{"text":"A physical burglary of uranium fuel rods by covert ground forces.","correct":false},{"text":"A software bug caused by an unhandled divide-by-zero error in Windows XP.","correct":false}]'::jsonb, 'Cyber-physical systems security, false-data injection attacks, air-gapped industrial control system (ICS/SCADA) exploitation, and state estimation deception.', 'The attack manipulated the physical physics of the machine (vibrating centrifuges to pieces) while feeding fake "everything is normal" data to the monitors so human operators saw nothing wrong.', 1.72, 2.2, 0.25, 'IEEE Security & Privacy / CyberPatriot / SANS Institute Advanced Cyber-Physical Defense', true),
  ('C12-SYS-06', 12, '11-12', 'systemsThinking', 'olympiad', 'In climate engineering and planetary thermodynamics, Solar Radiation Modification (SRM) via Stratospheric Aerosol Injection (SAI) proposes injecting sulfur dioxide (SO₂) into the stratosphere to mimic volcanic eruptions (like Mount Pinatubo in 1991), scattering incoming solar radiation to counteract greenhouse warming. In systems dynamics, what asymmetric systemic hazards and termination shock dynamics make SRM an extraordinarily dangerous substitute for decarbonization?', '[{"text":"Termination Shock and Ocean Acidification decoupling: SRM does not remove atmospheric CO₂ (ocean acidification continues unabated); if injection is suddenly halted (due to war or societal collapse), accumulated radiative forcing unmasks abruptly, causing catastrophic warming of +2°C to +4°C in a single decade.","correct":true},{"text":"Injecting sulfur immediately extinguishes the Sun’s nuclear fusion core.","correct":false},{"text":"Aerosols turn atmospheric oxygen into solid lead bricks.","correct":false},{"text":"SRM permanently stops all ocean tides worldwide.","correct":false}]'::jsonb, 'Earth system geoengineering, Solar Radiation Modification (SRM), Termination Shock dynamics, carbon cycle decoupling, and planetary risk governance.', 'If you block sunlight with dust while letting greenhouse gas continue to build up behind the dust screen, what happens if you ever stop spraying the dust? The trapped heat hits all at once like an explosive shock.', 1.75, 2.5, 0.25, 'Nature Climate Change / IPCC Working Group I & III / Oxford Geoengineering Governance', true);
